window.CODE_INDEX = {"classes":{"BackPressedHandler":{"code":"interface BackPressedHandler {\n    fun onBackPressed(): Boolean\n}","file":"app/src/main/java/org/wikipedia/BackPressedHandler.kt","kind":"interface","line":3,"members":{"onBackPressed":[4,4]},"supers":[]},"DiscoverCard":{"alsoIn":["app/src/main/java/org/wikipedia/readinglist/compose/ReadingListsScreen.kt"],"appearsIn":[["saved","h-widgets","Screen \u00b7 composition"]],"code":"@Serializable\nclass DiscoverCard(\n    val title: PageTitle\n) : ForYouCard() {\n    override fun dismissHashCode(): Int {\n        return title.hashCode()\n    }\n}","file":"app/src/main/java/org/wikipedia/feed/model/DiscoverCard.kt","kind":"class","line":6,"members":{"dismissHashCode":[10,12],"title":[8,8]},"supers":["ForYouCard()"]},"PageFragment":{"appearsIn":[["article","h-classes","Logic \u00b7 class diagram"],["article","h-widgets","Screen \u00b7 view composition"],["article","h-sequence","Open an article and follow a link \u00b7 sequence"],["saved","h-sequence","Save an article and sync it \u00b7 sequence"]],"code":"class PageFragment : Fragment(), BackPressedHandler, CommunicationBridge.CommunicationBridgeListener, ThemeChooserDialog.Callback,\n    ReferenceDialog.Callback, WiktionaryDialog.Callback, WatchlistExpiryDialog.Callback {\n\n    interface Callback {\n        fun onPageDismissBottomSheet()\n        fun onPageLoadComplete()\n        fun onPageLoadPage(title: PageTitle, entry: HistoryEntry)\n        fun onPageInitWebView(v: ObservableWebView)\n        fun onPageShowLinkPreview(entry: HistoryEntry)\n        fun onPageLoadMainPageInForegroundTab()\n        fun onPageUpdateProgressBar(visible: Boolean)\n        fun onPageStartSupportActionMode(callback: ActionMode.Callback)\n        fun onPageHideSoftKeyboard()\n        fun onPageWatchlistExpirySelect(expiry: WatchlistExpiry)\n        fun onPageLoadError(title: PageTitle)\n        fun onPageLoadErrorBackPressed()\n        fun onPageSetToolbarElevationEnabled(enabled: Boolean)\n        fun onPageCloseActionMode()\n        fun onPageRequestEditSection(sectionId: Int, sectionAnchor: String?, title: PageTitle, highlightText: String?)\n        fun onPageRequestLangLinks(title: PageTitle, historyEntryId: Long)\n        fun onPageRequestGallery(title: PageTitle, fileName: String, wikiSite: WikiSite, revision: Long, isLeadImage: Boolean, options: ActivityOptionsCompat?)\n        fun onPageRequestAddImageTags(mwQueryPage: MwQueryPage, invokeSource: InvokeSource)\n        fun onPageRequestEditDescription(text: String?, title: PageTitle, sourceSummary: PageSummaryForEdit?,\n                                         targetSummary: PageSummaryForEdit?, action: DescriptionEditActivity.Action, invokeSource: InvokeSource)\n    }\n\n    private var campaignDialog: CampaignDialog? = null\n    private val donationReminderLauncher = registerForActivityResult(ActivityResultContracts.StartActivityForResult()) { result ->\n        if (result.resultCode == DonationReminderActivity.RESULT_OK_FROM_DONATION_REMINDER) {\n            campaignDialog?.dismiss()\n        }\n    }\n\n    private var _binding: FragmentPageBinding? = null\n    val binding get() = _binding!!\n\n    private val activeTimer = ActiveTimer()\n    private val scrollTriggerListener = WebViewScrollTriggerListener()\n    private val pageRefreshListener = OnRefreshListener {\n        webView.clearCache(true)\n        refreshPage()\n    }\n    private val pageActionItemCallback = PageActionItemCallback()\n\n    private lateinit var bridge: CommunicationBridge\n    private lateinit var leadImagesHandler: LeadImagesHandler\n    private lateinit var pageFragmentLoadState: PageFragmentLoadState\n    private lateinit var bottomBarHideHandler: ViewHideHandler\n    internal var articleInteractionEvent: ArticleInteractionEvent? = null\n    private var pageRefreshed = false\n    private var errorState = false\n    private var scrolledUpForThemeChange = false\n    private var references: PageReferences? = null\n    private var avPlayer: AvPlayer? = null\n    private var avCallback: AvCallback? = null\n    private var sections: MutableList<Section>? = null\n    private var editCount = 0\n    private var app = WikipediaApp.instance\n\n    override lateinit var linkHandler: LinkHandler\n    override lateinit var webView: ObservableWebView\n    override var model = PageViewModel()\n    override val toolbarMargin get() = (requireActivity() as PageActivity).getToolbarMargin()\n    override val isPreview get() = false\n    override val referencesGroup get() = references?.referencesGroup\n    override val selectedReferenceIndex get() = references?.selectedIndex ?: 0\n    override var messageCardHeight: Float = 0f\n\n    lateinit var sidePanelHandler: SidePanelHandler\n    lateinit var shareHandler: ShareHandler\n    lateinit var editHandler: EditHandler\n    var revision = 0L\n\n    private val shouldCreateNewTab get() = currentTab.backStack.isNotEmpty()\n    private val backgroundTabPosition get() = 0.coerceAtLeast(foregroundTabPosition - 1)\n    private val foregroundTabPosition get() = app.tabList.size\n    private val tabLayoutOffsetParams get() = LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, binding.pageActionsTabLayout.height)\n    val currentTab get() = app.tabList.last()\n    val title get() = model.title\n    val page get() = model.page\n    val isLoading get() = bridge.isLoading\n    val leadImageEditLang get() = leadImagesHandler.callToActionEditLang\n\n    override fun onCreateView(inflater: LayoutInflater, container: ViewGroup?, savedInstanceState: Bundle?): View {\n        _binding = FragmentPageBinding.inflate(inflater, container, false)\n        webView = binding.pageWebView\n        initWebViewListeners()\n        binding.pageRefreshContainer.scrollableChild = webView\n        binding.pageRefreshContainer.setOnRefreshListener(pageRefreshListener)\n        val swipeOffset = DimenUtil.getContentTopOffsetPx(requireActivity()) + REFRESH_SPINNER_ADDITIONAL_OFFSET\n        binding.pageRefreshContainer.setProgressViewOffset(false, -swipeOffset, swipeOffset)\n        binding.pageActionsTabLayout.callback = pageActionItemCallback\n        savedInstanceState?.let {\n            scrolledUpForThemeChange = it.getBoolean(ARG_THEME_CHANGE_SCROLLED, false)\n        }\n        return binding.root\n    }\n\n    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {\n        super.onViewCreated(view, savedInstanceState)\n        callback()?.onPageInitWebView(webView)\n        updateFontSize()\n\n        // Explicitly set background color of the WebView (independently of CSS, because\n        // the background may be shown momentarily while the WebView loads content,\n        // creating a seizure-inducing effect, or at the very least, a migraine with aura).\n        val activity = requireActivity()\n        webView.setBackgroundColor(ResourceUtil.getThemedColor(activity, R.attr.paper_color))\n        bridge = CommunicationBridge(this)\n        setupMessageHandlers()\n\n        binding.pageError.retryClickListener = View.OnClickListener { refreshPage() }\n        binding.pageError.backClickListener = View.OnClickListener {\n            if (!onBackPressed()) {\n                callback()?.onPageLoadErrorBackPressed()\n            }\n        }\n\n        bottomBarHideHandler = ViewHideHandler(binding.pageActionsTabContainer, null, Gravity.BOTTOM, updateElevation = false) { false }\n        bottomBarHideHandler.setScrollView(webView)\n        bottomBarHideHandler.enabled = Prefs.readingFocusModeEnabled\n\n        webView.addOnScrollChangeListener { _, scrollY, _ ->\n            if (scrollY > (DimenUtil.roundedDpToPx(webView.contentHeight.toFloat()) - (DimenUtil.displayHeightPx * 2)) &&\n                !model.isReadMoreLoaded) {\n                bridge.execute(JavaScriptActionHandler.appendReadMode(model))\n                model.isReadMoreLoaded = true\n            }\n        }\n\n        editHandler = EditHandler(this, bridge)\n        sidePanelHandler = SidePanelHandler(this, bridge)\n        leadImagesHandler = LeadImagesHandler(this, webView, binding.pageHeaderView, callback())\n        shareHandler = ShareHandler(this, bridge)\n        pageFragmentLoadState = PageFragmentLoadState(model, this, webView, bridge, leadImagesHandler, currentTab)\n\n        if (callback() != null) {\n            LongPressHandler(webView, HistoryEntry.SOURCE_INTERNAL_LINK, PageContainerLongPressHandler(this))\n        }\n\n        if (shouldLoadFromBackstack(activity) || savedInstanceState != null) {\n            reloadFromBackstack()\n        }\n    }\n\n    override fun onSaveInstanceState(outState: Bundle) {\n        super.onSaveInstanceState(outState)\n        outState.putBoolean(ARG_THEME_CHANGE_SCROLLED, scrolledUpForThemeChange)\n    }\n\n    override fun onDestroyView() {\n        avPlayer?.let {\n            it.deinit()\n            avPlayer = null\n        }\n        // uninitialize the bridge, so that no further JS events can have any effect.\n        bridge.cleanup()\n        sidePanelHandler.log()\n        leadImagesHandler.dispose()\n        webView.clearAllListeners()\n        (webView.parent as ViewGroup).removeView(webView)\n        Prefs.isSuggestedEditsHighestPriorityEnabled = false\n        _binding = null\n        super.onDestroyView()\n    }\n\n    override fun onPause() {\n        super.onPause()\n        bridge.execute(JavaScriptActionHandler.pauseAllMedia())\n        if (avPlayer?.isPlaying == true) {\n            avPlayer?.stop()\n            updateProgressBar(false)\n        }\n        activeTimer.pause()\n        addTimeSpentReading(activeTimer.elapsedSec)\n        pageFragmentLoadState.updateCurrentBackStackItem()\n        app.commitTabState()\n        val time = if (app.tabList.size >= 1 && !pageFragmentLoadState.backStackEmpty()) System.currentTimeMillis() else 0\n        Prefs.pageLastShown = time\n        articleInteractionEvent?.pause()\n    }\n\n    override fun onResume() {\n        super.onResume()\n        activeTimer.resume()\n        val params = CoordinatorLayout.LayoutParams(1, 1)\n        binding.pageImageTransitionHolder.layoutParams = params\n        binding.pageImageTransitionHolder.visibility = View.GONE\n        binding.pageActionsTabLayout.update()\n        updateQuickActionsAndMenuOptions()\n        if (ImageUrlUtil.isGif(page?.leadImageUrl)) {\n            leadImagesHandler.loadLeadImage()\n        }\n        articleInteractionEvent?.resume()\n        DonationReminderHelper.maybeShowSettingSnackbar(requireActivity())\n    }\n\n    override fun onConfigurationChanged(newConfig: Configuration) {\n        super.onConfigurationChanged(newConfig)\n        // if the screen orientation changes, then re-layout the lead image container,\n        // but only if we've finished fetching the page.\n        if (!bridge.isLoading && !errorState) {\n            pageFragmentLoadState.onConfigurationChanged()\n        }\n    }\n\n    override fun onBackPressed(): Boolean {\n        articleInteractionEvent?.logBackClick()\n        if (sidePanelHandler.isVisible) {\n            sidePanelHandler.hide()\n            return true\n        }\n        if (pageFragmentLoadState.goBack()) {\n            return true\n        }\n        // if the current tab can no longer go back, then close the tab before exiting\n        if (app.tabList.isNotEmpty()) {\n            app.tabList.removeAt(app.tabList.size - 1)\n            app.commitTabState()\n        }\n        return false\n    }\n\n    override fun onToggleDimImages() {\n        ActivityCompat.recreate(requireActivity())\n    }\n\n    override fun onToggleReadingFocusMode() {\n        webView.scrollEventsEnabled = false\n        bottomBarHideHandler.enabled = Prefs.readingFocusModeEnabled\n        leadImagesHandler.refreshCallToActionVisibility()\n        page?.let {\n            bridge.execute(JavaScriptActionHandler.setUpEditButtons(!Prefs.readingFocusModeEnabled, !it.canEdit))\n        }\n        // We disable and then re-enable scroll events coming from the WebView, because toggling\n        // reading focus mode within the article could actually change the dimensions of the page,\n        // which will cause extraneous scroll events to be sent.\n        binding.root.postDelayed({\n            if (isAdded) {\n                webView.scrollEventsEnabled = true\n            }\n        }, 250)\n    }\n\n    override fun onCancelThemeChooser() {\n        if (scrolledUpForThemeChange) {\n            val animDuration = 250L\n            ObjectAnimator.ofInt(webView, \"scrollY\", webView.scrollY, 0)\n                .setDuration(animDuration)\n                .start()\n        }\n    }\n\n    override fun onEditingPrefsChanged() { }\n\n    override fun wiktionaryShowDialogForTerm(term: String) {\n        shareHandler.showWiktionaryDefinition(term)\n    }\n\n    override fun onExpiryChanged(expiry: WatchlistExpiry) {\n        callback()?.onPageWatchlistExpirySelect(expiry)\n        dismissBottomSheet()\n    }\n\n    private fun shouldLoadFromBackstack(activity: Activity): Boolean {\n        return (activity.intent != null && (PageActivity.ACTION_RESUME_READING == activity.intent.action ||\n                activity.intent.hasExtra(Constants.INTENT_APP_SHORTCUT_CONTINUE_READING)))\n    }\n\n    private fun initWebViewListeners() {\n        webView.addOnUpOrCancelMotionEventListener {\n            // update our session, since it's possible for the user to remain on the page for\n            // a long time, and we wouldn't want the session to time out.\n            app.appSessionEvent.touchSession()\n        }\n        webView.addOnContentHeightChangedListener(scrollTriggerListener)\n        webView.webViewClient = object : OkHttpWebViewClient() {\n\n            override val model get() = this@PageFragment.model\n\n            override val linkHandler get() = this@PageFragment.linkHandler\n\n            override fun onPageFinished(view: WebView, url: String) {\n                bridge.evaluateImmediate(\"(function() { return (typeof pcs !== 'undefined'); })();\") { pcsExists ->\n                    if (!isAdded) {\n                        return@evaluateImmediate\n                    }\n                    // TODO: This is a bit of a hack: If PCS does not exist in the current page, then\n                    // it's implied that this page was loaded via Mobile Web (e.g. the Main Page) and\n                    // doesn't support PCS, meaning that we will never receive the `setup` event that\n                    // tells us the page is finished loading. In such a case, we must infer that the\n                    // page has now loaded and trigger the remaining logic ourselves.\n                    if (\"true\" != pcsExists) {\n                        if (WikipediaApp.instance.currentTheme.isDark) {\n                            // TODO: remove when mobile web supports automatic dark mode through\n                            // the `prefers-color-scheme` media query.\n                            bridge.execute(JavaScriptActionHandler.mobileWebSetDarkMode())\n                        }\n                        onPageSetupEvent()\n                        bridge.onMetadataReady()\n                        bridge.onPcsReady()\n                        bridge.execute(JavaScriptActionHandler.mobileWebChromeShim(DimenUtil.roundedPxToDp(((requireActivity() as AppCompatActivity).supportActionBar?.height ?: 0).toFloat()),\n                            DimenUtil.roundedPxToDp(binding.pageActionsTabLayout.height.toFloat())))\n\n                        // In the case of certain types of namespaces, especially pages with a lot of interactivity\n                        // that we can't control, we need to bounce them out explicitly to an external\n                        // browser, even after the page is fully loaded into our WebView. This is because\n                        // we can determine the namespace only after the loading sequence is in progress.\n                        if (model.page?.summary?.ns == Namespace.EVENT) {\n                            model.title?.let {\n                                UriUtil.visitInExternalBrowser(requireActivity(), it.uri.toUri())\n                                binding.root.post {\n                                    if (isAdded) {\n                                        requireActivity().onBackPressedDispatcher.onBackPressed()\n                                    }\n                                }\n                            }\n                        }\n                        callback()?.onPageLoadComplete()\n                    }\n                }\n            }\n\n            override fun onReceivedHttpError(view: WebView, request: WebResourceRequest, errorResponse: WebResourceResponse) {\n                if (!request.url.toString().contains(RestService.PAGE_HTML_ENDPOINT)) {\n                    // If the request is anything except the main mobile-html content request, then\n                    // don't worry about any errors and let the WebView deal with it.\n                    return\n                }\n                onPageLoadError(HttpStatusException(errorResponse.statusCode, request.url.toString(), UriUtil.decodeURL(errorResponse.reasonPhrase)))\n            }\n        }\n    }\n\n    private fun onPageSetupEvent() {\n        if (!isAdded) {\n            return\n        }\n        updateProgressBar(false)\n        webView.visibility = View.VISIBLE\n        bridge.evaluate(JavaScriptActionHandler.getRevision()) { value ->\n            if (!isAdded || value == null || value == \"null\") {\n                return@evaluate\n            }\n            try {\n                revision = value.replace(\"\\\"\", \"\").toLong()\n            } catch (e: Exception) {\n                L.e(e)\n            }\n        }\n        bridge.evaluate(JavaScriptActionHandler.getSections()) { value ->\n            if (!isAdded) {\n                return@evaluate\n            }\n            model.page?.let { page ->\n                sections = JsonUtil.decodeFromString(value)\n                sections?.let { sections ->\n                    sections.add(0, Section(0, 0, model.title?.displayText.orEmpty(), model.title?.displayText.orEmpty(), \"\"))\n                    page.sections = sections\n                }\n\n                sidePanelHandler.setupForNewPage(page)\n                sidePanelHandler.setEnabled(true)\n                model.isReadMoreLoaded = false\n            }\n        }\n        bridge.evaluate(JavaScriptActionHandler.getProtection()) { value ->\n            if (!isAdded) {\n                return@evaluate\n            }\n            model.page?.let { page ->\n                page.protection = JsonUtil.decodeFromString(value)\n                updateQuickActionsAndMenuOptions()\n            }\n        }\n    }\n\n    private fun handleInternalLink(title: PageTitle) {\n        if (!isResumed) {\n            return\n        }\n        if (title.namespace() === Namespace.USER_TALK || title.namespace() === Namespace.TALK) {\n            startTalkTopicsActivity(title)\n            return\n        } else if (title.namespace() == Namespace.CATEGORY) {\n            startActivity(CategoryActivity.newIntent(requireActivity(), title))\n            return\n        }\n\n        dismissBottomSheet()\n        val historyEntry = HistoryEntry(title, HistoryEntry.SOURCE_INTERNAL_LINK).apply {\n            prevId = model.curEntry?.id ?: -1\n        }\n\n        if (title == model.title && !title.fragment.isNullOrEmpty()) {\n            scrollToSection(title.fragment!!)\n            return\n        }\n\n        model.title?.run {\n            historyEntry.referrer = uri\n        }\n        if (title.namespace() !== Namespace.MAIN || !Prefs.isLinkPreviewEnabled) {\n            loadPage(title, historyEntry)\n        } else {\n            callback()?.onPageShowLinkPreview(historyEntry)\n        }\n    }\n\n    private fun setCurrentTabAndReset(position: Int) {\n        // move the selected tab to the bottom of the list, and navigate to it!\n        // (but only if it's a different tab than the one currently in view!\n        if (position < app.tabList.size - 1) {\n            val tab = app.tabList.removeAt(position)\n            app.tabList.add(tab)\n            pageFragmentLoadState.setTab(tab)\n        }\n        if (app.tabCount > 0) {\n            app.tabList.last().squashBackstack()\n            pageFragmentLoadState.loadFromBackStack()\n        }\n    }\n\n    private fun selectedTabPosition(title: PageTitle): Int {\n        return app.tabList.firstOrNull { it.backStackPositionTitle != null &&\n                title == it.backStackPositionTitle }?.let { app.tabList.indexOf(it) } ?: -1\n    }\n\n    private fun openInNewTab(title: PageTitle, entry: HistoryEntry, position: Int) {\n        val selectedTabPosition = selectedTabPosition(title)\n        if (selectedTabPosition >= 0) {\n            setCurrentTabAndReset(selectedTabPosition)\n            return\n        }\n        if (shouldCreateNewTab) {\n            // create a new tab\n            val tab = Tab()\n            val isForeground = position == foregroundTabPosition\n            // if the requested position is at the top, then make its backstack current\n            if (isForeground) {\n                pageFragmentLoadState.setTab(tab)\n            }\n            // put this tab in the requested position\n            app.tabList.add(position, tab)\n            trimTabCount()\n            // add the requested page to its backstack\n            tab.backStack.add(PageBackStackItem(title, entry))\n            if (!isForeground) {\n                lifecycleScope.launch(CoroutineExceptionHandler { _, t -> L.e(t) }) {\n                    ServiceFactory.get(title.wikiSite).getInfoByPageIdsOrTitles(null, title.prefixedText)\n                        .query?.firstPage()?.let { page ->\n                            WikipediaApp.instance.tabList.find { it.backStackPositionTitle == title }?.backStackPositionTitle?.apply {\n                                thumbUrl = page.thumbUrl()\n                                description = page.description\n                            }\n                        }\n                }\n            }\n            requireActivity().invalidateOptionsMenu()\n        } else {\n            pageFragmentLoadState.setTab(currentTab)\n            currentTab.backStack.add(PageBackStackItem(title, entry))\n        }\n    }\n\n    private fun dismissBottomSheet() {\n        ExclusiveBottomSheetPresenter.dismiss(childFragmentManager)\n        callback()?.onPageDismissBottomSheet()\n    }\n\n    private fun updateProgressBar(visible: Boolean) {\n        callback()?.onPageUpdateProgressBar(visible)\n    }\n\n    private fun startLangLinksActivity() {\n        val historyEntryId = model.curEntry?.id ?: -1\n        model.title?.let {\n            callback()?.onPageRequestLangLinks(it, historyEntryId)\n        }\n    }\n\n    private fun trimTabCount() {\n        while (app.tabList.size > Constants.MAX_TABS) {\n            app.tabList.removeAt(0)\n        }\n    }\n\n    private fun addTimeSpentReading(timeSpentSec: Int) {\n        model.curEntry?.let {\n            MainScope().launch(CoroutineExceptionHandler { _, throwable -> L.e(throwable) }) {\n                AppDatabase.instance.pageImagesDao().upsertForTimeSpent(it, timeSpentSec)\n            }\n\n            // Update the article visit for Donation Reminder\n            DonationReminderHelper.increaseArticleVisitCount(timeSpentSec)\n        }\n    }\n\n    private fun getContentTopOffsetParams(context: Context): LinearLayout.LayoutParams {\n        return LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, DimenUtil.getContentTopOffsetPx(context))\n    }\n\n    private fun disableActionTabs(caught: Throwable?) {\n        val offline = ThrowableUtil.isOffline(caught)\n        for (i in 0 until binding.pageActionsTabLayout.childCount) {\n            if (!offline) {\n                binding.pageActionsTabLayout.disableTab(i)\n            }\n        }\n    }\n\n    private fun startTalkTopicsActivity(title: PageTitle, stripUrlFragment: Boolean = false) {\n        val talkTitle = title.copy()\n        if (stripUrlFragment) {\n            talkTitle.fragment = null\n        }\n        startActivity(TalkTopicsActivity.newIntent(requireActivity(), talkTitle, InvokeSource.PAGE_ACTIVITY))\n    }\n\n    private fun startGalleryActivity(fileName: String) {\n        if (app.isOnline) {\n            bridge.evaluate(JavaScriptActionHandler.getElementAtPosition(DimenUtil.roundedPxToDp(webView.lastTouchX),\n                DimenUtil.roundedPxToDp(webView.lastTouchY))) { s ->\n                if (!isAdded) {\n                    return@evaluate\n                }\n                var options: ActivityOptionsCompat? = null\n\n                val hitInfo: JavaScriptActionHandler.ImageHitInfo? = JsonUtil.decodeFromString(s)\n                hitInfo?.let {\n                    val params = CoordinatorLayout.LayoutParams(\n                        DimenUtil.roundedDpToPx(it.width),\n                        DimenUtil.roundedDpToPx(it.height)\n                    )\n                    params.topMargin = DimenUtil.roundedDpToPx(it.top)\n                    params.leftMargin = DimenUtil.roundedDpToPx(it.left)\n                    binding.pageImageTransitionHolder.layoutParams = params\n                    binding.pageImageTransitionHolder.visibility = View.VISIBLE\n                    ViewUtil.loadImage(binding.pageImageTransitionHolder, it.src)\n                    GalleryActivity.setTransitionInfo(it)\n                    options = ActivityOptionsCompat.makeSceneTransitionAnimation(requireActivity(),\n                        binding.pageImageTransitionHolder, getString(R.string.transition_page_gallery))\n                }\n                webView.post {\n                    if (!isAdded) {\n                        return@post\n                    }\n                    model.title?.let {\n                        callback()?.onPageRequestGallery(it, fileName, it.wikiSite, revision, false, options)\n                    }\n                }\n            }\n        } else {\n            val snackbar = FeedbackUtil.makeSnackbar(requireActivity(), getString(R.string.gallery_not_available_offline_snackbar))\n            snackbar.setAction(R.string.gallery_not_available_offline_snackbar_dismiss) { snackbar.dismiss() }\n            snackbar.show()\n        }\n    }\n\n    private fun hidePageContent() {\n        leadImagesHandler.hide()\n        bridge.loadBlankPage()\n        webView.visibility = View.INVISIBLE\n    }\n\n    fun updateWatchlistExpiry(expiry: WatchlistExpiry) {\n        model.hasWatchlistExpiry = expiry !== WatchlistExpiry.NEVER\n    }\n\n    private fun maybeShowAnnouncement() {\n        if (!lifecycle.currentState.isAtLeast(Lifecycle.State.RESUMED)) {\n            return\n        }\n        title?.let { pageTitle ->\n            // Check if the pause time is older than 1 day.\n            val dateDiff = Duration.between(Instant.ofEpochMilli(Prefs.announcementPauseTime), Instant.now())\n            if (Prefs.hasVisitedArticlePage && dateDiff.toDays() >= 1) {\n                lifecycleScope.launch(CoroutineExceptionHandler { _, t -> L.e(t) }) {\n                    val campaignList = CampaignCollection.getActiveCampaigns()\n                    val availableCampaign = campaignList.find { campaign -> campaign.getAssetsForLang(app.appOrSystemLanguageCode) != null }\n                    availableCampaign?.let {\n                        val campaignId = it.getIdForLang(app.appOrSystemLanguageCode)\n                        if (!Prefs.announcementShownDialogs.contains(campaignId)) {\n                            DonorExperienceEvent.logAction(\"impression\", \"article_banner\", pageTitle.wikiSite.languageCode, campaignId)\n                            campaignDialog = CampaignDialog(requireActivity(), it, onNeutralButtonClick = {\n                                donationReminderLauncher.launch(DonationReminderActivity.newIntent(requireContext()))\n                            })\n                            campaignDialog?.setCancelable(false)\n                            campaignDialog?.show()\n                        }\n                    }\n                }\n            }\n        }\n    }\n\n    private fun showFindReferenceInPage(referenceAnchor: String,\n                                        backLinksList: List<String?>,\n                                        referenceText: String) {\n        model.page?.run {\n            startSupportActionMode(object : ActionMode.Callback {\n                override fun onCreateActionMode(mode: ActionMode, menu: Menu): Boolean {\n                    val menuItem = menu.add(R.string.menu_page_find_in_page)\n                    menuItem.actionProvider = FindReferenceInPageActionProvider(requireContext(), referenceAnchor, referenceText, backLinksList)\n                    menuItem.expandActionView()\n                    return true\n                }\n\n                override fun onPrepareActionMode(mode: ActionMode, menu: Menu): Boolean {\n                    mode.tag = \"actionModeFindReferenceInPage\"\n                    return false\n                }\n\n                override fun onActionItemClicked(mode: ActionMode, item: MenuItem): Boolean {\n                    return false\n                }\n\n                override fun onDestroyActionMode(mode: ActionMode) {\n                    bridge.execute(JavaScriptActionHandler.removeHighlights())\n                }\n            })\n        }\n    }\n\n    private fun setupMessageHandlers() {\n        linkHandler = object : LinkHandler(requireActivity()) {\n            override fun onPageLinkClicked(anchor: String, linkText: String) {\n                dismissBottomSheet()\n                bridge.execute(JavaScriptActionHandler.prepareToScrollTo(anchor, true))\n            }\n\n            override fun onInternalLinkClicked(title: PageTitle) {\n                handleInternalLink(title)\n            }\n\n            override fun onMediaLinkClicked(title: PageTitle) {\n                startGalleryActivity(title.prefixedText)\n            }\n\n            override fun onDiffLinkClicked(title: PageTitle, revisionId: Long) {\n                startActivity(ArticleEditDetailsActivity.newIntent(requireContext(), title, revisionId))\n            }\n\n            // ignore\n            override var wikiSite: WikiSite\n                get() = model.title?.run { wikiSite } ?: WikiSite.forLanguageCode(\"en\")\n                set(wikiSite) {\n                    // ignore\n                }\n        }\n        bridge.addListener(\"link\", linkHandler)\n        bridge.addListener(\"setup\") { _, _ -> onPageSetupEvent() }\n        bridge.addListener(\"final_setup\") { _, payload ->\n            if (!isAdded) {\n                return@addListener\n            }\n            bridge.onPcsReady()\n            articleInteractionEvent?.logLoaded()\n            callback()?.onPageLoadComplete()\n\n            JsonUtil.decodeFromElement<PageMetadata>(payload)?.let { metadata ->\n                // Persist the list of topics for this article.\n                // TODO: do something with the other bits of metadata?\n                model.curEntry?.let { entry ->\n                    if (metadata.topics.isNotEmpty()) {\n                        MainScope().launch(CoroutineExceptionHandler { _, t -> L.e(t) }) {\n                            AppDatabase.instance.pageTopicDao()\n                                .upsertForPage(entry, PageTopic.fromMetadata(entry, metadata.topics))\n                        }\n                    }\n                }\n            }\n\n            // do we have a URL fragment or highlight text to scroll to?\n            model.title?.let { prevTitle ->\n                if ((!prevTitle.fragment.isNullOrEmpty() || !model.pendingHighlightText.isNullOrEmpty()) && scrollTriggerListener.stagedScrollY == 0) {\n                    val scrollDelay = 100\n                    webView.postDelayed({\n                        if (!isAdded) {\n                            return@postDelayed\n                        }\n                        model.title?.let {\n                            jumpToHighlightOrSection(it.fragment, model.pendingHighlightText)\n                            model.pendingHighlightText = null\n                        }\n                    }, scrollDelay.toLong())\n                }\n            }\n        }\n        bridge.addListener(\"reference\") { _, messagePayload ->\n            if (!isAdded) {\n                return@addListener\n            }\n            references = JsonUtil.decodeFromElement<PageReferences>(messagePayload)\n            references?.let {\n                if (it.referencesGroup.isNotEmpty()) {\n                    showBottomSheet(ReferenceDialog())\n                }\n            }\n        }\n        bridge.addListener(\"back_link\") { _, messagePayload ->\n            messagePayload?.let { payload ->\n                val backLinks = payload[\"backLinks\"]?.jsonArray\n                if (!backLinks.isNullOrEmpty()) {\n                    val backLinksList = backLinks.map { it.jsonObject[\"id\"]?.jsonPrimitive?.content }\n                    showFindReferenceInPage(payload[\"referenceId\"]?.jsonPrimitive?.content.orEmpty(), backLinksList, payload[\"referenceText\"]?.jsonPrimitive?.content.orEmpty())\n                }\n            }\n        }\n        bridge.addListener(\"scroll_to_anchor\") { _, messagePayload ->\n            messagePayload?.let { payload ->\n                payload[\"rect\"]?.jsonObject?.let {\n                    val diffY = if (it.containsKey(\"y\")) DimenUtil.roundedDpToPx(it[\"y\"]!!.jsonPrimitive.float) else DimenUtil.roundedDpToPx(it[\"top\"]!!.jsonPrimitive.float)\n                    val offsetFraction = 3\n                    webView.scrollY = webView.scrollY + diffY - webView.height / offsetFraction\n                }\n            }\n        }\n        bridge.addListener(\"image\") { _, messagePayload ->\n            messagePayload?.let { payload ->\n                linkHandler.onUrlClick(UriUtil.decodeURL(payload[\"href\"]?.jsonPrimitive?.content.orEmpty()), payload[\"title\"]?.jsonPrimitive?.content, \"\")\n            }\n        }\n        bridge.addListener(\"media\") { _, messagePayload ->\n            messagePayload?.let { payload ->\n                linkHandler.onUrlClick(UriUtil.decodeURL(payload[\"href\"]?.jsonPrimitive?.content.orEmpty()), payload[\"title\"]?.jsonPrimitive?.content, \"\")\n            }\n        }\n        bridge.addListener(\"pronunciation\") { _, messagePayload ->\n            messagePayload?.let { payload ->\n                if (avPlayer == null) {\n                    avPlayer = AvPlayer()\n                }\n                if (avCallback == null) {\n                    avCallback = AvCallback()\n                }\n                if (!avPlayer!!.isPlaying && payload.containsKey(\"url\")) {\n                    updateProgressBar(true)\n                    avPlayer!!.play(UriUtil.resolveProtocolRelativeUrl(payload[\"url\"]?.jsonPrimitive?.content.orEmpty()), avCallback!!)\n                } else {\n                    updateProgressBar(false)\n                    avPlayer!!.stop()\n                }\n            }\n        }\n        bridge.addListener(\"footer_item\") { _, messagePayload ->\n            messagePayload?.let { payload ->\n                when (payload[\"itemType\"]?.jsonPrimitive?.content) {\n                    \"talkPage\" -> model.title?.run {\n                        articleInteractionEvent?.logTalkPageArticleClick()\n                        startTalkTopicsActivity(this, true)\n                    }\n                    \"languages\" -> startLangLinksActivity()\n                    \"lastEdited\" -> {\n                        model.title?.run {\n                            articleInteractionEvent?.logEditHistoryArticleClick()\n                            startActivity(EditHistoryListActivity.newIntent(requireContext(), this))\n                        }\n                    }\n                    \"coordinate\" -> {\n                        model.page?.let { page ->\n                            val location = page.summary.coordinates\n                            if (location != null) {\n                                PlacesEvent.logAction(\"places_click\", \"article_footer\")\n                                requireActivity().startActivity(PlacesActivity.newIntent(requireContext(), page.title, location))\n                            } else {\n                                FeedbackUtil.showMessage(this@PageFragment, getString(R.string.action_item_view_on_map_unavailable))\n                            }\n                        }\n                    }\n                    \"pageIssues\" -> {\n                        val array = payload[\"payload\"]\n                        if (array != null && array.jsonArray.isNotEmpty() && model.title != null) {\n                            val issues = array.jsonArray.mapNotNull {\n                                it.jsonObject[\"html\"]?.jsonPrimitive?.content\n                            }\n                            PageIssuesDialog(requireActivity(), model.title!!.wikiSite, issues) { url, title, linkText ->\n                                linkHandler.onUrlClick(url, title, linkText)\n                            }\n                                .setTitle(R.string.page_issues_title)\n                                .setPositiveButton(android.R.string.ok, null)\n                                .show()\n                        }\n                    }\n                    \"disambiguation\" -> {\n                        // TODO\n                        // messagePayload contains an array of URLs called \"payload\".\n                    }\n                }\n            }\n        }\n        bridge.addListener(\"read_more_titles_retrieved\") { _, _ -> }\n        bridge.addListener(\"view_license\") { _, _ ->\n            UriUtil.visitInExternalBrowser(requireContext(), Uri.parse(getString(R.string.cc_by_sa_4_url)))\n        }\n        bridge.addListener(\"view_in_browser\") { _, _ ->\n            model.title?.let {\n                UriUtil.visitInExternalBrowser(requireContext(), Uri.parse(it.uri))\n            }\n        }\n    }\n\n    fun reloadFromBackstack(forceReload: Boolean = true) {\n        if (pageFragmentLoadState.setTab(currentTab) || forceReload) {\n            if (!pageFragmentLoadState.backStackEmpty()) {\n                pageFragmentLoadState.loadFromBackStack()\n            } else {\n                callback()?.onPageLoadMainPageInForegroundTab()\n            }\n        }\n    }\n\n    fun onPageMetadataLoaded(redirectedFrom: String? = null, editCount: Int = -1) {\n        this.editCount = editCount\n        updateQuickActionsAndMenuOptions()\n        if (model.page == null) {\n            return\n        }\n        model.page?.run {\n            articleInteractionEvent = ArticleInteractionEvent(model.title?.wikiSite?.dbName()!!, summary.pageId)\n        }\n        editHandler.setPage(model.page)\n        binding.pageRefreshContainer.isEnabled = true\n        binding.pageRefreshContainer.isRefreshing = false\n        requireActivity().invalidateOptionsMenu()\n        redirectedFrom?.let {\n            FeedbackUtil.showMessage(requireActivity(), getString(R.string.redirected_from_snackbar, it), Snackbar.LENGTH_SHORT)\n        }\n        model.readingListPage?.let { page ->\n            model.title?.let { title ->\n                lifecycleScope.launch(CoroutineExceptionHandler { _, t ->\n                    L.e(t)\n                }) {\n                    if (!page.thumbUrl.equals(title.thumbUrl, true) || !page.description.equals(title.description, true)) {\n                        AppDatabase.instance.readingListPageDao().updateThumbAndDescriptionByName(\n                            lang = page.wiki.languageCode,\n                            apiTitle = page.apiTitle,\n                            thumbUrl = title.thumbUrl,\n                            description = title.description\n                        )\n                    }\n                }\n            }\n        }\n        if (!errorState) {\n            editHandler.setPage(model.page)\n            webView.visibility = View.VISIBLE\n        }\n\n        maybeShowAnnouncement()\n\n        bridge.onMetadataReady()\n        // Explicitly set the top margin (even though it might have already been set in the setup\n        // handler), since the page metadata might have altered the lead image display state.\n        bridge.execute(JavaScriptActionHandler.setTopMargin(leadImagesHandler.topMargin))\n        bridge.execute(JavaScriptActionHandler.setFooter(model))\n    }\n\n    fun openInNewBackgroundTab(title: PageTitle, entry: HistoryEntry) {\n        if (app.tabCount == 0) {\n            openInNewTab(title, entry, foregroundTabPosition)\n            pageFragmentLoadState.loadFromBackStack()\n        } else {\n            openInNewTab(title, entry, backgroundTabPosition)\n            (requireActivity() as PageActivity).animateTabsButton()\n        }\n    }\n\n    fun openInNewForegroundTab(title: PageTitle, entry: HistoryEntry) {\n        openInNewTab(title, entry, foregroundTabPosition)\n        pageFragmentLoadState.loadFromBackStack()\n    }\n\n    fun openFromExistingTab(title: PageTitle, entry: HistoryEntry) {\n        val selectedTabPosition = selectedTabPosition(title)\n\n        if (selectedTabPosition == -1) {\n            loadPage(title, entry, pushBackStack = true, squashBackstack = false)\n            return\n        }\n        setCurrentTabAndReset(selectedTabPosition)\n    }\n\n    fun loadPage(title: PageTitle, entry: HistoryEntry, pushBackStack: Boolean, squashBackstack: Boolean, isRefresh: Boolean = false, highlightText: String? = null) {\n        // is the new title the same as what's already being displayed?\n        if (currentTab.backStack.isNotEmpty() &&\n                title == currentTab.backStack[currentTab.backStackPosition].title) {\n            if (model.page == null || isRefresh) {\n                if (highlightText.isNullOrEmpty()) {\n                    pageFragmentLoadState.loadFromBackStack()\n                } else {\n                    // Scroll to the highlighted passage instead of restoring the previous scroll position.\n                    loadPage(title, entry, false, 0, isRefresh, highlightText)\n                }\n            } else {\n                // Keep the model in sync so that a pending final_setup does not jump to a stale target.\n                model.title?.fragment = title.fragment\n                model.pendingHighlightText = highlightText\n                jumpToHighlightOrSection(title.fragment, highlightText)\n            }\n            return\n        }\n        if (squashBackstack) {\n            if (app.tabCount > 0) {\n                app.tabList.last().clearBackstack()\n            }\n        }\n        loadPage(title, entry, pushBackStack, 0, isRefresh, highlightText)\n    }\n\n    fun loadPage(title: PageTitle, entry: HistoryEntry, pushBackStack: Boolean, stagedScrollY: Int, isRefresh: Boolean = false, highlightText: String? = null) {\n        // clear the title in case the previous page load had failed.\n        clearActivityActionBarTitle()\n\n        if (ExclusiveBottomSheetPresenter.getCurrentBottomSheet(childFragmentManager) !is ThemeChooserDialog) {\n            dismissBottomSheet()\n        }\n\n        if (AccountUtil.isLoggedIn) {\n            // explicitly check notifications for the current user\n            PollNotificationWorker.schedulePollNotificationJob(requireContext())\n        }\n\n        EventPlatformClient.AssociationController.beginNewPageView()\n\n        // update the time spent reading of the current page, before loading the new one\n        addTimeSpentReading(activeTimer.elapsedSec)\n        activeTimer.reset()\n        callback()?.onPageSetToolbarElevationEnabled(false)\n        sidePanelHandler.setEnabled(false)\n        errorState = false\n        binding.pageError.visibility = View.GONE\n        model.title = title\n        model.pendingHighlightText = highlightText\n        model.curEntry = entry\n        model.page = null\n        model.readingListPage = null\n        model.forceNetwork = isRefresh\n        webView.visibility = View.VISIBLE\n        binding.pageActionsTabLayout.visibility = View.VISIBLE\n        binding.pageActionsTabLayout.enableAllTabs()\n        updateProgressBar(true)\n        pageRefreshed = isRefresh\n        references = null\n        revision = 0\n        pageFragmentLoadState.load(pushBackStack)\n        scrollTriggerListener.stagedScrollY = stagedScrollY\n    }\n\n    fun updateFontSize() {\n        webView.settings.defaultFontSize = app.getFontSize().toInt()\n    }\n\n    fun updateQuickActionsAndMenuOptions() {\n        if (!isAdded) {\n            return\n        }\n        binding.pageActionsTabLayout.forEach { it as MaterialTextView\n            val pageActionItem = PageActionItem.find(it.id)\n            var enabled = model.page != null && (!model.shouldLoadAsMobileWeb || (model.shouldLoadAsMobileWeb && pageActionItem.isAvailableOnMobileWeb))\n            when (pageActionItem) {\n                PageActionItem.ADD_TO_WATCHLIST -> {\n                    it.setText(if (model.isWatched) R.string.menu_page_unwatch else R.string.menu_page_watch)\n                    it.setCompoundDrawablesWithIntrinsicBounds(0, PageActionItem.watchlistIcon(model.isWatched, model.hasWatchlistExpiry), 0, 0)\n                    enabled = enabled && AccountUtil.isLoggedIn\n                }\n                PageActionItem.SAVE -> {\n                    it.setCompoundDrawablesWithIntrinsicBounds(0, PageActionItem.readingListIcon(model.isInReadingList), 0, 0)\n                }\n                PageActionItem.EDIT_ARTICLE -> {\n                    it.setCompoundDrawablesWithIntrinsicBounds(0, PageActionItem.editArticleIcon(model.page?.canEdit != true), 0, 0)\n                }\n                PageActionItem.VIEW_ON_MAP -> {\n                    val geoAvailable = model.page?.summary?.coordinates != null\n                    val tintColor = ResourceUtil.getThemedColorStateList(requireContext(), if (geoAvailable) R.attr.primary_color else R.attr.inactive_color)\n                    it.setTextColor(tintColor)\n                    TextViewCompat.setCompoundDrawableTintList(it, tintColor)\n                }\n                else -> { }\n            }\n            it.isEnabled = enabled\n            it.alpha = if (enabled) 1f else 0.5f\n        }\n        sidePanelHandler.setEnabled(false)\n        requireActivity().invalidateOptionsMenu()\n    }\n\n    suspend fun updateBookmarkAndMenuOptionsFromDao() {\n        title?.let {\n            model.readingListPage = AppDatabase.instance.readingListPageDao().findPageInAnyList(it)\n            updateQuickActionsAndMenuOptions()\n            requireActivity().invalidateOptionsMenu()\n        }\n    }\n\n    fun onActionModeShown(mode: ActionMode) {\n        // make sure we have a page loaded, since shareHandler makes references to it.\n        model.page?.run {\n            shareHandler.onTextSelected(mode)\n        }\n    }\n\n    fun onRequestEditSection(sectionId: Int, sectionAnchor: String?, title: PageTitle, highlightText: String?) {\n        callback()?.onPageRequestEditSection(sectionId, sectionAnchor, title, highlightText)\n    }\n\n    fun sharePageLink() {\n        model.title?.let {\n            ShareUtil.shareText(requireActivity(), it)\n        }\n    }\n\n    fun showFindInPage() {\n        model.title?.let { title ->\n            bridge.evaluate(JavaScriptActionHandler.expandCollapsedTables(true)) {\n                if (!isAdded) {\n                    return@evaluate\n                }\n                val articleFindInPageInteractionEvent = ArticleFindInPageInteractionEvent(model.page?.summary?.pageId ?: -1)\n                val findInPageActionProvider = FindInWebPageActionProvider(this, articleFindInPageInteractionEvent)\n                startSupportActionMode(object : ActionMode.Callback {\n                    override fun onCreateActionMode(mode: ActionMode, menu: Menu): Boolean {\n                        val menuItem = menu.add(R.string.menu_page_find_in_page)\n                        menuItem.actionProvider = findInPageActionProvider\n                        menuItem.expandActionView()\n                        callback()?.onPageSetToolbarElevationEnabled(false)\n                        return true\n                    }\n\n                    override fun onPrepareActionMode(mode: ActionMode, menu: Menu): Boolean {\n                        mode.tag = \"actionModeFindInPage\"\n                        return false\n                    }\n\n                    override fun onActionItemClicked(mode: ActionMode, item: MenuItem): Boolean {\n                        return false\n                    }\n\n                    override fun onDestroyActionMode(mode: ActionMode) {\n                        if (!isAdded) {\n                            return\n                        }\n                        articleFindInPageInteractionEvent.pageHeight = webView.contentHeight\n                        articleFindInPageInteractionEvent.logDone()\n                        webView.clearMatches()\n                        callback()?.onPageHideSoftKeyboard()\n                        callback()?.onPageSetToolbarElevationEnabled(true)\n                    }\n                })\n            }\n        }\n    }\n\n    private fun scrollToSection(sectionAnchor: String) {\n        if (!isAdded) {\n            return\n        }\n        bridge.execute(JavaScriptActionHandler.clearHighlight())\n        bridge.execute(JavaScriptActionHandler.prepareToScrollTo(sectionAnchor, false))\n    }\n\n    private fun jumpToHighlightOrSection(sectionAnchor: String?, highlightText: String?) {\n        if (!highlightText.isNullOrEmpty()) {\n            bridge.evaluate(JavaScriptActionHandler.jumpToHighlightOrSection(sectionAnchor, highlightText)) { result ->\n                // ignore\n            }\n        } else if (!sectionAnchor.isNullOrEmpty()) {\n            scrollToSection(sectionAnchor)\n        }\n    }\n\n    fun onPageLoadError(caught: Throwable) {\n        if (!isAdded) {\n            return\n        }\n        title?.let {\n            updateProgressBar(false)\n            binding.pageRefreshContainer.isRefreshing = false\n            if (pageRefreshed) {\n                pageRefreshed = false\n            }\n            hidePageContent()\n            bridge.onMetadataReady()\n            if (binding.pageError.visibility != View.VISIBLE) {\n                binding.pageError.setError(caught, it)\n            }\n            binding.pageError.visibility = View.VISIBLE\n            binding.pageError.contentTopOffset.layoutParams = getContentTopOffsetParams(requireContext())\n            binding.pageError.contentTopOffset.visibility = View.VISIBLE\n            binding.pageError.tabLayoutOffset.layoutParams = tabLayoutOffsetParams\n            binding.pageError.tabLayoutOffset.visibility = View.VISIBLE\n            disableActionTabs(caught)\n            binding.pageRefreshContainer.isEnabled = !ThrowableUtil.is404(caught)\n            errorState = true\n            callback()?.onPageLoadError(it)\n        }\n    }\n\n    fun updateHeaderTopMargin() {\n        bridge.execute(JavaScriptActionHandler.setTopMargin(leadImagesHandler.topMargin))\n    }\n\n    fun updateMessageCardHeight() {\n        messageCardHeight = leadImagesHandler.getDonationReminderCardViewHeight()\n    }\n\n    fun refreshPage(stagedScrollY: Int = 0) {\n        if (bridge.isLoading) {\n            binding.pageRefreshContainer.isRefreshing = false\n            return\n        }\n        model.title?.let { title ->\n            model.curEntry?.let { entry ->\n                binding.pageError.visibility = View.GONE\n                binding.pageActionsTabLayout.enableAllTabs()\n                errorState = false\n                model.curEntry = HistoryEntry(title, HistoryEntry.SOURCE_HISTORY)\n                loadPage(title, entry, false, stagedScrollY, app.isOnline)\n            }\n        }\n    }\n\n   private fun clearActivityActionBarTitle() {\n        val currentActivity = requireActivity()\n        if (currentActivity is PageActivity) {\n            currentActivity.clearActionBarTitle()\n        }\n   }\n\n    fun verifyBeforeEditingDescription(text: String?, invokeSource: InvokeSource) {\n        page?.let {\n            if (!AccountUtil.isLoggedIn && Prefs.totalAnonDescriptionsEdited >= resources.getInteger(R.integer.description_max_anon_edits)) {\n                MaterialAlertDialogBuilder(requireActivity())\n                    .setMessage(R.string.description_edit_anon_limit)\n                    .setPositiveButton(R.string.page_editing_login) { _, _ ->\n                        startActivity(LoginActivity.newIntent(requireContext(), LoginActivity.SOURCE_EDIT))\n                    }\n                    .setNegativeButton(R.string.description_edit_login_cancel_button_text, null)\n                    .show()\n            } else {\n                startDescriptionEditActivity(text, invokeSource)\n            }\n        }\n    }\n\n    private fun startDescriptionEditActivity(text: String?, invokeSource: InvokeSource) {\n        title?.run {\n            val sourceSummary = PageSummaryForEdit(prefixedText, wikiSite.languageCode, this,\n                displayText, description, thumbUrl)\n            callback()?.onPageRequestEditDescription(text, this, sourceSummary, null,\n                DescriptionEditActivity.Action.ADD_DESCRIPTION, invokeSource)\n        }\n    }\n\n    fun goForward() {\n        pageFragmentLoadState.goForward()\n    }\n\n    fun showBottomSheet(dialog: BottomSheetDialogFragment) {\n        ExclusiveBottomSheetPresenter.show(childFragmentManager, dialog)\n    }\n\n    fun loadPage(title: PageTitle, entry: HistoryEntry) {\n        callback()?.onPageLoadPage(title, entry)\n    }\n\n    fun startSupportActionMode(actionModeCallback: ActionMode.Callback) {\n        callback()?.onPageStartSupportActionMode(actionModeCallback)\n    }\n\n    fun callback(): Callback? {\n        return getCallback(this, Callback::class.java)\n    }\n\n    fun updateWatchlist() {\n        title?.let {\n            lifecycleScope.launch(CoroutineExceptionHandler { _, throwable ->\n                FeedbackUtil.showError(requireActivity(), throwable)\n                L.d(throwable)\n            }) {\n                val pair = WatchlistViewModel.watchPageTitle(this, it, model.isWatched, WatchlistExpiry.NEVER, model.isWatched, it.namespace().talk())\n                model.isWatched = pair.first\n                updateWatchlistExpiry(WatchlistExpiry.NEVER)\n                WatchlistViewModel.showWatchlistSnackbar(requireActivity() as AppCompatActivity, childFragmentManager, it, pair.first, pair.second)\n                updateQuickActionsAndMenuOptions()\n            }\n        }\n    }\n\n    fun showAnonNotification() {\n        (requireActivity() as PageActivity).onAnonNotification()\n    }\n\n    fun showOverflowMenu(anchor: View) {\n        PageActionOverflowView(requireContext()).show(anchor, pageActionItemCallback, currentTab, model)\n    }\n\n    fun goToMainActivity(tab: NavTab, tabExtra: String) {\n        startActivity(MainActivity.newIntent(requireActivity())\n            .addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP)\n            .putExtra(Constants.INTENT_RETURN_TO_MAIN, true)\n            .putExtra(tabExtra, tab.code()))\n        requireActivity().finish()\n    }\n\n    fun dismissEditHandlerMenu(title: PageTitle?) {\n        title?.let {\n            EditAttemptStepEvent.logAbort(pageTitle = it, editCount = this.editCount)\n        }\n    }\n\n    private inner class AvCallback : AvPlayer.Callback {\n        override fun onSuccess() {\n            avPlayer?.stop()\n            updateProgressBar(false)\n        }\n\n        override fun onError(code: Int, extra: Int) {\n            if (avPlayer?.isPlaying == true) {\n                avPlayer?.stop()\n            }\n            FeedbackUtil.showMessage(this@PageFragment, R.string.media_playback_error)\n            updateProgressBar(false)\n        }\n    }\n\n    private inner class WebViewScrollTriggerListener : ObservableWebView.OnContentHeightChangedListener {\n        var stagedScrollY = 0\n        override fun onContentHeightChanged(contentHeight: Int) {\n            if (stagedScrollY > 0 && contentHeight * DimenUtil.densityScalar - webView.height > stagedScrollY) {\n                webView.scrollY = stagedScrollY\n                stagedScrollY = 0\n            }\n        }\n    }\n\n    private inner class FindReferenceInPageActionProvider constructor(context: Context,\n                                                                      private val referenceAnchor: String,\n                                                                      private val referenceText: String,\n                                                                      private val backLinksList: List<String?>) : ActionProvider(context), View.OnClickListener {\n        private val binding = GroupFindReferencesInPageBinding.inflate(LayoutInflater.from(context), null, false)\n        private var currentPos = 0\n\n        override fun onCreateActionView(): View {\n            binding.findInPagePrev.setOnClickListener(this)\n            binding.findInPageNext.setOnClickListener(this)\n            binding.referenceLabel.setOnClickListener(this)\n            binding.referenceLabel.text = getString(R.string.reference_list_title).plus(\" $referenceText\")\n            if (backLinksList.isNotEmpty()) {\n                scrollTo(0)\n            }\n            return binding.root\n        }\n\n        override fun overridesItemVisibility(): Boolean {\n            return true\n        }\n\n        override fun onClick(v: View) {\n            when (v) {\n                binding.findInPagePrev -> {\n                    if (backLinksList.isNotEmpty()) {\n                        currentPos = if (--currentPos < 0) backLinksList.size - 1 else currentPos\n                        scrollTo(currentPos)\n                    }\n                }\n                binding.findInPageNext -> {\n                    if (backLinksList.isNotEmpty()) {\n                        currentPos = if (++currentPos >= backLinksList.size) 0 else currentPos\n                        scrollTo(currentPos)\n                    }\n                }\n                binding.referenceLabel -> {\n                    bridge.execute(JavaScriptActionHandler.scrollToAnchor(referenceAnchor))\n                    callback()?.onPageCloseActionMode()\n                }\n            }\n        }\n\n        private fun scrollTo(position: Int) {\n            backLinksList[position]?.let {\n                binding.referenceCount.text = getString(R.string.find_in_page_result, position + 1,\n                    if (backLinksList.isEmpty()) 0 else backLinksList.size)\n                bridge.execute(JavaScriptActionHandler.prepareToScrollTo(it, true))\n            }\n        }\n    }\n\n    inner class PageActionItemCallback : PageActionItem.Callback {\n        override fun onSaveSelected() {\n            title?.let { SaveArticleSheetDialog.show(childFragmentManager, it) }\n            articleInteractionEvent?.logSaveClick()\n        }\n\n        override fun onLanguageSelected() {\n            startLangLinksActivity()\n            articleInteractionEvent?.logLanguageClick()\n        }\n\n        override fun onFindInArticleSelected() {\n            showFindInPage()\n            articleInteractionEvent?.logFindInArticleClick()\n        }\n\n        override fun onThemeSelected() {\n            articleInteractionEvent?.logThemeClick()\n\n            // If we're looking at the top of the article, then scroll down a bit so that at least\n            // some of the text is shown.\n            if (webView.scrollY < DimenUtil.leadImageHeightForDevice(requireActivity())) {\n                scrolledUpForThemeChange = true\n                val animDuration = 250\n                val anim = ObjectAnimator.ofInt(webView, \"scrollY\", webView.scrollY, DimenUtil.leadImageHeightForDevice(requireActivity()))\n                anim.setDuration(animDuration.toLong()).doOnEnd {\n                    showBottomSheet(ThemeChooserDialog.newInstance(InvokeSource.PAGE_ACTION_TAB))\n                }\n                anim.start()\n            } else {\n                scrolledUpForThemeChange = false\n                showBottomSheet(ThemeChooserDialog.newInstance(InvokeSource.PAGE_ACTION_TAB))\n            }\n        }\n\n        override fun onContentsSelected() {\n            sidePanelHandler.showToC()\n            articleInteractionEvent?.logContentsClick()\n        }\n\n        override fun onShareSelected() {\n            sharePageLink()\n            articleInteractionEvent?.logShareClick()\n        }\n\n        override fun onAddToWatchlistSelected() {\n            if (model.isWatched) {\n                WatchlistAnalyticsHelper.logRemovedFromWatchlist(model.title, requireContext())\n                articleInteractionEvent?.logUnWatchClick()\n            } else {\n                WatchlistAnalyticsHelper.logAddedToWatchlist(model.title, requireContext())\n                articleInteractionEvent?.logWatchClick()\n            }\n            updateWatchlist()\n        }\n\n        override fun onViewTalkPageSelected() {\n            title?.let {\n                startTalkTopicsActivity(it, true)\n            }\n            articleInteractionEvent?.logTalkPageClick()\n        }\n\n        override fun onViewEditHistorySelected() {\n            title?.run {\n                startActivity(EditHistoryListActivity.newIntent(requireContext(), this))\n            }\n            articleInteractionEvent?.logEditHistoryClick()\n        }\n\n        override fun onNewTabSelected() {\n            startActivity(PageActivity.newIntentForNewTab(requireContext()))\n            articleInteractionEvent?.logNewTabClick()\n        }\n\n        override fun onHomeSelected() {\n            goToMainActivity(tab = NavTab.HOME, tabExtra = Constants.INTENT_EXTRA_GO_TO_MAIN_TAB)\n            articleInteractionEvent?.logHomeClick()\n        }\n\n        override fun onCategoriesSelected() {\n            title?.let {\n                ExclusiveBottomSheetPresenter.show(childFragmentManager, CategoryDialog.newInstance(it))\n            }\n            articleInteractionEvent?.logCategoriesClick()\n        }\n\n        override fun onEditArticleSelected() {\n            editHandler.startEditingArticle()\n            articleInteractionEvent?.logEditArticleClick()\n        }\n\n        override fun onViewOnMapSelected() {\n            title?.let {\n                val location = page?.summary?.coordinates\n                if (location != null) {\n                    PlacesEvent.logAction(\"places_click\", \"article_more_menu\")\n                    requireActivity().startActivity(PlacesActivity.newIntent(requireContext(), it, location))\n                } else {\n                    FeedbackUtil.showMessage(this@PageFragment, getString(R.string.action_item_view_on_map_unavailable))\n                }\n            }\n        }\n\n        override fun forwardClick() {\n            goForward()\n            articleInteractionEvent?.logForwardClick()\n        }\n    }\n\n    companion object {\n        private const val ARG_THEME_CHANGE_SCROLLED = \"themeChangeScrolled\"\n        private val REFRESH_SPINNER_ADDITIONAL_OFFSET = (16 * DimenUtil.densityScalar).toInt()\n    }\n}","file":"app/src/main/java/org/wikipedia/page/PageFragment.kt","kind":"class","line":123,"members":{"ARG_THEME_CHANGE_SCROLLED":[1522,1522],"AvCallback":[1334,1347],"Callback":[126,147],"FindReferenceInPageActionProvider":[1359,1409],"PageActionItemCallback":[1411,1519],"REFRESH_SPINNER_ADDITIONAL_OFFSET":[1523,1523],"WebViewScrollTriggerListener":[1349,1357],"_binding":[156,156],"activeTimer":[159,159],"addTimeSpentReading":[610,619],"app":[180,180],"articleInteractionEvent":[171,171],"avCallback":[177,177],"avPlayer":[176,176],"backgroundTabPosition":[197,197],"binding":[157,157],"bottomBarHideHandler":[170,170],"bridge":[167,167],"callback":[1293,1295],"campaignDialog":[149,149],"clearActivityActionBarTitle":[1245,1250],"currentTab":[200,200],"disableActionTabs":[625,632],"dismissBottomSheet":[588,591],"dismissEditHandlerMenu":[1328,1332],"donationReminderLauncher":[150,154],"editCount":[179,179],"editHandler":[193,193],"errorState":[173,173],"foregroundTabPosition":[198,198],"getContentTopOffsetParams":[621,623],"goForward":[1277,1279],"goToMainActivity":[1320,1326],"handleInternalLink":[500,530],"hidePageContent":[682,686],"initWebViewListeners":[392,455],"isLoading":[203,203],"isPreview":[186,186],"jumpToHighlightOrSection":[1184,1192],"leadImageEditLang":[204,204],"leadImagesHandler":[168,168],"linkHandler":[182,182],"loadPage":[1006,1031],"maybeShowAnnouncement":[692,717],"messageCardHeight":[189,189],"model":[184,184],"onActionModeShown":[1118,1123],"onBackPressed":[329,344],"onCancelThemeChooser":[367,374],"onConfigurationChanged":[320,327],"onCreateView":[206,219],"onDestroyView":[273,287],"onEditingPrefsChanged":[376,376],"onExpiryChanged":[382,385],"onPageLoadError":[1194,1219],"onPageMetadataLoaded":[935,979],"onPageSetupEvent":[457,498],"onPause":[289,303],"onRequestEditSection":[1125,1127],"onResume":[305,318],"onSaveInstanceState":[268,271],"onToggleDimImages":[346,348],"onToggleReadingFocusMode":[350,365],"onViewCreated":[221,266],"openFromExistingTab":[996,1004],"openInNewBackgroundTab":[981,989],"openInNewForegroundTab":[991,994],"openInNewTab":[551,586],"page":[202,202],"pageActionItemCallback":[165,165],"pageFragmentLoadState":[169,169],"pageRefreshListener":[161,164],"pageRefreshed":[172,172],"references":[175,175],"referencesGroup":[187,187],"refreshPage":[1229,1243],"reloadFromBackstack":[925,933],"revision":[194,194],"scrollToSection":[1176,1182],"scrollTriggerListener":[160,160],"scrolledUpForThemeChange":[174,174],"sections":[178,178],"selectedReferenceIndex":[188,188],"selectedTabPosition":[546,549],"setCurrentTabAndReset":[532,544],"setupMessageHandlers":[747,923],"shareHandler":[192,192],"sharePageLink":[1129,1133],"shouldCreateNewTab":[196,196],"shouldLoadFromBackstack":[387,390],"showAnonNotification":[1312,1314],"showBottomSheet":[1281,1283],"showFindInPage":[1135,1174],"showFindReferenceInPage":[719,745],"showOverflowMenu":[1316,1318],"sidePanelHandler":[191,191],"startDescriptionEditActivity":[1268,1275],"startGalleryActivity":[642,680],"startLangLinksActivity":[597,602],"startSupportActionMode":[1289,1291],"startTalkTopicsActivity":[634,640],"tabLayoutOffsetParams":[199,199],"title":[201,201],"toolbarMargin":[185,185],"trimTabCount":[604,608],"updateBookmarkAndMenuOptionsFromDao":[1110,1116],"updateFontSize":[1072,1074],"updateHeaderTopMargin":[1221,1223],"updateMessageCardHeight":[1225,1227],"updateProgressBar":[593,595],"updateQuickActionsAndMenuOptions":[1076,1108],"updateWatchlist":[1297,1310],"updateWatchlistExpiry":[688,690],"verifyBeforeEditingDescription":[1252,1266],"webView":[183,183],"wiktionaryShowDialogForTerm":[378,380]},"shot":"shots/code/PageFragment.jpg","supers":["Fragment()","BackPressedHandler","CommunicationBridge.CommunicationBridgeListener","ThemeChooserDialog.Callback","ReferenceDialog.Callback","WiktionaryDialog.Callback","WatchlistExpiryDialog.Callback"]},"ReadingList":{"appearsIn":[["saved","h-classes","Logic \u00b7 class diagram"]],"code":"@Entity\nclass ReadingList(\n    var listTitle: String,\n    var description: String?,\n    var mtime: Long = System.currentTimeMillis(),\n    var atime: Long = mtime,\n    @PrimaryKey(autoGenerate = true) var id: Long = 0,\n    var sizeBytes: Long = 0,\n    var dirty: Boolean = true,\n    var remoteId: Long = 0\n) : Serializable {\n\n    @Ignore\n    val pages = mutableListOf<ReadingListPage>()\n\n    @delegate:Transient\n    val accentInvariantTitle: String by lazy {\n        StringUtils.stripAccents(title)\n    }\n\n    @Transient\n    var selected = false\n\n    var title\n        get() = listTitle.ifEmpty { L10nUtil.getString(R.string.default_reading_list_name) }\n        set(value) { listTitle = value }\n\n    val isDefault\n        get() = title == L10nUtil.getString(R.string.default_reading_list_name)\n\n    val numPagesOffline\n        get() = pages.count { it.offline && it.status == ReadingListPage.STATUS_SAVED }\n\n    val sizeBytesFromPages\n        get() = pages.sumOf { if (it.offline) it.sizeBytes else 0 }\n\n    fun touch() {\n        atime = System.currentTimeMillis()\n    }\n\n    fun compareTo(other: Any): Boolean {\n        return (other is ReadingList &&\n                id == other.id &&\n                pages.size == other.pages.size &&\n                numPagesOffline == other.numPagesOffline &&\n                title == other.title &&\n                description == other.description)\n    }\n\n    companion object {\n        const val SORT_BY_NAME_ASC = 0\n        const val SORT_BY_NAME_DESC = 1\n        const val SORT_BY_RECENT_ASC = 2\n        const val SORT_BY_RECENT_DESC = 3\n\n        fun sort(list: ReadingList, sortMode: Int) {\n            when (sortMode) {\n                SORT_BY_NAME_ASC -> list.pages.sortWith { lhs: ReadingListPage, rhs: ReadingListPage -> lhs.accentInvariantTitle.compareTo(rhs.accentInvariantTitle, true) }\n                SORT_BY_NAME_DESC -> list.pages.sortWith { lhs: ReadingListPage, rhs: ReadingListPage -> rhs.accentInvariantTitle.compareTo(lhs.accentInvariantTitle, true) }\n                SORT_BY_RECENT_ASC -> list.pages.sortWith { lhs: ReadingListPage, rhs: ReadingListPage -> rhs.mtime.compareTo(lhs.mtime) }\n                SORT_BY_RECENT_DESC -> list.pages.sortWith { lhs: ReadingListPage, rhs: ReadingListPage -> lhs.mtime.compareTo(rhs.mtime) }\n            }\n        }\n\n        fun sort(lists: MutableList<ReadingList>, sortMode: Int) {\n            when (sortMode) {\n                SORT_BY_NAME_ASC -> lists.sortWith { lhs: ReadingList, rhs: ReadingList -> lhs.accentInvariantTitle.compareTo(rhs.accentInvariantTitle, true) }\n                SORT_BY_NAME_DESC -> lists.sortWith { lhs: ReadingList, rhs: ReadingList -> rhs.accentInvariantTitle.compareTo(lhs.accentInvariantTitle, true) }\n                SORT_BY_RECENT_ASC -> lists.sortWith { lhs: ReadingList, rhs: ReadingList -> rhs.mtime.compareTo(lhs.mtime) }\n                SORT_BY_RECENT_DESC -> lists.sortWith { lhs: ReadingList, rhs: ReadingList -> lhs.mtime.compareTo(rhs.mtime) }\n            }\n            // make the Default list sticky on top, regardless of sorting.\n            lists.firstOrNull { it.isDefault }?.let {\n                lists.remove(it)\n                lists.add(0, it)\n            }\n        }\n    }\n}","file":"app/src/main/java/org/wikipedia/readinglist/database/ReadingList.kt","kind":"class","line":13,"members":{"SORT_BY_NAME_ASC":[63,63],"SORT_BY_NAME_DESC":[64,64],"SORT_BY_RECENT_ASC":[65,65],"SORT_BY_RECENT_DESC":[66,66],"accentInvariantTitle":[28,31],"atime":[18,18],"compareTo":[53,60],"description":[16,16],"dirty":[21,21],"id":[19,19],"isDefault":[40,40],"listTitle":[15,15],"mtime":[17,17],"numPagesOffline":[43,43],"pages":[25,26],"remoteId":[22,22],"selected":[33,34],"sizeBytes":[20,20],"sizeBytesFromPages":[46,46],"sort":[68,75],"title":[36,36],"touch":[49,51]},"supers":["Serializable"]},"ReadingListClient":{"appearsIn":[["saved","h-classes","Logic \u00b7 class diagram"],["saved","h-sequence","Save an article and sync it \u00b7 sequence"]],"code":"class ReadingListClient(private val wiki: WikiSite) {\n    var lastDateHeader: Instant? = null\n        private set\n\n    /**\n     * Sets up reading list syncing on the server, and returns true if the setup was successful,\n     * or false if syncing is already set up.\n     */\n    @Throws(Throwable::class)\n    fun setup(csrfToken: String): Boolean {\n        return try {\n            ServiceFactory.getRest(wiki).setupReadingLists(csrfToken).execute()\n            true\n        } catch (t: Throwable) {\n            if (isErrorType(t, \"already-set-up\")) {\n                return false\n            }\n            throw t\n        }\n    }\n\n    @Throws(Throwable::class)\n    fun tearDown(csrfToken: String) {\n        try {\n            ServiceFactory.getRest(wiki).tearDownReadingLists(csrfToken).execute()\n        } catch (t: Throwable) {\n            if (isErrorType(t, \"not-set-up\")) {\n                return\n            }\n            throw t\n        }\n    }\n\n    @get:Throws(Throwable::class)\n    val allLists: List<RemoteReadingList>\n        get() {\n            val totalLists = mutableListOf<RemoteReadingList>()\n            var totalCycles = 0\n            var continueStr: String? = null\n            do {\n                val response = ServiceFactory.getRest(wiki).getReadingLists(continueStr).execute()\n                val lists = response.body()\n                if (lists?.lists == null) {\n                    throw IOException(\"Incorrect response format.\")\n                }\n                totalLists.addAll(lists.lists)\n                continueStr = if (lists.continueStr.isNullOrEmpty()) null else lists.continueStr\n                saveLastDateHeader(response)\n            } while (!continueStr.isNullOrEmpty() && totalCycles++ < MAX_CONTINUE_CYCLES)\n            return totalLists\n        }\n\n    @Throws(Throwable::class)\n    fun getChangesSince(date: String): SyncedReadingLists {\n        val totalLists = mutableListOf<RemoteReadingList>()\n        val totalEntries = mutableListOf<RemoteReadingListEntry>()\n        var totalCycles = 0\n        var continueStr: String? = null\n        do {\n            val response = ServiceFactory.getRest(wiki).getReadingListChangesSince(date, continueStr).execute()\n            val body = response.body() ?: throw IOException(\"Incorrect response format.\")\n            body.lists?.let {\n                totalLists.addAll(it)\n            }\n            body.entries?.let {\n                totalEntries.addAll(it)\n            }\n            continueStr = if (body.continueStr.isNullOrEmpty()) null else body.continueStr\n            saveLastDateHeader(response)\n        } while (!continueStr.isNullOrEmpty() && totalCycles++ < MAX_CONTINUE_CYCLES)\n        return SyncedReadingLists(totalLists, totalEntries)\n    }\n\n    @Throws(Throwable::class)\n    @Suppress(\"unused\")\n    fun getListsContaining(entry: RemoteReadingListEntry): List<RemoteReadingList> {\n        val totalLists: MutableList<RemoteReadingList> = ArrayList()\n        var totalCycles = 0\n        var continueStr: String? = null\n        do {\n            val response = ServiceFactory.getRest(wiki)\n                    .getReadingListsContaining(entry.project(), entry.title(), continueStr).execute()\n            val lists = response.body()\n            if (lists?.lists == null) {\n                throw IOException(\"Incorrect response format.\")\n            }\n            totalLists.addAll(lists.lists)\n            continueStr = if (lists.continueStr.isNullOrEmpty()) null else lists.continueStr\n            saveLastDateHeader(response)\n        } while (!continueStr.isNullOrEmpty() && totalCycles++ < MAX_CONTINUE_CYCLES)\n        return totalLists\n    }\n\n    @Throws(Throwable::class)\n    fun getListEntries(listId: Long): List<RemoteReadingListEntry> {\n        val totalEntries = mutableListOf<RemoteReadingListEntry>()\n        var totalCycles = 0\n        var continueStr: String? = null\n        do {\n            val response = ServiceFactory.getRest(wiki).getReadingListEntries(listId, continueStr).execute()\n            val body = response.body()\n            if (body?.entries == null) {\n                throw IOException(\"Incorrect response format.\")\n            }\n            totalEntries.addAll(body.entries)\n            continueStr = if (body.continueStr.isNullOrEmpty()) null else body.continueStr\n            saveLastDateHeader(response)\n        } while (!continueStr.isNullOrEmpty() && totalCycles++ < MAX_CONTINUE_CYCLES)\n        return totalEntries\n    }\n\n    @Throws(Throwable::class)\n    fun createList(csrfToken: String, list: RemoteReadingList): Long {\n        val response = ServiceFactory.getRest(wiki).createReadingList(csrfToken, list).execute()\n        val idResponse = response.body() ?: throw IOException(\"Incorrect response format.\")\n        saveLastDateHeader(response)\n        return idResponse.id\n    }\n\n    @Throws(Throwable::class)\n    fun updateList(csrfToken: String, listId: Long, list: RemoteReadingList) {\n        saveLastDateHeader(ServiceFactory.getRest(wiki).updateReadingList(listId, csrfToken, list).execute())\n    }\n\n    @Throws(Throwable::class)\n    fun deleteList(csrfToken: String, listId: Long) {\n        saveLastDateHeader(ServiceFactory.getRest(wiki).deleteReadingList(listId, csrfToken).execute())\n    }\n\n    @Throws(Throwable::class)\n    fun addPageToList(csrfToken: String, listId: Long, entry: RemoteReadingListEntry): Long {\n        val response = ServiceFactory.getRest(wiki).addEntryToReadingList(listId, csrfToken, entry).execute()\n        val idResponse = response.body() ?: throw IOException(\"Incorrect response format.\")\n        saveLastDateHeader(response)\n        return idResponse.id\n    }\n\n    @Throws(Throwable::class)\n    fun addPagesToList(csrfToken: String, listId: Long, entries: List<RemoteReadingListEntry>): List<Long> {\n        val ids = mutableListOf<Long>()\n        for (batch in entries.chunked(50)) {\n            if (batch.isEmpty()) {\n                break\n            }\n            try {\n                val response = ServiceFactory.getRest(wiki).addEntriesToReadingList(listId, csrfToken, RemoteReadingListEntryBatch(batch)).execute()\n                val idResponse = response.body() ?: throw IOException(\"Incorrect response format.\")\n                saveLastDateHeader(response)\n                for (id in idResponse.batch) {\n                    ids.add(id.id)\n                }\n            } catch (t: Throwable) {\n                if (isErrorType(t, \"entry-limit\")) {\n                    // TODO: handle more meaningfully than ignoring, for now.\n                    break\n                }\n                throw t\n            }\n        }\n        return ids\n    }\n\n    @Throws(Throwable::class)\n    fun deletePageFromList(csrfToken: String, listId: Long, entryId: Long) {\n        saveLastDateHeader(ServiceFactory.getRest(wiki).deleteEntryFromReadingList(listId, entryId, csrfToken).execute())\n    }\n\n    fun isErrorType(t: Throwable?, errorType: String): Boolean {\n        return t is HttpStatusException && t.serviceError?.key?.contains(errorType) == true\n    }\n\n    fun isServiceError(t: Throwable?): Boolean {\n        return t is HttpStatusException && t.code == 400\n    }\n\n    fun isUnavailableError(t: Throwable?): Boolean {\n        return t is HttpStatusException && t.code == 405\n    }\n\n    private fun saveLastDateHeader(response: Response<*>) {\n        lastDateHeader = response.headers().getInstant(\"date\")\n    }\n\n    companion object {\n        // Artificial upper limit on the number of continuation cycles we can do, to prevent\n        // getting stuck in an infinite loop.\n        private const val MAX_CONTINUE_CYCLES = 256\n    }\n}","file":"app/src/main/java/org/wikipedia/readinglist/sync/ReadingListClient.kt","kind":"class","line":11,"members":{"MAX_CONTINUE_CYCLES":[195,197],"addPageToList":[140,146],"addPagesToList":[148,171],"allLists":[44,45],"createList":[122,128],"deleteList":[135,138],"deletePageFromList":[173,176],"getChangesSince":[63,82],"getListEntries":[104,120],"getListsContaining":[84,102],"isErrorType":[178,180],"isServiceError":[182,184],"isUnavailableError":[186,188],"lastDateHeader":[12,12],"saveLastDateHeader":[190,192],"setup":[15,30],"tearDown":[32,42],"updateList":[130,133],"wiki":[11,11]},"supers":[]},"ReadingListPage":{"appearsIn":[["saved","h-classes","Logic \u00b7 class diagram"]],"code":"@Entity\ndata class ReadingListPage(\n    val wiki: WikiSite,\n    val namespace: Namespace,\n    var displayTitle: String,\n    var apiTitle: String,\n    var description: String? = null,\n    var thumbUrl: String? = null,\n    var listId: Long = -1,\n    @PrimaryKey(autoGenerate = true) var id: Long = 0,\n    var mtime: Long = 0,\n    var atime: Long = 0,\n    var offline: Boolean = Prefs.isDownloadingReadingListArticlesEnabled,\n    var status: Long = STATUS_QUEUE_FOR_SAVE,\n    var sizeBytes: Long = 0,\n    var lang: String = \"en\",\n    var revId: Long = 0,\n    var remoteId: Long = 0\n) : Serializable {\n\n    constructor(title: PageTitle) :\n            this(title.wikiSite, title.namespace(), title.displayText, title.prefixedText,\n                title.description, title.thumbUrl, lang = title.wikiSite.languageCode) {\n        val now = System.currentTimeMillis()\n        mtime = now\n        atime = now\n    }\n\n    @delegate:Transient\n    val accentInvariantTitle: String by lazy {\n        StringUtils.stripAccents(StringUtil.fromHtml(displayTitle).toString())\n    }\n\n    @Transient var downloadProgress = 0\n\n    @Transient var selected = false\n\n    val saving get() = offline && (status == STATUS_QUEUE_FOR_SAVE || status == STATUS_QUEUE_FOR_FORCED_SAVE)\n\n    companion object {\n        const val STATUS_QUEUE_FOR_SAVE = 0L\n        const val STATUS_SAVED = 1L\n        const val STATUS_QUEUE_FOR_DELETE = 2L\n        const val STATUS_QUEUE_FOR_FORCED_SAVE = 3L\n\n        fun toPageSummary(page: ReadingListPage): PageSummary {\n            return PageSummary(page.displayTitle, page.apiTitle, page.description, page.description, page.thumbUrl, page.lang)\n        }\n\n        fun toPageTitle(page: ReadingListPage): PageTitle {\n            val wiki = page.wiki\n            wiki.languageCode = page.lang\n            return PageTitle(page.apiTitle, wiki, page.thumbUrl, page.description, page.displayTitle)\n        }\n    }\n}","file":"app/src/main/java/org/wikipedia/readinglist/database/ReadingListPage.kt","kind":"data class","line":14,"members":{"STATUS_QUEUE_FOR_DELETE":[56,56],"STATUS_QUEUE_FOR_FORCED_SAVE":[57,57],"STATUS_QUEUE_FOR_SAVE":[54,54],"STATUS_SAVED":[55,55],"accentInvariantTitle":[42,45],"apiTitle":[19,19],"atime":[25,25],"constructor":[34,40],"description":[20,20],"displayTitle":[18,18],"downloadProgress":[47,47],"id":[23,23],"lang":[29,29],"listId":[22,22],"mtime":[24,24],"namespace":[17,17],"offline":[26,26],"remoteId":[31,31],"revId":[30,30],"saving":[51,51],"selected":[49,49],"sizeBytes":[28,28],"status":[27,27],"thumbUrl":[21,21],"toPageSummary":[59,61],"toPageTitle":[63,67],"wiki":[16,16]},"supers":["Serializable"]},"ReadingListPageDao":{"appearsIn":[["saved","h-classes","Logic \u00b7 class diagram"],["saved","h-sequence","Save an article and sync it \u00b7 sequence"]],"code":"@Dao\ninterface ReadingListPageDao {\n    @Insert(onConflict = OnConflictStrategy.REPLACE)\n    suspend fun insertReadingListPage(page: ReadingListPage): Long\n\n    @Update(onConflict = OnConflictStrategy.REPLACE)\n    suspend fun updateReadingListPage(page: ReadingListPage)\n\n    @Update(onConflict = OnConflictStrategy.REPLACE)\n    suspend fun updateReadingListPages(pages: List<ReadingListPage>)\n\n    @Delete\n    suspend fun deleteReadingListPage(page: ReadingListPage)\n\n    @Query(\"SELECT COUNT(*) FROM ReadingListPage\")\n    suspend fun getPagesCount(): Int\n\n    @Query(\"SELECT COUNT(*) FROM (SELECT DISTINCT lang, apiTitle, wiki, namespace FROM ReadingListPage WHERE status != :excludedStatus)\")\n    suspend fun getDistinctPagesCount(excludedStatus: Long): Int\n\n    @Query(\"SELECT * FROM ReadingListPage WHERE id = :id\")\n    suspend fun getPageById(id: Long): ReadingListPage?\n\n    @Query(\"SELECT * FROM ReadingListPage WHERE id IN (:ids)\")\n    suspend fun getPagesByIds(ids: Set<Long>): List<ReadingListPage>\n\n    @Query(\"SELECT * FROM ReadingListPage WHERE status = :status AND offline = :offline\")\n    suspend fun getPagesByStatus(status: Long, offline: Boolean): List<ReadingListPage>\n\n    @Query(\"SELECT * FROM ReadingListPage WHERE status = :status\")\n    suspend fun getPagesByStatus(status: Long): List<ReadingListPage>\n\n    @Query(\"SELECT * FROM ReadingListPage WHERE wiki = :wiki AND lang = :lang AND namespace = :ns AND apiTitle = :apiTitle AND listId = :listId AND status != :excludedStatus\")\n    suspend fun getPageByParams(wiki: WikiSite, lang: String, ns: Namespace,\n        apiTitle: String, listId: Long, excludedStatus: Long): ReadingListPage?\n\n    @Query(\"SELECT * FROM ReadingListPage WHERE wiki = :wiki AND lang = :lang AND namespace = :ns AND apiTitle = :apiTitle AND status != :excludedStatus\")\n    suspend fun getPageByParams(wiki: WikiSite, lang: String, ns: Namespace,\n        apiTitle: String, excludedStatus: Long): ReadingListPage?\n\n    @Query(\"SELECT * FROM ReadingListPage WHERE wiki = :wiki AND lang = :lang AND namespace = :ns AND apiTitle = :apiTitle AND status != :excludedStatus\")\n    suspend fun getPagesByParams(wiki: WikiSite, lang: String, ns: Namespace,\n        apiTitle: String, excludedStatus: Long): List<ReadingListPage>\n\n    @Query(\"SELECT * FROM ReadingListPage ORDER BY RANDOM() DESC LIMIT :limit\")\n    suspend fun getPagesByRandom(limit: Int): List<ReadingListPage>\n\n    @Query(\"SELECT * FROM ReadingListPage WHERE listId = :listId AND status != :excludedStatus\")\n    suspend fun getPagesByListId(listId: Long, excludedStatus: Long): List<ReadingListPage>\n\n    @Query(\"UPDATE ReadingListPage SET thumbUrl = :thumbUrl, description = :description WHERE lang = :lang AND apiTitle = :apiTitle\")\n    suspend fun updateThumbAndDescriptionByName(lang: String, apiTitle: String, thumbUrl: String?, description: String?)\n\n    @Query(\"UPDATE ReadingListPage SET status = :newStatus WHERE status = :oldStatus AND offline = :offline\")\n    suspend fun updateStatus(oldStatus: Long, newStatus: Long, offline: Boolean)\n\n    @Query(\"SELECT * FROM ReadingListPage WHERE lang = :lang ORDER BY RANDOM() LIMIT 1\")\n    suspend fun getRandomPage(lang: String): ReadingListPage?\n\n    @Query(\"SELECT * FROM ReadingListPage WHERE atime BETWEEN :startMillis AND :endMillis AND status != :excludedStatus GROUP BY lang, apiTitle, wiki, namespace ORDER BY RANDOM() LIMIT :limit\")\n    suspend fun getRandomDistinctSavedPagesBetween(startMillis: Long, endMillis: Long, excludedStatus: Long, limit: Int): List<ReadingListPage>\n\n    @Query(\"SELECT * FROM ReadingListPage WHERE UPPER(displayTitle) LIKE UPPER(:term) ESCAPE '\\\\'\")\n    suspend fun findPageBySearchTerm(term: String): List<ReadingListPage>\n\n    @Query(\"DELETE FROM ReadingListPage WHERE status = :status\")\n    suspend fun deletePagesByStatus(status: Long)\n\n    @Query(\"UPDATE ReadingListPage SET remoteId = -1\")\n    suspend fun markAllPagesUnsynced()\n\n    @Query(\"SELECT * FROM ReadingListPage WHERE remoteId < 1\")\n    suspend fun getAllPagesToBeSynced(): List<ReadingListPage>\n\n    @Query(\"SELECT COUNT(*) FROM ReadingListPage WHERE atime > 0 AND atime BETWEEN :startMillis AND :endMillis\")\n    suspend fun getTotalSavedPagesBetween(startMillis: Long, endMillis: Long = System.currentTimeMillis()): Int?\n\n    @Query(\"SELECT COUNT(*) FROM (SELECT DISTINCT lang, apiTitle, wiki, namespace FROM ReadingListPage WHERE atime BETWEEN :startMillis AND :endMillis AND status != :excludedStatus)\")\n    suspend fun getDistinctSavedPagesCountBetween(startMillis: Long, endMillis: Long, excludedStatus: Long): Int\n\n    @Query(\"SELECT * FROM ReadingListPage WHERE atime > 0 AND atime > :timestamp ORDER BY atime DESC LIMIT :limit\")\n    suspend fun getSavedPagesSince(timestamp: Long, limit: Int): List<ReadingListPage>\n\n    @Query(\"SELECT * FROM ReadingListPage WHERE atime > 0 ORDER BY atime DESC LIMIT 1\")\n    suspend fun getMostRecentSavedPage(): ReadingListPage?\n\n    @Query(\"SELECT * FROM ReadingListPage WHERE lang = :langCode GROUP BY apiTitle ORDER BY atime DESC LIMIT :limit\")\n    suspend fun getMostRecentSavedPagesByLang(langCode: String, limit: Int): List<ReadingListPage>\n\n    @Query(\"SELECT * FROM ReadingListPage WHERE atime > 0 ORDER BY atime DESC LIMIT :limit OFFSET :offset\")\n    suspend fun getPagesBySavedTime(limit: Int, offset: Int): List<ReadingListPage>\n\n    @Query(\"SELECT apiTitle FROM ReadingListPage WHERE lang = :lang AND apiTitle IN (:apiTitles) AND status != :excludedStatus\")\n    fun observeSavedApiTitles(lang: String, apiTitles: List<String>, excludedStatus: Long): Flow<List<String>>\n\n    suspend fun getAllPagesToBeSaved() = getPagesByStatus(ReadingListPage.STATUS_QUEUE_FOR_SAVE, true)\n\n    suspend fun getAllPagesToBeForcedSave() = getPagesByStatus(ReadingListPage.STATUS_QUEUE_FOR_FORCED_SAVE, true)\n\n    suspend fun getAllPagesToBeUnsaved() = getPagesByStatus(ReadingListPage.STATUS_SAVED, false)\n\n    suspend fun getAllPagesToBeDeleted() = getPagesByStatus(ReadingListPage.STATUS_QUEUE_FOR_DELETE)\n\n    suspend fun populateListPages(list: ReadingList) {\n        list.pages.addAll(getPagesByListId(list.id, ReadingListPage.STATUS_QUEUE_FOR_DELETE))\n    }\n\n    @Transaction\n    suspend fun addPagesToList(list: ReadingList, pages: List<ReadingListPage>, queueForSync: Boolean) {\n        for (page in pages) {\n            insertPageIntoDb(list, page)\n        }\n        FlowEventBus.post(ArticleSavedOrDeletedEvent(true, *pages.toTypedArray()))\n        SavedPageSyncService.enqueue()\n        if (queueForSync) {\n            ReadingListSyncAdapter.manualSync()\n        }\n    }\n\n    @Transaction\n    suspend fun addPagesToListIfNotExist(list: ReadingList, titles: List<PageTitle>): List<String> {\n        val pages = mutableListOf<ReadingListPage>()\n        for (title in titles) {\n            if (getPageByTitle(list, title) != null) {\n                continue\n            }\n            val page = addPageToList(list, title)\n            pages.add(page)\n        }\n        if (pages.isNotEmpty()) {\n            SavedPageSyncService.enqueue()\n            ReadingListSyncAdapter.manualSync()\n            FlowEventBus.post(ArticleSavedOrDeletedEvent(true, *pages.toTypedArray()))\n        }\n        return pages.map { it.displayTitle }\n    }\n\n    @Transaction\n    suspend fun findPageInAnyList(title: PageTitle): ReadingListPage? {\n        return getPageByParams(\n            title.wikiSite, title.wikiSite.languageCode, title.namespace(),\n            title.prefixedText, ReadingListPage.STATUS_QUEUE_FOR_DELETE\n        )\n    }\n\n    suspend fun findPageForSearchQueryInAnyList(wikiSite: WikiSite, searchQuery: String): SearchResults {\n        var normalizedQuery = StringUtils.stripAccents(searchQuery)\n        if (normalizedQuery.isEmpty()) {\n            return SearchResults()\n        }\n        normalizedQuery = normalizedQuery.replace(\"\\\\\", \"\\\\\\\\\")\n            .replace(\"%\", \"\\\\%\").replace(\"_\", \"\\\\_\")\n\n        val pages = findPageBySearchTerm(\"%$normalizedQuery%\")\n                .filter { wikiSite.languageCode == it.lang && StringUtil.fromHtml(it.accentInvariantTitle).contains(normalizedQuery, true) }\n\n        return if (pages.isEmpty()) SearchResults()\n        else SearchResults(pages.take(2).map {\n            SearchResult(PageTitle(it.apiTitle, it.wiki, it.thumbUrl, it.description, it.displayTitle), SearchResult.SearchResultType.READING_LIST)\n        }.toMutableList())\n    }\n\n    @Transaction\n    suspend fun markPagesForDeletion(list: ReadingList, pages: List<ReadingListPage>, queueForSync: Boolean = true) {\n        for (page in pages) {\n            page.status = ReadingListPage.STATUS_QUEUE_FOR_DELETE\n            updateReadingListPage(page)\n        }\n        if (queueForSync) {\n            ReadingListSyncAdapter.manualSyncWithDeletePages(list, pages)\n        }\n        FlowEventBus.post(ArticleSavedOrDeletedEvent(false, *pages.toTypedArray()))\n        SavedPageSyncService.enqueue()\n    }\n\n    @Transaction\n    suspend fun markPagesForDeletionFromLists(lists: List<ReadingList>) {\n        val pages = lists.flatMap { it.pages }\n        pages.forEach { it.status = ReadingListPage.STATUS_QUEUE_FOR_DELETE }\n        updateReadingListPages(pages)\n        ReadingListSyncAdapter.manualSyncWithDeletePages(lists)\n        FlowEventBus.post(ArticleSavedOrDeletedEvent(false, *pages.toTypedArray()))\n        SavedPageSyncService.enqueue()\n    }\n\n    @Transaction\n    suspend fun markPagesForOffline(pages: List<ReadingListPage>, offline: Boolean, forcedSave: Boolean) {\n        val updatedPages = pages.map {\n            if (it.offline != offline || !forcedSave) {\n                it.offline = offline\n                if (forcedSave) {\n                    it.status = ReadingListPage.STATUS_QUEUE_FOR_FORCED_SAVE\n                }\n            }\n            it\n        }\n        updateReadingListPages(updatedPages)\n        SavedPageSyncService.enqueue()\n    }\n\n    suspend fun purgeDeletedPages() {\n        deletePagesByStatus(ReadingListPage.STATUS_QUEUE_FOR_DELETE)\n    }\n\n    @Transaction\n    suspend fun movePagesToListAndDeleteSourcePages(sourceList: ReadingList, destList: ReadingList, titles: List<PageTitle>): List<String> {\n        val movedTitles = mutableListOf<String>()\n        for (title in titles) {\n            movePageToList(sourceList, destList, title)\n            movedTitles.add(title.displayText)\n        }\n        if (movedTitles.isNotEmpty()) {\n            SavedPageSyncService.enqueue()\n            ReadingListSyncAdapter.manualSync()\n        }\n        return movedTitles\n    }\n\n    @Transaction\n    suspend fun movePageToList(sourceList: ReadingList, destList: ReadingList, title: PageTitle) {\n        if (sourceList.id == destList.id) {\n            return\n        }\n        val sourceReadingListPage = getPageByTitle(sourceList, title)\n        if (sourceReadingListPage != null) {\n            if (getPageByTitle(destList, title) == null) {\n                val page = addPageToList(destList, title)\n                FlowEventBus.post(ArticleSavedOrDeletedEvent(true, page))\n            }\n            markPagesForDeletion(sourceList, listOf(sourceReadingListPage))\n            ReadingListSyncAdapter.manualSync()\n            SavedPageSyncService.sendSyncEvent()\n        }\n    }\n\n    suspend fun getPageByTitle(list: ReadingList, title: PageTitle): ReadingListPage? {\n        return getPageByParams(\n            title.wikiSite, title.wikiSite.languageCode, title.namespace(),\n            title.prefixedText, list.id, ReadingListPage.STATUS_QUEUE_FOR_DELETE\n        )\n    }\n\n    suspend fun addPageToLists(lists: List<ReadingList>, page: ReadingListPage, queueForSync: Boolean) {\n        for (list in lists) {\n            if (getPageByTitle(list, ReadingListPage.toPageTitle(page)) != null) {\n                continue\n            }\n            page.status = ReadingListPage.STATUS_QUEUE_FOR_SAVE\n            insertPageIntoDb(list, page)\n        }\n        FlowEventBus.post(ArticleSavedOrDeletedEvent(true, page))\n\n        SavedPageSyncService.enqueue()\n        if (queueForSync) {\n            ReadingListSyncAdapter.manualSync()\n        }\n    }\n\n    suspend fun getAllPageOccurrences(title: PageTitle): List<ReadingListPage> {\n        return getPagesByParams(\n            title.wikiSite, title.wikiSite.languageCode, title.namespace(),\n            title.prefixedText, ReadingListPage.STATUS_QUEUE_FOR_DELETE\n        )\n    }\n\n    private suspend fun addPageToList(list: ReadingList, title: PageTitle): ReadingListPage {\n        val protoPage = ReadingListPage(title)\n        insertPageIntoDb(list, protoPage)\n        return protoPage\n    }\n\n    private suspend fun insertPageIntoDb(list: ReadingList, page: ReadingListPage) {\n        page.listId = list.id\n        page.id = insertReadingListPage(page)\n    }\n}","file":"app/src/main/java/org/wikipedia/readinglist/db/ReadingListPageDao.kt","kind":"interface","line":25,"members":{"addPageToList":[290,294],"addPageToLists":[267,281],"addPagesToList":[132,142],"addPagesToListIfNotExist":[144,160],"deletePagesByStatus":[90,91],"deleteReadingListPage":[36,37],"findPageBySearchTerm":[87,88],"findPageForSearchQueryInAnyList":[170,185],"findPageInAnyList":[162,168],"getAllPageOccurrences":[283,288],"getAllPagesToBeDeleted":[126,126],"getAllPagesToBeForcedSave":[122,122],"getAllPagesToBeSaved":[120,120],"getAllPagesToBeSynced":[96,97],"getAllPagesToBeUnsaved":[124,124],"getDistinctPagesCount":[42,43],"getDistinctSavedPagesCountBetween":[102,103],"getMostRecentSavedPage":[108,109],"getMostRecentSavedPagesByLang":[111,112],"getPageById":[45,46],"getPageByParams":[57,59],"getPageByTitle":[260,265],"getPagesByIds":[48,49],"getPagesByListId":[72,73],"getPagesByParams":[65,67],"getPagesByRandom":[69,70],"getPagesBySavedTime":[114,115],"getPagesByStatus":[51,52],"getPagesCount":[39,40],"getRandomDistinctSavedPagesBetween":[84,85],"getRandomPage":[81,82],"getSavedPagesSince":[105,106],"getTotalSavedPagesBetween":[99,100],"insertPageIntoDb":[296,299],"insertReadingListPage":[27,28],"markAllPagesUnsynced":[93,94],"markPagesForDeletion":[187,198],"markPagesForDeletionFromLists":[200,208],"markPagesForOffline":[210,223],"movePageToList":[243,258],"movePagesToListAndDeleteSourcePages":[229,241],"observeSavedApiTitles":[117,118],"populateListPages":[128,130],"purgeDeletedPages":[225,227],"updateReadingListPage":[30,31],"updateReadingListPages":[33,34],"updateStatus":[78,79],"updateThumbAndDescriptionByName":[75,76]},"supers":[]},"ReadingListPageRow":{"appearsIn":[["saved","h-widgets","Screen \u00b7 composition"]],"code":"@Composable\nfun ReadingListPageRow(\n    page: ReadingListPageUiModel,\n    containingLists: List<ContainingList>,\n    modifier: Modifier = Modifier,\n    downloadProgress: Int = 0,\n    isSelectionMode: Boolean = false,\n    isSelected: Boolean = false,\n    onSelectionChange: () -> Unit = {},\n    onClick: () -> Unit = {},\n    onLongClick: () -> Unit = {},\n    onToggleOfflineClick: () -> Unit = {},\n    onChipClick: (Long) -> Unit = {}\n) {\n    Row(\n        modifier = modifier\n            .combinedClickable(\n                onClick = if (isSelectionMode) onSelectionChange else onClick,\n                onLongClick = if (isSelectionMode) onSelectionChange else onLongClick\n            )\n            .padding(horizontal = 16.dp, vertical = 16.dp),\n        verticalAlignment = Alignment.Top\n    ) {\n        if (isSelectionMode) {\n            Checkbox(\n                checked = isSelected,\n                onCheckedChange = { onSelectionChange() },\n                colors = CheckboxDefaults.colors(\n                    checkedColor = ComposeColors.Blue600,\n                    uncheckedColor = WikipediaTheme.colors.primaryColor\n                ),\n                modifier = Modifier.padding(end = 16.dp)\n            )\n        }\n        Column(modifier = Modifier.weight(1f)) {\n            val alpha = if (page.isAvailable) 1f else 0.5f\n            HtmlText(\n                modifier = Modifier.alpha(alpha),\n                text = page.title,\n                color = WikipediaTheme.colors.primaryColor,\n                style = MaterialTheme.typography.bodyLarge.copy(\n                    fontWeight = FontWeight.Bold\n                ),\n                maxLines = 2,\n                overflow = TextOverflow.Ellipsis\n            )\n            if (!page.description.isNullOrEmpty()) {\n                Spacer(modifier = Modifier.size(6.dp))\n                Text(\n                    modifier = Modifier.alpha(alpha),\n                    text = page.description,\n                    color = WikipediaTheme.colors.secondaryColor,\n                    style = MaterialTheme.typography.bodyMedium.copy(\n                        lineHeight = 24.sp\n                    ),\n                    maxLines = 2,\n                    overflow = TextOverflow.Ellipsis\n                )\n            }\n\n            val customLists = containingLists.filterNot { it.isDefault }\n            if (customLists.isNotEmpty()) {\n                FlowRow(\n                    modifier = Modifier.padding(top = 8.dp),\n                    horizontalArrangement = spacedBy(8.dp)\n                ) {\n                    customLists.forEach { list ->\n                        ListChip(\n                            title = list.title,\n                            onClick = {\n                                if (isSelectionMode) onSelectionChange() else onChipClick(list.id)\n                            }\n                        )\n                    }\n                }\n            }\n        }\n\n        if (!isSelectionMode && (!page.offline || page.saving)) {\n            Spacer(modifier = Modifier.width(16.dp))\n            Box(\n                modifier = Modifier\n                    .padding(top = (THUMBNAIL_SIZE - DOWNLOAD_BUTTON_SIZE) / 2)\n                    .size(DOWNLOAD_BUTTON_SIZE)\n                    .clickable(onClick = onToggleOfflineClick),\n                contentAlignment = Alignment.Center\n            ) {\n                if (downloadProgress in 1 until 100) {\n                    CircularProgressIndicator(\n                        progress = { downloadProgress / 100f },\n                        modifier = Modifier.size(28.dp),\n                        color = WikipediaTheme.colors.progressiveColor,\n                        trackColor = WikipediaTheme.colors.borderColor,\n                        strokeWidth = 3.dp\n                    )\n                } else {\n                    Icon(\n                        painter = painterResource(\n                            if (page.saving) R.drawable.ic_download_in_progress\n                            else R.drawable.ic_download_circle_gray_24dp\n                        ),\n                        contentDescription = stringResource(R.string.reading_list_article_make_offline),\n                        tint = if (page.saving) WikipediaTheme.colors.progressiveColor\n                        else WikipediaTheme.colors.placeholderColor,\n                        modifier = Modifier.size(24.dp)\n                    )\n                }\n            }\n        }\n\n        if (!page.thumbUrl.isNullOrEmpty()) {\n            Spacer(modifier = Modifier.width(16.dp))\n            ArticleThumbnail(\n                thumbUrl = page.thumbUrl,\n                modifier = Modifier.alpha(if (page.isAvailable) 1f else 0.5f)\n            )\n        }\n    }\n}","file":"app/src/main/java/org/wikipedia/readinglist/compose/ReadingListPageRow.kt","kind":"composable function","line":50,"members":{},"supers":[]},"ReadingListRow":{"alsoIn":["app/src/main/java/org/wikipedia/readinglist/compose/ReadingListRow.kt"],"appearsIn":[["saved","h-widgets","Screen \u00b7 composition"]],"code":"/**\n * A single row in the \"Saved\" list. Normally the screen only shows [ListRow]s; while searching it\n * shows matching [ListRow]s followed by matching [PageRow]s (articles found across all lists).\n */\nsealed interface ReadingListRow {\n    data class ListRow(val list: ReadingListUiModel) : ReadingListRow\n    data class PageRow(val page: ReadingListPageUiModel, val containingLists: List<ContainingList>) : ReadingListRow\n}","file":"app/src/main/java/org/wikipedia/readinglist/ReadingListsViewModel.kt","kind":"interface","line":589,"members":{"ListRow":[594,594],"PageRow":[595,595]},"supers":[]},"ReadingListSyncAdapter":{"appearsIn":[["index","h-services","Services \u00b7 what the screens share"],["saved","h-classes","Logic \u00b7 class diagram"],["saved","h-sequence","Save an article and sync it \u00b7 sequence"]],"code":"class ReadingListSyncAdapter(context: Context, params: WorkerParameters) : CoroutineWorker(context, params) {\n\n    override suspend fun doWork(): Result {\n        return withContext(Dispatchers.IO) {\n            val extras = getBooleanExtraFromData(inputData)\n            if (RemoteConfig.config.disableReadingListSync || !AccountUtil.isLoggedIn || AccountUtil.isTemporaryAccount ||\n                !(Prefs.isReadingListSyncEnabled || Prefs.isReadingListsRemoteDeletePending)) {\n                L.d(\"Skipping sync of reading lists.\")\n                if (extras.containsKey(SYNC_EXTRAS_REFRESHING)) {\n                    SavedPageSyncService.sendSyncEvent()\n                }\n                return@withContext Result.success()\n            }\n            L.d(\"Begin sync of reading lists...\")\n            val listIdsDeleted = Prefs.readingListsDeletedIds.toMutableSet()\n            val pageIdsDeleted = Prefs.readingListPagesDeletedIds.toMutableSet()\n            var allLocalLists: MutableList<ReadingList>? = null\n            val wiki = WikipediaApp.instance.wikiSite\n            val client = ReadingListClient(wiki)\n            val readingListSyncNotification = ReadingListSyncNotification.instance\n            val lastSyncTime = Prefs.readingListsLastSyncTime.orEmpty()\n            var shouldSendSyncEvent = extras.containsKey(SYNC_EXTRAS_REFRESHING)\n            var shouldRetry = false\n            var shouldRetryWithForce = false\n            try {\n                IN_PROGRESS = true\n                var syncEverything = false\n                if (extras.containsKey(SYNC_EXTRAS_FORCE_FULL_SYNC) ||\n                    Prefs.isReadingListsRemoteDeletePending ||\n                    Prefs.isReadingListsRemoteSetupPending) {\n                    // reset the remote ID on all lists, since they will need to be recreated next time.\n                    L.d(\"Resetting all lists to un-synced.\")\n                    syncEverything = true\n                    AppDatabase.instance.readingListDao().markAllListsUnsynced()\n                    AppDatabase.instance.readingListPageDao().markAllPagesUnsynced()\n                    allLocalLists = AppDatabase.instance.readingListDao().getAllLists().toMutableList()\n                }\n\n                val csrfToken = CsrfTokenClient.getToken(wiki)\n\n                if (Prefs.isReadingListsRemoteDeletePending) {\n                    // Are we scheduled for a teardown? If so, delete everything and bail.\n                    L.d(\"Tearing down remote lists...\")\n                    client.tearDown(csrfToken)\n                    Prefs.isReadingListsRemoteDeletePending = false\n                    return@withContext Result.success()\n                } else if (Prefs.isReadingListsRemoteSetupPending) {\n                    // ...Or are we scheduled for setup?\n                    client.setup(csrfToken)\n                    Prefs.isReadingListsRemoteSetupPending = false\n                }\n\n                // -----------------------------------------------\n                // PHASE 1: Sync from remote to local.\n                // -----------------------------------------------\n                var remoteListsModified = mutableListOf<RemoteReadingList>()\n                var remoteEntriesModified = mutableListOf<RemoteReadingListEntry>()\n                if (lastSyncTime.isEmpty()) {\n                    syncEverything = true\n                }\n\n                if (!syncEverything) {\n                    try {\n                        L.d(\"Fetching changes from server, since $lastSyncTime\")\n                        val allChanges = client.getChangesSince(lastSyncTime)\n                        allChanges.lists?.let {\n                            remoteListsModified = it as MutableList<RemoteReadingList>\n                        }\n                        allChanges.entries?.let {\n                            remoteEntriesModified = it as MutableList<RemoteReadingListEntry>\n                        }\n                    } catch (t: Throwable) {\n                        if (client.isErrorType(t, \"too-old\")) {\n                            // If too much time has elapsed between syncs, then perform a full sync.\n                            syncEverything = true\n                        } else {\n                            throw t\n                        }\n                    }\n                }\n\n                if (allLocalLists == null) {\n                    allLocalLists = if (syncEverything) {\n                        AppDatabase.instance.readingListDao().getAllLists().toMutableList()\n                    } else {\n                        AppDatabase.instance.readingListDao().getAllListsWithUnsyncedPages().toMutableList()\n                    }\n                }\n\n                        // Perform a quick check for whether we'll need to sync all lists\n                for (remoteEntry in remoteEntriesModified) {\n                    // find the list to which this entry belongs...\n                    val eigenLocalList = allLocalLists.find { it.remoteId == remoteEntry.listId }\n                    val eigenRemoteList = remoteListsModified.find { it.id == remoteEntry.listId }\n\n                    if (eigenLocalList == null && eigenRemoteList == null) {\n                        L.w(\"Remote entry belongs to an unknown local list. Falling back to full sync.\")\n                        syncEverything = true\n                        break\n                    }\n                }\n                if (syncEverything) {\n                    allLocalLists = AppDatabase.instance.readingListDao().getAllLists().toMutableList()\n                    L.d(\"Fetching all lists from server...\")\n                    remoteListsModified = client.allLists as MutableList<RemoteReadingList>\n                }\n\n                // Notify any event consumers that reading lists are, in fact, enabled.\n                FlowEventBus.post(ReadingListsEnabledStatusEvent())\n\n                // setup syncing indicator for remote to local\n                val remoteItemsTotal = remoteListsModified.size\n\n                // First, update our list hierarchy to match the remote hierarchy.\n                for ((remoteItemsSynced, remoteList) in remoteListsModified.withIndex()) {\n                    readingListSyncNotification.setNotificationProgress(applicationContext, remoteItemsTotal, remoteItemsSynced)\n                    // Find the remote list in our local lists...\n                    var localList: ReadingList? = null\n                    var upsertNeeded = false\n                    for (list in allLocalLists) {\n                        if (list.isDefault && remoteList.isDefault) {\n                            localList = list\n                            if (list.remoteId != remoteList.id) {\n                                list.remoteId = remoteList.id\n                                upsertNeeded = true\n                            }\n                            break\n                        }\n                        if (list.remoteId == remoteList.id) {\n                            localList = list\n                            break\n                        } else if (StringUtil.normalizedEquals(list.title, remoteList.name())) {\n                            localList = list\n                            localList.remoteId = remoteList.id\n                            upsertNeeded = true\n                            break\n                        }\n                    }\n                    if (remoteList.isDefault && localList != null && !localList.isDefault) {\n                        L.logRemoteError(RuntimeException(\"Unexpected: remote default list corresponds to local non-default list.\"))\n                        localList = AppDatabase.instance.readingListDao().getDefaultList()\n                    }\n                    if (remoteList.isDeleted) {\n                        if (localList != null && !localList.isDefault) {\n                            L.d(\"Deleting local list \" + localList.title)\n                            AppDatabase.instance.readingListDao().deleteList(localList, false)\n                            AppDatabase.instance.readingListPageDao().markPagesForDeletion(localList, localList.pages, false)\n                            allLocalLists.remove(localList)\n                            shouldSendSyncEvent = true\n                        }\n                        continue\n                    }\n                    if (localList == null) {\n                        // A new list needs to be created locally.\n                        L.d(\"Creating local list \" + remoteList.name())\n                        localList = if (remoteList.isDefault) {\n                            L.logRemoteError(RuntimeException(\"Unexpected: local default list no longer matches remote.\"))\n                            AppDatabase.instance.readingListDao().getDefaultList()\n                        } else {\n                            AppDatabase.instance.readingListDao().createList(remoteList.name(), remoteList.description())\n                        }\n                        localList.remoteId = remoteList.id\n                        localList.atime = remoteList.created.toInstant(ZoneOffset.UTC).toEpochMilli()\n                        localList.mtime = remoteList.updated.toInstant(ZoneOffset.UTC).toEpochMilli()\n                        allLocalLists.add(localList)\n                        upsertNeeded = true\n                    } else {\n                        if (!localList.isDefault && !StringUtil.normalizedEquals(localList.title, remoteList.name())) {\n                            localList.title = remoteList.name()\n                            upsertNeeded = true\n                        }\n                        if (!localList.isDefault && !StringUtil.normalizedEquals(localList.description, remoteList.description())) {\n                            localList.description = remoteList.description()\n                            upsertNeeded = true\n                        }\n                    }\n                    if (upsertNeeded) {\n                        L.d(\"Updating info for local list \" + localList.title)\n                        localList.dirty = false\n                        AppDatabase.instance.readingListDao().updateList(localList, false)\n                        shouldSendSyncEvent = true\n                    }\n                    if (syncEverything) {\n                        L.d(\"Fetching all pages in remote list \" + remoteList.name())\n                        client.getListEntries(remoteList.id).forEach {\n                            // TODO: optimization opportunity -- create/update local pages in bulk.\n                            createOrUpdatePage(localList, it)\n                        }\n                        shouldSendSyncEvent = true\n                    }\n                }\n                if (!syncEverything) {\n                    for (remoteEntry in remoteEntriesModified) {\n                        // find the list to which this entry belongs...\n                        val eigenList = allLocalLists.find { it.remoteId == remoteEntry.listId }\n                        if (eigenList == null) {\n                            L.w(\"Remote entry belongs to an unknown local list.\")\n                            continue\n                        }\n                        shouldSendSyncEvent = true\n                        if (remoteEntry.isDeleted) {\n                            deletePageByTitle(eigenList, pageTitleFromRemoteEntry(remoteEntry))\n                        } else {\n                            createOrUpdatePage(eigenList, remoteEntry)\n                        }\n                    }\n                }\n\n                // -----------------------------------------------\n                // PHASE 2: Sync from local to remote.\n                // -----------------------------------------------\n\n                // Do any remote lists need to be deleted?\n                val listIdsToDelete = mutableListOf<Long>()\n                listIdsToDelete.addAll(listIdsDeleted)\n                for (id in listIdsToDelete) {\n                    L.d(\"Deleting remote list id $id\")\n                    try {\n                        client.deleteList(csrfToken, id)\n                    } catch (t: Throwable) {\n                        L.w(t)\n                        if (!client.isServiceError(t) && !client.isUnavailableError(t)) {\n                            throw t\n                        }\n                    }\n                    listIdsDeleted.remove(id)\n                }\n\n                // Do any remote pages need to be deleted?\n                val pageIdsToDelete = pageIdsDeleted.toMutableSet()\n\n                // Determine if any articles need to be de-duplicated (because of bugs in previous sync inconsistencies)\n                if (syncEverything) {\n                    allLocalLists.forEach { list ->\n                        val distinct = list.pages.distinctBy { pageTitleFromRemoteEntry(remoteEntryFromLocalPage(it)) }\n                        val toRemove = list.pages.toMutableSet()\n                        toRemove.removeAll(distinct.toSet())\n                        if (toRemove.isNotEmpty()) {\n                            toRemove.forEach {\n                                AppDatabase.instance.readingListPageDao().deleteReadingListPage(it)\n                            }\n                            pageIdsToDelete.addAll(createIdsForDeletion(list, toRemove))\n                        }\n                    }\n                }\n\n                for (id in pageIdsToDelete) {\n                    L.d(\"Deleting remote page id $id\")\n                    val listAndPageId = id.split(\":\").toTypedArray()\n                    try {\n                        // TODO: optimization opportunity once server starts supporting batch deletes.\n                        client.deletePageFromList(csrfToken, listAndPageId[0].toLong(), listAndPageId[1].toLong())\n                    } catch (t: Throwable) {\n                        L.w(t)\n                        if (!client.isServiceError(t) && !client.isUnavailableError(t)) {\n                            throw t\n                        }\n                    }\n                    pageIdsDeleted.remove(id)\n                }\n\n                // setup syncing indicator for local to remote\n                val localItemsTotal = allLocalLists.size\n\n                // Determine whether any remote lists need to be created or updated\n                for ((localItemsSynced, localList) in allLocalLists.withIndex()) {\n                    readingListSyncNotification.setNotificationProgress(applicationContext, localItemsTotal, localItemsSynced)\n                    val remoteList = RemoteReadingList(name = localList.title, description = localList.description)\n                    var upsertNeeded = false\n                    if (localList.remoteId > 0) {\n                        if (!localList.isDefault && localList.dirty) {\n                            // Update remote metadata for this list.\n                            L.d(\"Updating info for remote list \" + remoteList.name())\n                            client.updateList(csrfToken, localList.remoteId, remoteList)\n                            upsertNeeded = true\n                        }\n                    } else if (!localList.isDefault) {\n                        // This list needs to be created remotely.\n                        L.d(\"Creating remote list \" + remoteList.name())\n                        val id = client.createList(csrfToken, remoteList)\n                        localList.remoteId = id\n                        upsertNeeded = true\n                    }\n                    if (upsertNeeded) {\n                        localList.dirty = false\n                        AppDatabase.instance.readingListDao().updateList(localList, false)\n                    }\n                }\n                for (localList in allLocalLists) {\n                    val localPages = localList.pages.filter { it.remoteId < 1 }\n                    val newEntries = localPages.map { remoteEntryFromLocalPage(it) }\n                    // Note: newEntries.size() is guaranteed to be equal to localPages.size()\n                    if (newEntries.isEmpty()) {\n                        continue\n                    }\n                    var tryOneAtATime = false\n                    try {\n                        if (localPages.size == 1) {\n                            L.d(\"Creating new remote page \" + localPages[0].displayTitle)\n                            localPages[0].remoteId = client.addPageToList(csrfToken, localList.remoteId, newEntries[0])\n                            AppDatabase.instance.readingListPageDao().updateReadingListPage(localPages[0])\n                        } else {\n                            L.d(\"Creating \" + newEntries.size + \" new remote pages\")\n                            val ids = client.addPagesToList(csrfToken, localList.remoteId, newEntries)\n                            for (i in ids.indices) {\n                                localPages[i].remoteId = ids[i]\n                            }\n                            AppDatabase.instance.readingListPageDao().updateReadingListPages(localPages)\n                        }\n                    } catch (t: Throwable) {\n                        // TODO: optimization opportunity -- if the server can return the ID\n                        // of the existing page(s), then we wouldn't need to do a hard sync.\n\n                        // If the page already exists in the remote list, this means that\n                        // the contents of this list have diverged from the remote list,\n                        // so let's force a full sync.\n                        if (client.isErrorType(t, \"duplicate-page\")) {\n                            shouldRetryWithForce = true\n                            break\n                        } else if (client.isErrorType(t, \"entry-limit\")) {\n                            // TODO: handle more meaningfully than ignoring, for now.\n                        } else if (client.isErrorType(t, \"no-such-project\")) {\n                            // Something is malformed in the page domain, but we don't know which page\n                            // in the batch caused the error. Therefore, let's retry uploading the pages\n                            // one at a time, and single out the one that fails.\n                            tryOneAtATime = true\n                        } else {\n                            throw t\n                        }\n                    }\n                    if (tryOneAtATime) {\n                        for (i in localPages.indices) {\n                            val localPage = localPages[i]\n                            try {\n                                L.d(\"Creating new remote page \" + localPage.displayTitle)\n                                localPage.remoteId = client.addPageToList(csrfToken, localList.remoteId, newEntries[i])\n                            } catch (t: Throwable) {\n                                if (client.isErrorType(t, \"duplicate-page\")) {\n                                    shouldRetryWithForce = true\n                                    break\n                                } else if (client.isErrorType(t, \"entry-limit\")) {\n                                    // TODO: handle more meaningfully than ignoring, for now.\n                                } else if (client.isErrorType(t, \"no-such-project\")) {\n                                    // Ignore the error, and give this malformed page a bogus remoteID,\n                                    // so that we won't try syncing it again.\n                                    localPage.remoteId = Int.MAX_VALUE.toLong()\n                                    // ...and also log it:\n                                    L.logRemoteError(RuntimeException(\"Attempted to sync malformed page: ${localPage.wiki}, ${localPage.displayTitle}\"))\n                                } else {\n                                    throw t\n                                }\n                            }\n                        }\n                        AppDatabase.instance.readingListPageDao().updateReadingListPages(localPages)\n                    }\n                }\n            } catch (e: CancellationException) {\n                throw e\n            } catch (t: Throwable) {\n                var errorMsg = t\n                if (client.isErrorType(t, \"not-set-up\")) {\n                    Prefs.isReadingListSyncEnabled = false\n                    if (lastSyncTime.isEmpty()) {\n                        // This means that it's our first time attempting to sync, and we see that\n                        // syncing isn't enabled on the server. So, let's prompt the user to enable it:\n                        FlowEventBus.post(ReadingListsEnableDialogEvent())\n                    } else {\n                        // This can only mean that our reading lists have been torn down (disabled) by\n                        // another client, so we need to notify the user of this development.\n                        FlowEventBus.post(ReadingListsNoLongerSyncedEvent())\n                    }\n                }\n                if (client.isErrorType(t, \"notloggedin\")) {\n                    try {\n                        L.d(\"Server doesn't believe we're logged in, so logging in...\")\n                        CsrfTokenClient.getToken(wiki)\n                        shouldRetry = true\n                    } catch (caught: Throwable) {\n                        errorMsg = caught\n                    }\n                }\n                L.w(errorMsg)\n            } finally {\n                Prefs.readingListsLastSyncTime = client.lastDateHeader?.toString() ?: lastSyncTime\n                Prefs.readingListsDeletedIds = listIdsDeleted\n                Prefs.readingListPagesDeletedIds = pageIdsDeleted\n                readingListSyncNotification.cancelNotification(applicationContext)\n                if (shouldSendSyncEvent) {\n                    SavedPageSyncService.sendSyncEvent(extras.containsKey(SYNC_EXTRAS_REFRESHING))\n                }\n                if ((shouldRetry || shouldRetryWithForce) && !extras.containsKey(SYNC_EXTRAS_RETRYING)) {\n                    val b = Bundle()\n                    b.putAll(extras)\n                    b.putBoolean(SYNC_EXTRAS_RETRYING, true)\n                    if (shouldRetryWithForce) {\n                        b.putBoolean(SYNC_EXTRAS_FORCE_FULL_SYNC, true)\n                    }\n                    manualSync(b)\n                }\n                IN_PROGRESS = false\n                SavedPageSyncService.enqueue()\n                L.d(\"Finished sync of reading lists.\")\n            }\n            Result.success()\n        }\n    }\n\n    private fun getBooleanExtraFromData(inputData: Data): Bundle {\n        val extras = Bundle()\n        inputData.keyValueMap.forEach {\n            extras.putBoolean(it.key, it.value as Boolean)\n        }\n        return extras\n    }\n\n    private suspend fun createOrUpdatePage(listForPage: ReadingList,\n                                   remotePage: RemoteReadingListEntry) {\n        val remoteTitle = pageTitleFromRemoteEntry(remotePage)\n        var localPage = listForPage.pages.find { ReadingListPage.toPageTitle(it) == remoteTitle }\n        var updateOnly = localPage != null\n\n        if (localPage == null) {\n            localPage = ReadingListPage(pageTitleFromRemoteEntry(remotePage))\n            localPage.listId = listForPage.id\n            updateOnly = AppDatabase.instance.readingListPageDao().getPageByTitle(listForPage, remoteTitle) != null\n        }\n        localPage.remoteId = remotePage.id\n        localPage.atime = remotePage.created.toInstant(ZoneOffset.UTC).toEpochMilli()\n        localPage.mtime = remotePage.updated.toInstant(ZoneOffset.UTC).toEpochMilli()\n        if (updateOnly) {\n            L.d(\"Updating local page \" + localPage.apiTitle)\n            AppDatabase.instance.readingListPageDao().updateReadingListPage(localPage)\n        } else {\n            L.d(\"Creating local page \" + localPage.apiTitle)\n            AppDatabase.instance.readingListPageDao().addPagesToList(listForPage, listOf(localPage), false)\n        }\n    }\n\n    private suspend fun deletePageByTitle(listForPage: ReadingList, title: PageTitle) {\n        var localPage = listForPage.pages.find { ReadingListPage.toPageTitle(it) == title }\n        if (localPage == null) {\n            localPage = AppDatabase.instance.readingListPageDao().getPageByTitle(listForPage, title)\n            if (localPage == null) {\n                return\n            }\n        }\n        L.d(\"Deleting local page \" + localPage.apiTitle)\n        AppDatabase.instance.readingListPageDao().markPagesForDeletion(listForPage, listOf(localPage), false)\n    }\n\n    private fun pageTitleFromRemoteEntry(remoteEntry: RemoteReadingListEntry): PageTitle {\n        return PageTitle(remoteEntry.title(), WikiSite(remoteEntry.project()))\n    }\n\n    private fun remoteEntryFromLocalPage(localPage: ReadingListPage): RemoteReadingListEntry {\n        val title = ReadingListPage.toPageTitle(localPage)\n        return RemoteReadingListEntry(0, 0,\n            \"${title.wikiSite.scheme()}://${title.wikiSite.authority()}\", title.prefixedText,\n            created = if (localPage.atime == 0L) LocalDateTime.now() else LocalDateTime.ofInstant(Instant.ofEpochMilli(localPage.atime), ZoneOffset.UTC),\n            updated = if (localPage.mtime == 0L) LocalDateTime.now() else LocalDateTime.ofInstant(Instant.ofEpochMilli(localPage.mtime), ZoneOffset.UTC))\n    }\n\n    companion object {\n        private const val WORK_NAME = \"readingListSyncAdapter\"\n        private const val SYNC_EXTRAS_FORCE_FULL_SYNC = \"forceFullSync\"\n        private const val SYNC_EXTRAS_REFRESHING = \"refreshing\"\n        private const val SYNC_EXTRAS_RETRYING = \"retrying\"\n        private var IN_PROGRESS = false\n\n        fun inProgress(): Boolean {\n            return IN_PROGRESS\n        }\n\n        fun setSyncEnabledWithSetup() {\n            Prefs.isReadingListSyncEnabled = true\n            Prefs.isReadingListsRemoteSetupPending = true\n            Prefs.isReadingListsRemoteDeletePending = false\n            manualSync()\n        }\n\n        fun manualSyncWithDeleteList(list: ReadingList) {\n            if (list.remoteId <= 0) {\n                return\n            }\n            Prefs.addReadingListsDeletedIds(setOf(list.remoteId))\n            manualSync()\n        }\n\n        fun createIdsForDeletion(list: ReadingList, pages: Set<ReadingListPage>): Set<String> {\n            return if (list.remoteId <= 0) emptySet() else pages.map { it.remoteId }.filter { it > 0 }.map { \"${list.remoteId}:$it\" }.toSet()\n        }\n\n        fun manualSyncWithDeletePages(list: ReadingList, pages: List<ReadingListPage>) {\n            val ids = createIdsForDeletion(list, pages.toSet())\n            if (ids.isNotEmpty()) {\n                Prefs.addReadingListPagesDeletedIds(ids)\n                manualSync()\n            }\n        }\n\n        fun manualSyncWithDeletePages(lists: List<ReadingList>) {\n            val ids = lists.flatMapTo(mutableSetOf()) { list ->\n                createIdsForDeletion(list, list.pages.toSet())\n            }\n\n            if (ids.isNotEmpty()) {\n                Prefs.addReadingListPagesDeletedIds(ids)\n                manualSync()\n            }\n        }\n\n        fun manualSyncWithForce(fromRefresh: Boolean = false) {\n            val extras = bundleOf(SYNC_EXTRAS_FORCE_FULL_SYNC to true)\n            // Pull-to-refresh needs the REFRESHING flag so a ReadingListSyncEvent is emitted on\n            // completion to dismiss the refresh spinner.\n            if (fromRefresh) {\n                extras.putBoolean(SYNC_EXTRAS_REFRESHING, true)\n            }\n            manualSync(extras)\n        }\n\n        fun manualSyncWithRefresh() {\n            Prefs.isSuggestedEditsHighestPriorityEnabled = false\n            manualSync(bundleOf(SYNC_EXTRAS_REFRESHING to true))\n        }\n\n        fun manualSync(extras: Bundle = Bundle()) {\n            if (inProgress()) {\n                return\n            }\n            if (AccountUtil.account() == null || !WikipediaApp.instance.isOnline) {\n                if (extras.containsKey(SYNC_EXTRAS_REFRESHING)) {\n                    SavedPageSyncService.sendSyncEvent()\n                }\n                return\n            }\n            extras.putBoolean(ContentResolver.SYNC_EXTRAS_MANUAL, true)\n            extras.putBoolean(ContentResolver.SYNC_EXTRAS_EXPEDITED, true)\n\n            // Convert the Bundle to a Data object\n            val dataBuilder = Data.Builder()\n            extras.keySet().forEach {\n                dataBuilder.putBoolean(it, extras.getBoolean(it))\n            }\n\n            val constraints = Constraints.Builder()\n                .setRequiredNetworkType(NetworkType.CONNECTED)\n                .build()\n            val workRequest = OneTimeWorkRequestBuilder<ReadingListSyncAdapter>()\n                .setConstraints(constraints)\n                .setInputData(dataBuilder.build())\n                .build()\n            WorkManager.getInstance(WikipediaApp.instance)\n                .enqueueUniqueWork(WORK_NAME, ExistingWorkPolicy.REPLACE, workRequest)\n        }\n    }\n}","file":"app/src/main/java/org/wikipedia/readinglist/sync/ReadingListSyncAdapter.kt","kind":"class","line":41,"members":{"IN_PROGRESS":[508,508],"SYNC_EXTRAS_FORCE_FULL_SYNC":[505,505],"SYNC_EXTRAS_REFRESHING":[506,506],"SYNC_EXTRAS_RETRYING":[507,507],"WORK_NAME":[504,504],"context":[41,41],"createIdsForDeletion":[529,531],"createOrUpdatePage":[456,477],"deletePageByTitle":[479,489],"doWork":[43,446],"getBooleanExtraFromData":[448,454],"inProgress":[510,512],"manualSync":[567,595],"manualSyncWithDeleteList":[521,527],"manualSyncWithDeletePages":[533,539],"manualSyncWithForce":[552,560],"manualSyncWithRefresh":[562,565],"pageTitleFromRemoteEntry":[491,493],"params":[41,41],"remoteEntryFromLocalPage":[495,501],"setSyncEnabledWithSetup":[514,519]},"supers":["CoroutineWorker(context, params)"]},"ReadingListsContent":{"appearsIn":[["saved","h-widgets","Screen \u00b7 composition"]],"code":"@Composable\nprivate fun ReadingListsContent(\n    uiState: ReadingListsUiState,\n    isSelectionMode: Boolean,\n    selectedListIds: Set<Long>,\n    selectedPageIds: Set<Long>,\n    onOnboardingAction: (OnboardingAction) -> Unit,\n    onListClick: (Long) -> Unit,\n    onListMenuAction: (Long, ReadingListMenuAction) -> Unit,\n    onListSelectionChange: (Long) -> Unit,\n    onPageSelectionChange: (Long) -> Unit,\n    onPageClick: (Long) -> Unit,\n    onPageLongClick: (Long) -> Unit,\n    onPageChipClick: (Long) -> Unit,\n    onPageToggleOfflineClick: (Long) -> Unit,\n    onDiscoverCardClick: () -> Unit,\n    onCreateCollectionClick: () -> Unit,\n    modifier: Modifier = Modifier\n) {\n    when {\n        uiState.isLoading -> {\n            Box(\n                modifier = modifier.fillMaxSize(),\n                contentAlignment = Alignment.Center\n            ) {\n                CircularProgressIndicator(\n                    color = WikipediaTheme.colors.progressiveColor\n                )\n            }\n        }\n\n        // empty state\n        uiState.rows.isEmpty() && uiState.searchQuery.isNullOrEmpty() &&\n            uiState.onboarding == OnboardingState.None && uiState.discoverCard == null -> {\n            val isAllArticlesTab = uiState.selectedTab == SavedTab.ALL_ARTICLES\n            val allSavedArticlesAreInCollections = isAllArticlesTab &&\n                uiState.selectedArticleFilter == SavedArticleFilter.NOT_IN_COLLECTION && uiState.hasSavedArticles\n            EmptyReadingListsContent(\n                title = stringResource(\n                    when {\n                        allSavedArticlesAreInCollections -> R.string.reading_lists_empty_not_in_collection_title\n                        isAllArticlesTab -> R.string.saved_list_empty_title\n                        else -> R.string.reading_lists_empty_collections_title\n                    }\n                ),\n                description = when {\n                    allSavedArticlesAreInCollections -> null\n                    isAllArticlesTab -> stringResource(R.string.reading_lists_empty_message)\n                    else -> stringResource(R.string.reading_lists_empty_collections_description)\n                },\n                buttonText = if (isAllArticlesTab) {\n                    null\n                } else {\n                    stringResource(R.string.reading_lists_create_new_collection)\n                },\n                onButtonClick = onCreateCollectionClick,\n                modifier = modifier\n            )\n        }\n\n        // searching but no results\n        uiState.rows.isEmpty() && !uiState.searchQuery.isNullOrEmpty() -> {\n            val isAllArticlesTab = uiState.selectedTab == SavedTab.ALL_ARTICLES\n            EmptyReadingListsContent(\n                title = stringResource(\n                    if (isAllArticlesTab) R.string.reading_lists_search_empty_articles_title\n                    else R.string.reading_lists_search_empty_collections_title\n                ),\n                description = stringResource(\n                    if (isAllArticlesTab) R.string.reading_lists_search_empty_articles_message\n                    else R.string.reading_lists_search_empty_collections_message,\n                    uiState.searchQuery\n                ),\n                modifier = modifier\n            )\n        }\n        else -> {\n            ReadingListsList(\n                rows = uiState.rows,\n                pageDownloadProgress = uiState.pageDownloadProgress,\n                sortMode = uiState.sortMode,\n                onboarding = uiState.onboarding,\n                discoverCard = uiState.discoverCard,\n                onOnboardingAction = onOnboardingAction,\n                isSelectionMode = isSelectionMode,\n                selectedListIds = selectedListIds,\n                selectedPageIds = selectedPageIds,\n                onListClick = onListClick,\n                onListMenuAction = onListMenuAction,\n                onListSelectionChange = onListSelectionChange,\n                onPageSelectionChange = onPageSelectionChange,\n                onPageClick = onPageClick,\n                onPageLongClick = onPageLongClick,\n                onPageChipClick = onPageChipClick,\n                onPageToggleOfflineClick = onPageToggleOfflineClick,\n                onDiscoverCardClick = onDiscoverCardClick,\n                modifier = modifier\n            )\n        }\n    }\n}","file":"app/src/main/java/org/wikipedia/readinglist/compose/ReadingListsScreen.kt","kind":"composable function","line":228,"members":{},"shot":"shots/code/ReadingListsContent.jpg","supers":[]},"ReadingListsFragment":{"appearsIn":[["index","h-screens","Screens \u00b7 how the user moves"],["saved","h-classes","Logic \u00b7 class diagram"],["saved","h-widgets","Screen \u00b7 composition"]],"code":"class ReadingListsFragment : Fragment(), SortReadingListsDialog.Callback, ReadingListItemActionsDialog.Callback {\n\n    private val viewModel: ReadingListsViewModel by viewModels()\n    private var actionMode: ActionMode? = null\n\n    private val filePickerLauncher = registerForActivityResult(ActivityResultContracts.StartActivityForResult()) { result ->\n        if (result.resultCode == AppCompatActivity.RESULT_OK) {\n            result.data?.data?.let(::importReadingLists)\n        }\n    }\n\n    override fun onCreate(savedInstanceState: Bundle?) {\n        super.onCreate(savedInstanceState)\n        RecommendedReadingListEvent.submit(\"impression\", \"rrl_saved\")\n    }\n\n    override fun onCreateView(\n        inflater: LayoutInflater,\n        container: ViewGroup?,\n        savedInstanceState: Bundle?\n    ): View {\n        return ComposeView(requireContext()).apply {\n            setContent {\n                BaseTheme {\n                    val uiState by viewModel.uiState.collectAsStateWithLifecycle()\n                    val isRefreshing by viewModel.isRefreshing.collectAsStateWithLifecycle()\n                    val selectionState by viewModel.selectionState.collectAsStateWithLifecycle()\n                    ReadingListsScreen(\n                        uiState = uiState,\n                        isRefreshing = isRefreshing,\n                        pullToRefreshEnabled = !RemoteConfig.config.disableReadingListSync,\n                        isSelectionMode = selectionState.enabled,\n                        selectedListIds = selectionState.selectedListIds,\n                        selectedPageIds = selectionState.selectedPageIds,\n                        showCollectionsBadge = uiState.showCollectionsBadge,\n                        onSelectTab = ::onSelectTab,\n                        onOnboardingAction = ::onOnboardingAction,\n                        onRefresh = ::onRefresh,\n                        onListClick = ::onListClick,\n                        onListMenuAction = ::onListMenuAction,\n                        onListSelectionChange = viewModel::toggleListSelection,\n                        onPageSelectionChange = viewModel::togglePageSelection,\n                        onPageClick = ::onPageClick,\n                        onPageLongClick = ::onPageLongClick,\n                        onPageChipClick = ::onPageChipClick,\n                        onPageToggleOfflineClick = ::onToggleOfflineClick,\n                        onDiscoverCardClick = ::onDiscoverCardClick,\n                        onCreateCollectionClick = overflowCallback::createNewListClick\n                    )\n                }\n            }\n        }\n    }\n\n    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {\n        super.onViewCreated(view, savedInstanceState)\n        viewLifecycleOwner.lifecycleScope.launch {\n            viewLifecycleOwner.repeatOnLifecycle(Lifecycle.State.CREATED) {\n                FlowEventBus.events.collectLatest { event ->\n                    when (event) {\n                        // The list itself updates reactively via the DB flow; this just stops the spinner.\n                        is ReadingListSyncEvent -> viewModel.setRefreshing(false)\n                        is LoggedInEvent,\n                        is LoggedOutEvent,\n                        is LoggedOutInBackgroundEvent -> viewModel.refreshAccountState()\n                        is PageDownloadEvent -> viewModel.updatePageDownloadProgress(event.page)\n                        is ArticleSavedOrDeletedEvent -> {\n                            if (event.isAdded && Prefs.readingListsPageSaveCount < SAVE_COUNT_LIMIT) {\n                                showReadingListsSyncDialog()\n                                Prefs.readingListsPageSaveCount += 1\n                            }\n                        }\n                    }\n                }\n            }\n        }\n\n        viewLifecycleOwner.lifecycleScope.launch {\n            viewLifecycleOwner.repeatOnLifecycle(Lifecycle.State.STARTED) {\n                combine(viewModel.uiState, viewModel.selectionState) { _, _ -> }.collect {\n                    actionMode?.invalidate()\n                }\n            }\n        }\n\n        viewLifecycleOwner.lifecycleScope.launch {\n            viewLifecycleOwner.repeatOnLifecycle(Lifecycle.State.RESUMED) {\n                launch {\n                    val initialState = viewModel.uiState.first { !it.isLoading }\n                    ReadingListsAnalyticsHelper.logListsShown(requireContext(), initialState.listCount)\n                    viewModel.uiState\n                        .map { it.listCount >= Constants.MAX_READING_LISTS_LIMIT }\n                        .distinctUntilChanged()\n                        .collect(::maybeShowListLimitMessage)\n                }\n                launch {\n                    viewModel.uiState\n                        .map { state ->\n                            state.pendingPreviewSavedListId?.takeIf { id ->\n                                state.rows.any {\n                                    it is ReadingListRow.ListRow && it.list.id == id\n                                }\n                            }\n                        }\n                        .distinctUntilChanged()\n                        .collect { listId ->\n                            listId?.let { maybeShowPreviewSavedReadingListsSnackbar(it) }\n                        }\n                }\n            }\n        }\n    }\n\n    private fun showReadingListsSyncDialog() {\n        if (Prefs.isReadingListSyncEnabled) {\n            return\n        }\n        if (AccountUtil.isLoggedIn) {\n            ReadingListSyncBehaviorDialogs.promptEnableSyncDialog(requireActivity())\n        }\n    }\n\n    private fun onRefresh() {\n        viewModel.setRefreshing(true)\n        if (!AccountUtil.isLoggedIn || AccountUtil.isTemporaryAccount) {\n            viewModel.setRefreshing(false)\n        } else {\n            Prefs.isReadingListSyncEnabled = true\n            // TODO: Change this back to the less forceful manualSyncWithRefresh() when the\n            // service-side endpoint is fixed.\n            // https://phabricator.wikimedia.org/T351149\n            ReadingListSyncAdapter.manualSyncWithForce(fromRefresh = true)\n        }\n    }\n\n    private fun maybeShowListLimitMessage(atLimit: Boolean) {\n        if (atLimit && actionMode == null) {\n            FeedbackUtil.makeSnackbar(\n                requireActivity(),\n                getString(R.string.reading_lists_limit_message)\n            ).show()\n        }\n    }\n\n    private suspend fun maybeShowPreviewSavedReadingListsSnackbar(listId: Long) {\n        val list = viewModel.loadReadingListWithPagesById(listId) ?: return\n        ReadingListsAnalyticsHelper.logReceiveFinish(requireContext(), list)\n        FeedbackUtil.makeSnackbar(requireActivity(), getString(R.string.reading_lists_preview_saved_snackbar))\n            .setAction(R.string.suggested_edits_article_cta_snackbar_action) {\n                viewModel.clearRecentPreviewSavedList()\n                startActivity(ReadingListActivity.newIntent(requireContext(), list))\n            }\n            .show()\n        viewModel.consumePreviewSavedSnackbar(listId)\n    }\n\n    private fun maybeDeleteListFromIntent() {\n        val intent = requireActivity().intent\n        val titleToDelete = intent.getStringExtra(Constants.INTENT_EXTRA_DELETE_READING_LIST) ?: return\n        intent.removeExtra(Constants.INTENT_EXTRA_DELETE_READING_LIST)\n        viewLifecycleOwner.lifecycleScope.launch {\n            val listId = viewModel.getReadingListsWithoutContents()\n                .firstOrNull { it.title == titleToDelete }?.id ?: return@launch\n            val list = viewModel.loadReadingListWithPagesById(listId) ?: return@launch\n            ReadingListBehaviorsUtil.deleteReadingList(requireActivity(), list, false) {\n                ReadingListBehaviorsUtil.showDeleteListUndoSnackbar(requireActivity(), list) {}\n            }\n        }\n    }\n\n    private fun onOnboardingAction(action: OnboardingAction) {\n        when (action) {\n            OnboardingAction.RecommendedShown -> {\n                RecommendedReadingListEvent.submit(\"impression\", \"rrl_saved_prompt\")\n            }\n            OnboardingAction.RecommendedAccept -> {\n                startActivity(RecommendedReadingListOnboardingActivity.newIntent(requireContext()))\n                RecommendedReadingListEvent.submit(\"enter_click\", \"rrl_saved_prompt\")\n            }\n            OnboardingAction.RecommendedDismiss -> {\n                Prefs.isRecommendedReadingListOnboardingShown = true\n                FeedbackUtil.showMessage(this, getString(R.string.recommended_reading_list_onboarding_card_negative_snackbar))\n                RecommendedReadingListEvent.submit(\"nothanks_click\", \"rrl_saved_prompt\")\n            }\n            OnboardingAction.SyncEnable -> {\n                ReadingListSyncAdapter.setSyncEnabledWithSetup()\n            }\n            OnboardingAction.SyncDismiss -> {\n                Prefs.isReadingListSyncReminderEnabled = false\n            }\n            OnboardingAction.LoginRequest -> {\n                if (isAdded && requireParentFragment() is MainFragment) {\n                    (requireParentFragment() as MainFragment).onLoginRequested()\n                }\n            }\n            OnboardingAction.LoginDismiss -> {\n                Prefs.isReadingListLoginReminderEnabled = false\n            }\n        }\n    }\n\n    override fun onResume() {\n        super.onResume()\n        viewModel.refreshAccountState()\n        viewModel.refreshRecentPreviewSavedList()\n        maybeDeleteListFromIntent()\n        requireActivity().invalidateOptionsMenu()\n    }\n\n    override fun onPause() {\n        super.onPause()\n        actionMode?.finish()\n    }\n\n    // Search action mode\n    fun startSearchActionMode() {\n        (requireActivity() as AppCompatActivity).startSupportActionMode(searchActionModeCallback)\n    }\n\n    private fun onSelectTab(tab: SavedTab) {\n        actionMode?.takeIf(::isTagType)?.finish()\n        viewModel.setSelectedTab(tab)\n        searchActionModeCallback.updateSearchHint(getSearchHint(tab))\n        requireActivity().invalidateOptionsMenu()\n    }\n\n    private fun getSearchHint(tab: SavedTab): String {\n        return getString(\n            when (tab) {\n                SavedTab.ALL_ARTICLES -> R.string.reading_lists_search_saved_articles\n                SavedTab.COLLECTIONS -> R.string.reading_lists_search_collections\n            }\n        )\n    }\n\n    private val searchActionModeCallback = object : SearchActionModeCallback() {\n        override fun onCreateActionMode(mode: ActionMode, menu: Menu): Boolean {\n            actionMode = mode\n            viewModel.setSearchActive(true)\n            if (isAdded) {\n                (requireParentFragment() as MainFragment).setBottomNavVisible(false)\n            }\n            return super.onCreateActionMode(mode, menu)\n        }\n\n        override fun onQueryChange(s: String) {\n            viewModel.setSearchQuery(s.trim())\n        }\n\n        override fun onDestroyActionMode(mode: ActionMode) {\n            super.onDestroyActionMode(mode)\n            actionMode = null\n            viewModel.setSearchActive(false)\n            viewModel.setSearchQuery(null)\n            if (isAdded) {\n                (requireParentFragment() as MainFragment).setBottomNavVisible(true)\n            }\n        }\n\n        override fun getSearchHintString(): String {\n            return getSearchHint(viewModel.uiState.value.selectedTab)\n        }\n\n        override fun getParentContext(): Context {\n            return requireContext()\n        }\n    }\n\n    fun isAllArticlesSelected(): Boolean {\n        return viewModel.isSelectedTab(SavedTab.ALL_ARTICLES)\n    }\n\n    fun showReadingListsFilterMenu() {\n        if (!isAllArticlesSelected()) {\n            return\n        }\n        ReadingListsAllArticlesFilterOverflowView(requireContext()).show(\n            anchorView = (requireActivity() as MainActivity).getToolbar()\n                .findViewById(R.id.menu_filter_reading_lists_articles),\n            selectedOption = viewModel.getSelectedArticleFilter(),\n            callback = viewModel::setArticleFilter\n        )\n    }\n\n    // Overflow menu\n    fun showReadingListsOverflowMenu() {\n        ReadingListsOverflowView(requireContext()).show(\n            anchorView = (requireActivity() as MainActivity).getToolbar()\n                .findViewById(R.id.menu_overflow_button),\n            callback = overflowCallback,\n            showCollectionActions = viewModel.uiState.value.selectedTab == SavedTab.COLLECTIONS\n        )\n    }\n\n    private val overflowCallback = object : ReadingListsOverflowView.Callback {\n        override fun sortByClick() {\n            ExclusiveBottomSheetPresenter.show(\n                childFragmentManager,\n                SortReadingListsDialog.newInstance(\n                    sortOption = viewModel.uiState.value.sortMode,\n                    sortArticles = viewModel.uiState.value.selectedTab == SavedTab.ALL_ARTICLES\n                )\n            )\n        }\n\n        override fun createNewListClick() {\n            viewLifecycleOwner.lifecycleScope.launch {\n                val existingTitles = viewModel.getReadingListsWithoutContents()\n                    .map { it.title }\n                ReadingListTitleDialog.readingListTitleDialog(\n                    activity = requireActivity(),\n                    title = getString(R.string.reading_list_name_sample),\n                    description = \"\",\n                    otherTitles = existingTitles,\n                    callback = object : ReadingListTitleDialog.Callback {\n                        override fun onSuccess(text: String, description: String) {\n                            viewLifecycleOwner.lifecycleScope.launch(\n                                CoroutineExceptionHandler { _, throwable -> L.w(throwable) }\n                            ) {\n                                viewModel.createReadingList(text, description)\n                            }\n                        }\n                    }\n                ).show()\n            }\n        }\n\n        override fun importNewList() {\n            val intent = Intent(Intent.ACTION_GET_CONTENT).apply { type = \"application/json\" }\n            val filePickerIntent = Intent.createChooser(intent, getString(R.string.reading_lists_import_file_picker_title))\n            filePickerLauncher.launch(filePickerIntent)\n        }\n\n        override fun selectListClick() {\n            beginMultiSelect()\n        }\n\n        override fun refreshClick() {\n            onRefresh()\n        }\n    }\n\n    override fun onSortOptionClick(position: Int) {\n        viewModel.setSortMode(position)\n    }\n\n    private fun importReadingLists(uri: android.net.Uri) {\n        val contentResolver = requireContext().contentResolver\n        viewLifecycleOwner.lifecycleScope.launch {\n            val input = withContext(Dispatchers.IO) {\n                contentResolver.openInputStream(uri)?.bufferedReader()?.use { it.readText() }\n            } ?: return@launch\n            ReadingListsExportImportHelper.importLists(requireActivity() as AppCompatActivity, input)\n        }\n    }\n\n    private fun onListClick(listId: Long) {\n        if (isTagType(actionMode)) {\n            viewModel.toggleListSelection(listId)\n            return\n        }\n        viewModel.clearRecentPreviewSavedList()\n        viewLifecycleOwner.lifecycleScope.launch {\n            val list = viewModel.loadReadingListWithPagesById(listId) ?: return@launch\n            RecommendedReadingListEvent.submit(\"open_list_click\", \"rrl_saved\")\n            startActivity(ReadingListActivity.newIntent(requireContext(), list))\n        }\n    }\n\n    // ListRow onLongClick actions\n    private fun onListMenuAction(listId: Long, action: ReadingListMenuAction) {\n        BreadCrumbLogEvent.logClick(\n            requireContext(),\n            resources.getResourceEntryName(action.breadcrumbId())\n        )\n        viewLifecycleOwner.lifecycleScope.launch {\n            val list = viewModel.loadReadingListWithPagesById(listId) ?: return@launch\n            // List refresh happens reactively via the DB flow, so these callbacks don't call updateLists.\n            when (action) {\n                ReadingListMenuAction.Rename -> {\n                    if (list.isDefault) return@launch\n                    ReadingListBehaviorsUtil.renameReadingList(requireActivity(), list) {\n                        ReadingListSyncAdapter.manualSync()\n                    }\n                }\n                ReadingListMenuAction.Delete -> {\n                    ReadingListBehaviorsUtil.deleteReadingList(requireActivity(), list, true) {\n                        ReadingListBehaviorsUtil.showDeleteListUndoSnackbar(requireActivity(), list) {}\n                    }\n                }\n                ReadingListMenuAction.SaveAllOffline -> {\n                    ReadingListBehaviorsUtil.savePagesForOffline(requireActivity(), list.pages) {}\n                }\n                ReadingListMenuAction.RemoveAllOffline -> {\n                    ReadingListBehaviorsUtil.removePagesFromOffline(requireActivity(), list.pages) {}\n                }\n                ReadingListMenuAction.Export -> {\n                    ReadingListsExportImportHelper.exportLists(requireActivity() as BaseActivity, listOf(list))\n                }\n                ReadingListMenuAction.Select -> {\n                    beginMultiSelect()\n                    viewModel.toggleListSelection(listId)\n                }\n                ReadingListMenuAction.Share -> {\n                    ReadingListsShareHelper.shareReadingList(requireActivity() as AppCompatActivity, list)\n                }\n            }\n        }\n    }\n\n    private fun ReadingListMenuAction.breadcrumbId(): Int {\n        return when (this) {\n            ReadingListMenuAction.Rename -> R.id.menu_reading_list_rename\n            ReadingListMenuAction.Delete -> R.id.menu_reading_list_delete\n            ReadingListMenuAction.SaveAllOffline -> R.id.menu_reading_list_save_all_offline\n            ReadingListMenuAction.RemoveAllOffline -> R.id.menu_reading_list_remove_all_offline\n            ReadingListMenuAction.Export -> R.id.menu_reading_list_export\n            ReadingListMenuAction.Select -> R.id.menu_reading_list_select\n            ReadingListMenuAction.Share -> R.id.menu_reading_list_share\n        }\n    }\n\n    private fun onPageClick(pageId: Long) {\n        if (isTagType(actionMode)) {\n            viewModel.togglePageSelection(pageId)\n            return\n        }\n        launchWithPage(pageId) { page ->\n            val entry = HistoryEntry(ReadingListPage.toPageTitle(page), HistoryEntry.SOURCE_READING_LIST)\n            ReadingListBehaviorsUtil.updateReadingListPage(page)\n            startActivity(PageActivity.newIntentForCurrentTab(requireContext(), entry, entry.title))\n        }\n    }\n\n    private fun onPageLongClick(pageId: Long) {\n        val containingLists = viewModel.containingLists(pageId)\n        if (containingLists.isEmpty()) {\n            return\n        }\n        ExclusiveBottomSheetPresenter.show(\n            childFragmentManager,\n            ReadingListItemActionsDialog.newInstance(\n                containingLists.first().title,\n                containingLists.size,\n                pageId,\n                actionMode != null,\n                containingLists.count { !it.isDefault }\n            )\n        )\n    }\n\n    private fun onToggleOfflineClick(pageId: Long) {\n        launchWithPage(pageId) { page ->\n            if (Prefs.isDownloadOnlyOverWiFiEnabled && !DeviceUtil.isOnWiFi &&\n                page.status == ReadingListPage.STATUS_QUEUE_FOR_SAVE) {\n                page.offline = false\n            }\n            if (page.saving) {\n                Toast.makeText(requireContext(), R.string.reading_list_article_save_in_progress, Toast.LENGTH_LONG).show()\n            } else {\n                ReadingListBehaviorsUtil.toggleOffline(requireActivity(), page) {\n                    viewModel.updatePageDownloadProgress(page)\n                }\n            }\n        }\n    }\n\n    private fun onDiscoverCardClick() {\n        startActivity(ReadingListActivity.newIntent(requireActivity(), ReadingListMode.RECOMMENDED))\n    }\n\n    private fun onPageChipClick(listId: Long) {\n        viewLifecycleOwner.lifecycleScope.launch {\n            val list = viewModel.loadReadingListWithPagesById(listId) ?: return@launch\n            startActivity(ReadingListActivity.newIntent(requireContext(), list))\n        }\n    }\n\n    // PageRow OnLongClick ReadingListItemActionsDialog Callbacks\n    override fun onToggleItemOffline(pageId: Long) {\n        launchWithPage(pageId) { page ->\n            ReadingListBehaviorsUtil.togglePageOffline(requireActivity(), page) {\n                viewModel.updatePageDownloadProgress(page)\n            }\n        }\n    }\n\n    override fun onShareItem(pageId: Long) {\n        launchWithPage(pageId) { page ->\n            ShareUtil.shareText(requireActivity(), ReadingListPage.toPageTitle(page))\n        }\n    }\n\n    override fun onManageCollections(pageId: Long) {\n        launchWithPage(pageId) { page ->\n            SaveArticleSheetDialog.show(childFragmentManager, ReadingListPage.toPageTitle(page))\n        }\n    }\n\n    override fun onSelectItem(pageId: Long) {\n        beginMultiSelect()\n        viewModel.togglePageSelection(pageId)\n    }\n\n    override fun onDeleteItem(pageId: Long) {\n        viewLifecycleOwner.lifecycleScope.launch {\n            val deletion = viewModel.prepareSelectedPagesForDeletion(setOf(pageId)) ?: return@launch\n            ReadingListBehaviorsUtil.deletePagesFromLists(\n                requireActivity(),\n                deletion.selectedPageCount,\n                deletion.readingLists,\n                {}\n            ) {}\n        }\n    }\n\n    private fun launchWithPage(pageId: Long, action: suspend (ReadingListPage) -> Unit) {\n        viewLifecycleOwner.lifecycleScope.launch {\n            val page = viewModel.getPageById(pageId) ?: return@launch\n            action(page)\n        }\n    }\n\n    private fun beginMultiSelect() {\n        if (!isTagType(actionMode)) {\n            viewModel.setSelectionMode(true)\n            val callback = when (viewModel.uiState.value.selectedTab) {\n                SavedTab.ALL_ARTICLES -> articleSelectionCallback\n                SavedTab.COLLECTIONS -> collectionSelectionCallback\n            }\n            actionMode = (requireActivity() as AppCompatActivity)\n                .startSupportActionMode(callback)\n        }\n    }\n\n    private val collectionSelectionCallback = object : MultiSelectActionModeCallback() {\n        override fun onCreateActionMode(mode: ActionMode, menu: Menu): Boolean {\n            super.onCreateActionMode(mode, menu)\n            mode.menuInflater.inflate(R.menu.menu_action_mode_reading_lists, menu)\n            actionMode = mode\n            val deleteItem = menu.findItem(R.id.menu_delete_selected)\n            deleteItem.isEnabled = false\n            return true\n        }\n\n        override fun onPrepareActionMode(mode: ActionMode, menu: Menu): Boolean {\n            val selectedIds = viewModel.selectionState.value.selectedListIds\n            val listRows = viewModel.uiState.value.rows.filterIsInstance<ReadingListRow.ListRow>()\n            val selectedLists = listRows.filter { it.list.id in selectedIds }\n            val allListIds = listRows.map { it.list.id }\n            val allSelected = allListIds.isNotEmpty() && selectedIds.containsAll(allListIds)\n            val onlyDefaultSelected = selectedLists.size == 1 && selectedLists.single().list.isDefault\n\n            mode.title = if (selectedLists.isEmpty()) \"\" else {\n                getString(R.string.multi_select_items_selected, selectedLists.size)\n            }\n            val fullOpacity = 255\n            val halfOpacity = 80\n            menu.findItem(R.id.menu_delete_selected).apply {\n                isEnabled = selectedLists.isNotEmpty() && !onlyDefaultSelected\n                icon?.alpha = if (selectedLists.isEmpty() || onlyDefaultSelected) halfOpacity else fullOpacity\n            }\n            menu.findItem(R.id.menu_export_selected).apply {\n                isEnabled = selectedLists.isNotEmpty()\n                val exportColor = ResourceUtil.getThemedColor(requireContext(), R.attr.progressive_color)\n                title = buildSpannedString {\n                    color(ColorUtils.setAlphaComponent(exportColor, if (selectedLists.isEmpty()) halfOpacity else fullOpacity)) {\n                        append(getString(R.string.reading_lists_action_menu_export_lists))\n                    }\n                }\n            }\n            menu.findItem(R.id.menu_select).apply {\n                setIcon(when {\n                    selectedLists.isEmpty() -> R.drawable.ic_outline_library_add_check_24\n                    allSelected -> R.drawable.ic_deselect_all\n                    else -> R.drawable.ic_select_indeterminate\n                })\n                title = when {\n                    selectedLists.isEmpty() -> getString(R.string.notifications_menu_check_all)\n                    allSelected -> getString(R.string.notifications_menu_uncheck_all)\n                    else -> \"\"\n                }\n            }\n            return true\n        }\n\n        override fun onActionItemClicked(mode: ActionMode, menuItem: MenuItem): Boolean {\n            return when (menuItem.itemId) {\n                R.id.menu_delete_selected -> {\n                    onDeleteSelected()\n                    true\n                }\n                R.id.menu_export_selected -> {\n                    exportSelectedLists()\n                    true\n                }\n                R.id.menu_select -> {\n                    val allListIds = viewModel.uiState.value.rows\n                        .filterIsInstance<ReadingListRow.ListRow>()\n                        .map { it.list.id }\n                    val selectedIds = viewModel.selectionState.value.selectedListIds\n                    if (allListIds.isNotEmpty() && selectedIds.containsAll(allListIds)) {\n                        viewModel.clearListSelection()\n                    } else {\n                        viewModel.selectAllLists()\n                    }\n                    true\n                }\n                else -> super.onActionItemClicked(mode, menuItem)\n            }\n        }\n\n        override fun onDeleteSelected() {\n            deleteSelectedLists()\n        }\n\n        override fun onDestroyActionMode(mode: ActionMode) {\n            viewModel.setSelectionMode(false)\n            actionMode = null\n            super.onDestroyActionMode(mode)\n        }\n    }\n\n    private val articleSelectionCallback = object : MultiSelectActionModeCallback() {\n        override fun onCreateActionMode(mode: ActionMode, menu: Menu): Boolean {\n            super.onCreateActionMode(mode, menu)\n            mode.menuInflater.inflate(R.menu.menu_action_mode_reading_list_articles, menu)\n            actionMode = mode\n            return true\n        }\n\n        override fun onPrepareActionMode(mode: ActionMode, menu: Menu): Boolean {\n            val selectedIds = viewModel.selectionState.value.selectedPageIds\n            val allPageIds = viewModel.uiState.value.rows\n                .filterIsInstance<ReadingListRow.PageRow>()\n                .map { it.page.id }\n            val allSelected = allPageIds.isNotEmpty() && selectedIds.containsAll(allPageIds)\n\n            mode.title = if (selectedIds.isEmpty()) \"\" else {\n                getString(R.string.multi_select_items_selected, selectedIds.size)\n            }\n            menu.findItem(R.id.menu_delete_selected).apply {\n                isEnabled = selectedIds.isNotEmpty()\n                icon?.alpha = if (selectedIds.isEmpty()) 80 else 255\n            }\n            menu.findItem(R.id.menu_select).apply {\n                setIcon(when {\n                    selectedIds.isEmpty() -> R.drawable.ic_outline_library_add_check_24\n                    allSelected -> R.drawable.ic_deselect_all\n                    else -> R.drawable.ic_select_indeterminate\n                })\n                title = when {\n                    selectedIds.isEmpty() -> getString(R.string.notifications_menu_check_all)\n                    allSelected -> getString(R.string.notifications_menu_uncheck_all)\n                    else -> \"\"\n                }\n            }\n            return true\n        }\n\n        override fun onActionItemClicked(mode: ActionMode, menuItem: MenuItem): Boolean {\n            return when (menuItem.itemId) {\n                R.id.menu_delete_selected -> {\n                    onDeleteSelected()\n                    true\n                }\n                R.id.menu_remove_from_offline -> {\n                    updateSelectedPagesOffline(saveForOffline = false)\n                    true\n                }\n                R.id.menu_save_for_offline -> {\n                    updateSelectedPagesOffline(saveForOffline = true)\n                    true\n                }\n                R.id.menu_add_to_another_list -> {\n                    addSelectedPagesToList()\n                    true\n                }\n                R.id.menu_select -> {\n                    val allPageIds = viewModel.uiState.value.rows\n                        .filterIsInstance<ReadingListRow.PageRow>()\n                        .map { it.page.id }\n                    val selectedIds = viewModel.selectionState.value.selectedPageIds\n                    if (allPageIds.isNotEmpty() && selectedIds.containsAll(allPageIds)) {\n                        viewModel.clearPageSelection()\n                    } else {\n                        viewModel.selectAllPages()\n                    }\n                    true\n                }\n                else -> super.onActionItemClicked(mode, menuItem)\n            }\n        }\n\n        override fun onDeleteSelected() {\n            deleteSelectedPages()\n        }\n\n        override fun onDestroyActionMode(mode: ActionMode) {\n            viewModel.setSelectionMode(false)\n            actionMode = null\n            super.onDestroyActionMode(mode)\n        }\n    }\n\n    private fun updateSelectedPagesOffline(saveForOffline: Boolean) {\n        val selectedPageIds = viewModel.selectionState.value.selectedPageIds\n        viewLifecycleOwner.lifecycleScope.launch {\n            val pages = viewModel.getPagesByIds(selectedPageIds)\n            if (pages.isEmpty()) {\n                return@launch\n            }\n            if (saveForOffline) {\n                ReadingListBehaviorsUtil.savePagesForOffline(requireActivity(), pages) {\n                    actionMode?.finish()\n                }\n            } else {\n                ReadingListBehaviorsUtil.removePagesFromOffline(requireActivity(), pages) {\n                    actionMode?.finish()\n                }\n            }\n        }\n    }\n\n    private fun addSelectedPagesToList() {\n        val selectedPageIds = viewModel.selectionState.value.selectedPageIds\n        viewLifecycleOwner.lifecycleScope.launch {\n            val titles = viewModel.getPagesByIds(selectedPageIds)\n                .distinctBy { it.lang to it.apiTitle }\n                .map { ReadingListPage.toPageTitle(it) }\n            if (titles.isEmpty()) {\n                return@launch\n            }\n            val dialog = AddToReadingListDialog.newInstance(titles, InvokeSource.READING_LIST_ACTIVITY).apply {\n                dismissListener = DialogInterface.OnDismissListener { actionMode?.finish() }\n            }\n            ExclusiveBottomSheetPresenter.show(childFragmentManager, dialog)\n        }\n    }\n\n    private fun deleteSelectedPages() {\n        viewLifecycleOwner.lifecycleScope.launch {\n            val deletion = viewModel.prepareSelectedPagesForDeletion() ?: return@launch\n            ReadingListBehaviorsUtil.deletePagesFromLists(\n                requireActivity(),\n                deletion.selectedPageCount,\n                deletion.readingLists,\n                {}\n            ) {\n                actionMode?.finish()\n            }\n        }\n    }\n\n    private fun deleteSelectedLists() {\n        val selectedIds = viewModel.selectionState.value.selectedListIds\n        viewLifecycleOwner.lifecycleScope.launch {\n            val lists = viewModel.loadReadingListsWithPagesByIds(selectedIds)\n            if (lists.isEmpty()) {\n                return@launch\n            }\n            ReadingListBehaviorsUtil.deleteReadingLists(requireActivity(), lists) {\n                ReadingListBehaviorsUtil.showDeleteListsUndoSnackbar(requireActivity(), lists) {}\n                actionMode?.finish()\n            }\n        }\n    }\n\n    private fun exportSelectedLists() {\n        val selectedIds = viewModel.selectionState.value.selectedListIds\n        viewLifecycleOwner.lifecycleScope.launch {\n            val lists = viewModel.loadReadingListsWithPagesByIds(selectedIds)\n            if (lists.isNotEmpty()) {\n                ReadingListsExportImportHelper.exportLists(requireActivity() as BaseActivity, lists)\n                actionMode?.finish()\n            }\n        }\n    }\n\n    companion object {\n        private const val SAVE_COUNT_LIMIT = 3\n\n        fun newInstance(): ReadingListsFragment {\n            return ReadingListsFragment()\n        }\n    }\n}","file":"app/src/main/java/org/wikipedia/readinglist/ReadingListsFragment.kt","kind":"class","line":76,"members":{"SAVE_COUNT_LIMIT":[856,856],"actionMode":[79,79],"addSelectedPagesToList":[800,814],"articleSelectionCallback":[699,779],"beginMultiSelect":[599,609],"breadcrumbId":[486,496],"collectionSelectionCallback":[611,697],"deleteSelectedLists":[830,842],"deleteSelectedPages":[816,828],"exportSelectedLists":[844,853],"filePickerLauncher":[81,85],"getSearchHint":[302,309],"importReadingLists":[422,430],"isAllArticlesSelected":[344,346],"launchWithPage":[592,597],"maybeDeleteListFromIntent":[232,244],"maybeShowListLimitMessage":[211,218],"maybeShowPreviewSavedReadingListsSnackbar":[220,230],"newInstance":[858,860],"onCreate":[87,90],"onCreateView":[92,128],"onDeleteItem":[580,590],"onDiscoverCardClick":[543,545],"onListClick":[432,443],"onListMenuAction":[445,484],"onManageCollections":[569,573],"onOnboardingAction":[246,275],"onPageChipClick":[547,552],"onPageClick":[498,508],"onPageLongClick":[510,525],"onPause":[285,288],"onRefresh":[198,209],"onResume":[277,283],"onSelectItem":[575,578],"onSelectTab":[295,300],"onShareItem":[563,567],"onSortOptionClick":[418,420],"onToggleItemOffline":[554,561],"onToggleOfflineClick":[527,541],"onViewCreated":[130,187],"overflowCallback":[370,416],"searchActionModeCallback":[311,342],"showReadingListsFilterMenu":[348,358],"showReadingListsOverflowMenu":[360,368],"showReadingListsSyncDialog":[189,196],"startSearchActionMode":[290,293],"updateSelectedPagesOffline":[781,798],"viewModel":[78,78]},"shot":"shots/code/ReadingListsFragment.jpg","supers":["Fragment()","SortReadingListsDialog.Callback","ReadingListItemActionsDialog.Callback"]},"ReadingListsList":{"appearsIn":[["saved","h-widgets","Screen \u00b7 composition"]],"code":"@Composable\nprivate fun ReadingListsList(\n    rows: List<ReadingListRow>,\n    pageDownloadProgress: Map<Long, Int>,\n    sortMode: Int,\n    onboarding: OnboardingState,\n    discoverCard: RecommendedReadingListCard?,\n    onOnboardingAction: (OnboardingAction) -> Unit,\n    isSelectionMode: Boolean,\n    selectedListIds: Set<Long>,\n    selectedPageIds: Set<Long>,\n    onListClick: (Long) -> Unit,\n    onListMenuAction: (Long, ReadingListMenuAction) -> Unit,\n    onListSelectionChange: (Long) -> Unit,\n    onPageSelectionChange: (Long) -> Unit,\n    onPageClick: (Long) -> Unit,\n    onPageLongClick: (Long) -> Unit,\n    onPageChipClick: (Long) -> Unit,\n    onPageToggleOfflineClick: (Long) -> Unit,\n    onDiscoverCardClick: () -> Unit,\n    modifier: Modifier = Modifier\n) {\n    val listState = rememberLazyListState()\n\n    LaunchedEffect(onboarding, discoverCard) {\n        if (onboarding != OnboardingState.None || discoverCard != null) {\n            listState.animateScrollToItem(0)\n        }\n    }\n\n    LazyColumn(\n        modifier = modifier.fillMaxSize(),\n        state = listState\n    ) {\n        if (onboarding != OnboardingState.None) {\n            item(key = onboarding.toString()) {\n                OnboardingCard(\n                    state = onboarding,\n                    onAction = onOnboardingAction\n                )\n            }\n        }\n        if (discoverCard != null) {\n            item(key = \"discover\") {\n                DiscoverCard(\n                    card = discoverCard,\n                    onClick = onDiscoverCardClick\n                )\n            }\n        }\n        itemsIndexed(\n            items = rows,\n            key = { _, row ->\n                when (row) {\n                    is ReadingListRow.ListRow -> \"list-$sortMode-${row.list.id}\"\n                    is ReadingListRow.PageRow -> \"page-$sortMode-${row.page.id}\"\n                }\n            }\n        ) { index, row ->\n            when (row) {\n                is ReadingListRow.ListRow -> ReadingListRow(\n                    list = row.list,\n                    isSelectionMode = isSelectionMode,\n                    isSelected = row.list.id in selectedListIds,\n                    onSelectionChange = { onListSelectionChange(row.list.id) },\n                    onClick = { onListClick(row.list.id) },\n                    onMenuAction = { action -> onListMenuAction(row.list.id, action) }\n                )\n                is ReadingListRow.PageRow -> ReadingListPageRow(\n                    page = row.page,\n                    isSelectionMode = isSelectionMode,\n                    isSelected = row.page.id in selectedPageIds,\n                    downloadProgress = pageDownloadProgress[row.page.id] ?: 0,\n                    containingLists = row.containingLists,\n                    onSelectionChange = { onPageSelectionChange(row.page.id) },\n                    onClick = { onPageClick(row.page.id) },\n                    onLongClick = { onPageLongClick(row.page.id) },\n                    onToggleOfflineClick = { onPageToggleOfflineClick(row.page.id) },\n                    onChipClick = { listId -> onPageChipClick(listId) }\n                )\n            }\n            if (index < rows.lastIndex) {\n                HorizontalDivider(\n                    color = WikipediaTheme.colors.borderColor,\n                    thickness = 0.5.dp\n                )\n            }\n        }\n    }\n}","file":"app/src/main/java/org/wikipedia/readinglist/compose/ReadingListsScreen.kt","kind":"composable function","line":431,"members":{},"shot":"shots/code/ReadingListsList.jpg","supers":[]},"ReadingListsScreen":{"appearsIn":[["saved","h-widgets","Screen \u00b7 composition"]],"code":"@Composable\nfun ReadingListsScreen(\n    uiState: ReadingListsUiState,\n    modifier: Modifier = Modifier,\n    isRefreshing: Boolean = false,\n    pullToRefreshEnabled: Boolean = true,\n    isSelectionMode: Boolean = false,\n    selectedListIds: Set<Long> = emptySet(),\n    selectedPageIds: Set<Long> = emptySet(),\n    showCollectionsBadge: Boolean = false,\n    onSelectTab: (SavedTab) -> Unit = {},\n    onOnboardingAction: (OnboardingAction) -> Unit = {},\n    onRefresh: () -> Unit = {},\n    onListClick: (Long) -> Unit = {},\n    onListMenuAction: (Long, ReadingListMenuAction) -> Unit = { _, _ -> },\n    onListSelectionChange: (Long) -> Unit = {},\n    onPageSelectionChange: (Long) -> Unit = {},\n    onPageClick: (Long) -> Unit = {},\n    onPageLongClick: (Long) -> Unit = {},\n    onPageChipClick: (Long) -> Unit = {},\n    onPageToggleOfflineClick: (Long) -> Unit = {},\n    onDiscoverCardClick: () -> Unit = {},\n    onCreateCollectionClick: () -> Unit = {}\n) {\n    LaunchedEffect(uiState.onboarding) {\n        if (uiState.onboarding == OnboardingState.RecommendedReadingList) {\n            onOnboardingAction(OnboardingAction.RecommendedShown)\n        }\n    }\n\n    Column(modifier = modifier.fillMaxSize()) {\n        if (!uiState.isSearchActive && !isSelectionMode) {\n            SavedTabBar(\n                selectedTab = uiState.selectedTab,\n                showCollectionsBadge = showCollectionsBadge,\n                onSelectTab = onSelectTab\n            )\n        }\n\n        if (pullToRefreshEnabled) {\n            val pullToRefreshState = rememberPullToRefreshState()\n            PullToRefreshBox(\n                modifier = Modifier.fillMaxSize(),\n                state = pullToRefreshState,\n                isRefreshing = isRefreshing,\n                onRefresh = onRefresh,\n                indicator = {\n                    Indicator(\n                        modifier = Modifier.align(Alignment.TopCenter),\n                        isRefreshing = isRefreshing,\n                        containerColor = WikipediaTheme.colors.paperColor,\n                        color = WikipediaTheme.colors.progressiveColor,\n                        state = pullToRefreshState\n                    )\n                }\n            ) {\n                ReadingListsContent(\n                    uiState = uiState,\n                    isSelectionMode = isSelectionMode,\n                    selectedListIds = selectedListIds,\n                    selectedPageIds = selectedPageIds,\n                    onOnboardingAction = onOnboardingAction,\n                    onListClick = onListClick,\n                    onListMenuAction = onListMenuAction,\n                    onListSelectionChange = onListSelectionChange,\n                    onPageSelectionChange = onPageSelectionChange,\n                    onPageClick = onPageClick,\n                    onPageLongClick = onPageLongClick,\n                    onPageChipClick = onPageChipClick,\n                    onPageToggleOfflineClick = onPageToggleOfflineClick,\n                    onDiscoverCardClick = onDiscoverCardClick,\n                    onCreateCollectionClick = onCreateCollectionClick\n                )\n            }\n        } else {\n            ReadingListsContent(\n                uiState = uiState,\n                isSelectionMode = isSelectionMode,\n                selectedListIds = selectedListIds,\n                selectedPageIds = selectedPageIds,\n                onOnboardingAction = onOnboardingAction,\n                onListClick = onListClick,\n                onListMenuAction = onListMenuAction,\n                onListSelectionChange = onListSelectionChange,\n                onPageSelectionChange = onPageSelectionChange,\n                onPageClick = onPageClick,\n                onPageLongClick = onPageLongClick,\n                onPageChipClick = onPageChipClick,\n                onPageToggleOfflineClick = onPageToggleOfflineClick,\n                onDiscoverCardClick = onDiscoverCardClick,\n                onCreateCollectionClick = onCreateCollectionClick\n            )\n        }\n    }\n}","file":"app/src/main/java/org/wikipedia/readinglist/compose/ReadingListsScreen.kt","kind":"composable function","line":64,"members":{},"shot":"shots/code/ReadingListsScreen.jpg","supers":[]},"ReadingListsViewModel":{"appearsIn":[["saved","h-classes","Logic \u00b7 class diagram"]],"code":"@OptIn(FlowPreview::class)\nclass ReadingListsViewModel : ViewModel() {\n    private val searchQuery = MutableStateFlow<String?>(null)\n    private val debouncedSearchQuery = searchQuery\n        .debounce { query -> if (query.isNullOrEmpty()) 0L else SEARCH_DEBOUNCE_MILLIS }\n        .distinctUntilChanged()\n    private val searchActive = MutableStateFlow(false)\n    private val selectedTab = MutableStateFlow(SavedTab.ALL_ARTICLES)\n    private val selectedArticleFilter = MutableStateFlow(SavedArticleFilter.ALL_ARTICLES)\n\n    // Combine the debounced search query, selected tab, and article filter into a single state flow representing the current content mode.\n    // this reduces the number of flows needed in the main combine() call for uiState\n    private val contentMode = combine(debouncedSearchQuery, selectedTab, selectedArticleFilter) { query, tab, filter ->\n        ContentMode(query, tab, filter)\n    }.distinctUntilChanged()\n\n    private val recentPreviewSavedState = MutableStateFlow(RecentPreviewSavedState())\n\n    private val accountState = MutableStateFlow(readAccountState())\n    private val pageDownloadProgress = MutableStateFlow<Map<Long, Int>>(emptyMap())\n\n    private val _isRefreshing = MutableStateFlow(false)\n    val isRefreshing: StateFlow<Boolean> = _isRefreshing.asStateFlow()\n\n    private val _selectionState = MutableStateFlow(ReadingListsSelectionState())\n    val selectionState: StateFlow<ReadingListsSelectionState> = _selectionState.asStateFlow()\n\n    private val readingListsContentState = combine(\n        AppDatabase.instance.readingListDao().getListsWithPagesFlow(),\n        contentMode,\n        recentPreviewSavedState,\n        Prefs.observeKeys(\n            R.string.preference_key_reading_list_sort_mode,\n            R.string.preference_key_reading_list_page_sort_mode\n        )\n    ) { relations, mode, previewSavedState, _ ->\n        val sortMode = when (mode.tab) {\n            SavedTab.ALL_ARTICLES -> Prefs.getReadingListPageSortMode(ReadingList.SORT_BY_NAME_ASC)\n            SavedTab.COLLECTIONS -> Prefs.getReadingListSortMode(ReadingList.SORT_BY_NAME_ASC)\n        }\n        // toReadingList() drops pages queued for deletion (Room @Relation can't filter children in SQL)\n        val lists = relations.map { it.toReadingList() }.toMutableList()\n        val hasSavedArticles = lists.any { it.pages.isNotEmpty() }\n        ReadingListsUiState(\n            isLoading = false,\n            rows = buildRows(\n                lists,\n                mode.tab,\n                mode.query,\n                mode.articleFilter,\n                previewSavedState.newBadgeListId,\n                sortMode\n            ),\n            hasSavedArticles = hasSavedArticles,\n            listCount = relations.size,\n            searchQuery = mode.query,\n            selectedTab = mode.tab,\n            selectedArticleFilter = mode.articleFilter,\n            sortMode = sortMode,\n            showCollectionsBadge = previewSavedState.newBadgeListId != null,\n            pendingPreviewSavedListId = previewSavedState.pendingSnackbarListId\n        )\n    }\n\n    // SavedPageSyncService emits PageDownloadEvent which updates downloadProgress in ReadingListPage during a sync\n    // this only exposes the presentation state of the download progress for visible article rows,\n    // which avoids expensive row-building combine above on each update\n    private val contentStateWithDownloadProgress = combine(\n        readingListsContentState,\n        pageDownloadProgress\n            .sample(PROGRESS_SAMPLE_MILLIS.milliseconds)\n            .onStart { emit(pageDownloadProgress.value) }\n            .distinctUntilChanged()\n    ) { contentState, downloadProgress ->\n        contentState.copy(\n            pageDownloadProgress = if (contentState.selectedTab == SavedTab.ALL_ARTICLES) {\n                downloadProgress\n            } else {\n                emptyMap()\n            }\n        )\n    }.distinctUntilChanged()\n\n    private val recommendationPreferenceChanges = Prefs.observeKeys(\n        R.string.preference_key_recommended_reading_list_enabled,\n        R.string.preference_key_recommended_reading_list_new_list_generated,\n        R.string.preference_key_recommended_reading_list_articles_number,\n        R.string.preference_key_recommended_reading_list_source,\n        R.string.preference_key_recommended_reading_list_update_frequency\n    )\n\n    private val discoverCard = combine(\n        AppDatabase.instance.recommendedPageDao().getNewRecommendedPagesFlow(),\n        recommendationPreferenceChanges,\n        accountState\n    ) { recommendedPages, _, accountState ->\n        if (!Prefs.isRecommendedReadingListEnabled || recommendedPages.isEmpty()) {\n            null\n        } else {\n            RecommendedReadingListCard(\n                images = recommendedPages.mapNotNull { it.thumbUrl },\n                isNewListGenerated = Prefs.isNewRecommendedReadingListGenerated,\n                isUserLoggedIn = accountState.isLoggedIn,\n                userName = accountState.userName,\n                updateFrequency = Prefs.recommendedReadingListUpdateFrequency\n            )\n        }\n    }\n        .distinctUntilChanged()\n        .flowOn(Dispatchers.IO)\n\n    val uiState: StateFlow<ReadingListsUiState> =\n        combine(\n            contentStateWithDownloadProgress,\n            searchActive,\n            accountState,\n            Prefs.observeKeys(\n                R.string.preference_key_recommended_reading_list_onboarding_shown,\n                R.string.preference_key_sync_reading_lists,\n                R.string.preference_key_reading_list_sync_reminder_enabled,\n                R.string.preference_key_reading_list_login_reminder_enabled\n            ),\n            discoverCard\n        ) { contentState, isSearchActive, accountState, _, discoverCard ->\n            val isSearching = isSearchActive || !contentState.searchQuery.isNullOrEmpty()\n            val isCollections = contentState.selectedTab == SavedTab.COLLECTIONS\n            contentState.copy(\n                isSearchActive = isSearchActive,\n                onboarding = resolveOnboardingState(contentState.selectedTab, contentState.searchQuery, isSearchActive, accountState),\n                discoverCard = discoverCard.takeIf { isCollections && !isSearching },\n                showCollectionsBadge = contentState.showCollectionsBadge || discoverCard?.isNewListGenerated == true\n            )\n        }\n            .flowOn(Dispatchers.IO)\n            .stateIn(\n                scope = viewModelScope,\n                started = SharingStarted.WhileSubscribed(STOP_TIMEOUT_MILLIS),\n                initialValue = ReadingListsUiState()\n            )\n\n    fun setSearchQuery(query: String?) {\n        searchQuery.value = query\n    }\n\n    fun setSelectedTab(tab: SavedTab) {\n        selectedTab.value = tab\n    }\n\n    fun isSelectedTab(tab: SavedTab): Boolean {\n        return selectedTab.value == tab\n    }\n\n    fun setArticleFilter(filter: SavedArticleFilter) {\n        selectedArticleFilter.value = filter\n    }\n\n    fun getSelectedArticleFilter(): SavedArticleFilter {\n        return selectedArticleFilter.value\n    }\n\n    fun setSearchActive(active: Boolean) {\n        searchActive.value = active\n    }\n\n    fun setRefreshing(refreshing: Boolean) {\n        _isRefreshing.value = refreshing\n    }\n\n    fun refreshAccountState() {\n        accountState.value = readAccountState()\n    }\n\n    fun updatePageDownloadProgress(page: ReadingListPage) {\n        pageDownloadProgress.update { progressByPageId ->\n            if (progressByPageId[page.id] == page.downloadProgress) {\n                progressByPageId\n            } else {\n                progressByPageId + (page.id to page.downloadProgress)\n            }\n        }\n    }\n\n    fun setSelectionMode(enabled: Boolean) {\n        _selectionState.value = ReadingListsSelectionState(enabled = enabled)\n    }\n\n    fun toggleListSelection(listId: Long) {\n        val selectedListIds = _selectionState.value.selectedListIds.toMutableSet()\n        if (!selectedListIds.add(listId)) {\n            selectedListIds.remove(listId)\n        }\n        _selectionState.value = ReadingListsSelectionState(\n            enabled = true,\n            selectedListIds = selectedListIds\n        )\n    }\n\n    fun togglePageSelection(pageId: Long) {\n        val selectedPageIds = _selectionState.value.selectedPageIds.toMutableSet()\n        if (!selectedPageIds.add(pageId)) {\n            selectedPageIds.remove(pageId)\n        }\n        _selectionState.value = ReadingListsSelectionState(\n            enabled = true,\n            selectedPageIds = selectedPageIds\n        )\n    }\n\n    fun selectAllLists() {\n        _selectionState.value = ReadingListsSelectionState(\n            enabled = true,\n            selectedListIds = uiState.value.rows.filterIsInstance<ReadingListRow.ListRow>()\n                .mapTo(mutableSetOf()) { it.list.id }\n        )\n    }\n\n    fun clearListSelection() {\n        _selectionState.value = _selectionState.value.copy(selectedListIds = emptySet())\n    }\n\n    fun selectAllPages() {\n        _selectionState.value = ReadingListsSelectionState(\n            enabled = true,\n            selectedPageIds = uiState.value.rows.filterIsInstance<ReadingListRow.PageRow>()\n                .mapTo(mutableSetOf()) { it.page.id }\n        )\n    }\n\n    fun clearPageSelection() {\n        _selectionState.value = _selectionState.value.copy(selectedPageIds = emptySet())\n    }\n\n    fun refreshRecentPreviewSavedList() {\n        val receivedListId = Prefs.readingListRecentReceivedId\n        if (receivedListId == -1L || recentPreviewSavedState.value.newBadgeListId != null) {\n            return\n        }\n        recentPreviewSavedState.value = RecentPreviewSavedState(\n            pendingSnackbarListId = receivedListId,\n            newBadgeListId = receivedListId\n        )\n    }\n\n    fun consumePreviewSavedSnackbar(listId: Long) {\n        val currentState = recentPreviewSavedState.value\n        if (currentState.pendingSnackbarListId != listId) {\n            return\n        }\n        Prefs.receiveReadingListsData = null\n        Prefs.readingListRecentReceivedId = -1L\n        recentPreviewSavedState.value = currentState.copy(pendingSnackbarListId = null)\n    }\n\n    fun clearRecentPreviewSavedList() {\n        Prefs.readingListRecentReceivedId = -1L\n        recentPreviewSavedState.value = RecentPreviewSavedState()\n    }\n\n    fun containingLists(pageId: Long): List<ContainingList> {\n        return uiState.value.rows\n            .filterIsInstance<ReadingListRow.PageRow>()\n            .firstOrNull { it.page.id == pageId }\n            ?.containingLists\n            .orEmpty()\n    }\n\n    fun setSortMode(sortMode: Int) {\n        when (selectedTab.value) {\n            SavedTab.ALL_ARTICLES -> Prefs.setReadingListPageSortMode(sortMode)\n            SavedTab.COLLECTIONS -> Prefs.setReadingListSortMode(sortMode)\n        }\n    }\n\n    suspend fun loadReadingListWithPagesById(listId: Long): ReadingList? {\n        return AppDatabase.instance.readingListDao().getListWithPagesById(listId)?.toReadingList()\n    }\n\n    suspend fun loadReadingListsWithPagesByIds(listIds: Set<Long>): List<ReadingList> {\n        return AppDatabase.instance.readingListDao().getListsWithPagesByIds(listIds)\n            .map { it.toReadingList() }\n    }\n\n    suspend fun getReadingListsWithoutContents(): List<ReadingList> {\n        return AppDatabase.instance.readingListDao().getListsWithoutContents()\n    }\n\n    suspend fun createReadingList(title: String, description: String) {\n        AppDatabase.instance.readingListDao().createList(title, description)\n    }\n\n    suspend fun getPageById(pageId: Long): ReadingListPage? {\n        return AppDatabase.instance.readingListPageDao().getPageById(pageId)\n    }\n\n    suspend fun getPagesByIds(pageIds: Set<Long>): List<ReadingListPage> {\n        return AppDatabase.instance.readingListPageDao().getPagesByIds(pageIds)\n    }\n\n    suspend fun prepareSelectedPagesForDeletion(pageIds: Set<Long> = selectionState.value.selectedPageIds): SelectedPagesDeletion? {\n        val selectedRows = uiState.value.rows\n            .asSequence()\n            .filterIsInstance<ReadingListRow.PageRow>()\n            .filter { it.page.id in pageIds }\n            .toList()\n        if (selectedRows.isEmpty()) {\n            return null\n        }\n\n        val selectedPageKeys = selectedRows.mapTo(mutableSetOf()) { it.page.lang to it.page.apiTitle }\n        val containingListIds = selectedRows.flatMapTo(mutableSetOf()) { row ->\n            row.containingLists.map { it.id }\n        }\n        if (containingListIds.isEmpty()) {\n            return null\n        }\n\n        val readingLists = mutableListOf<ReadingList>()\n        AppDatabase.instance.readingListDao().getListsWithPagesByIds(containingListIds).forEach { relation ->\n            val pagesToDelete = relation.pages.filter { page ->\n                page.status != ReadingListPage.STATUS_QUEUE_FOR_DELETE &&\n                    (page.lang to page.apiTitle) in selectedPageKeys\n            }\n            if (pagesToDelete.isNotEmpty()) {\n                relation.list.pages.clear()\n                relation.list.pages.addAll(pagesToDelete)\n                readingLists.add(relation.list)\n            }\n        }\n\n        return SelectedPagesDeletion(\n            selectedPageCount = selectedRows.size,\n            readingLists = readingLists\n        )\n    }\n\n    private fun resolveOnboardingState(\n        selectedTab: SavedTab,\n        query: String?,\n        isSearchActive: Boolean,\n        accountState: ReadingListsAccountState\n    ): OnboardingState {\n        if (isSearchActive || !query.isNullOrEmpty()) {\n            return OnboardingState.None\n        }\n\n        return when (selectedTab) {\n            SavedTab.ALL_ARTICLES -> when {\n                accountState.isLoggedIn && !accountState.isTemporaryAccount && !Prefs.isReadingListSyncEnabled &&\n                        Prefs.isReadingListSyncReminderEnabled && !RemoteConfig.config.disableReadingListSync -> {\n                    OnboardingState.SyncReminder\n                }\n                (!accountState.isLoggedIn || accountState.isTemporaryAccount) && Prefs.isReadingListLoginReminderEnabled &&\n                        !RemoteConfig.config.disableReadingListSync -> {\n                    OnboardingState.LoginReminder\n                }\n                else -> OnboardingState.None\n            }\n            SavedTab.COLLECTIONS -> {\n                if (!Prefs.isRecommendedReadingListOnboardingShown) {\n                    OnboardingState.RecommendedReadingList\n                } else {\n                    OnboardingState.None\n                }\n            }\n        }\n    }\n\n    private fun readAccountState(): ReadingListsAccountState {\n        return ReadingListsAccountState(\n            isLoggedIn = AccountUtil.isLoggedIn,\n            isTemporaryAccount = AccountUtil.isTemporaryAccount,\n            userName = AccountUtil.userName\n        )\n    }\n\n    private fun buildRows(\n        allLists: MutableList<ReadingList>,\n        tab: SavedTab,\n        query: String?,\n        articleFilter: SavedArticleFilter,\n        recentPreviewSavedId: Long?,\n        sortMode: Int\n    ): List<ReadingListRow> {\n        if (!query.isNullOrEmpty()) {\n            return buildSearchRows(allLists, tab, query, articleFilter, recentPreviewSavedId)\n        }\n\n        return when (tab) {\n            SavedTab.COLLECTIONS -> buildCollectionsRows(allLists, recentPreviewSavedId, sortMode)\n            SavedTab.ALL_ARTICLES -> buildArticleRows(allLists, articleFilter = articleFilter, sortMode = sortMode)\n        }\n    }\n\n    private fun buildCollectionsRows(\n        lists: MutableList<ReadingList>,\n        recentPreviewSavedId: Long?,\n        sortMode: Int\n    ): List<ReadingListRow> {\n        ReadingList.sort(lists, sortMode)\n        lists.removeAll { it.isDefault }\n        return lists.map { ReadingListRow.ListRow(it.toUiModel(recentPreviewSavedId)) }\n    }\n\n    private fun buildSearchRows(\n        lists: List<ReadingList>,\n        tab: SavedTab,\n        query: String,\n        articleFilter: SavedArticleFilter,\n        recentPreviewSavedId: Long?\n    ): List<ReadingListRow> {\n        val normalizedQuery = StringUtils.stripAccents(query)\n        return when (tab) {\n            SavedTab.COLLECTIONS -> lists\n                .filter {\n                    !it.isDefault &&\n                        it.accentInvariantTitle.contains(normalizedQuery, ignoreCase = true)\n                }\n                .map { ReadingListRow.ListRow(it.toUiModel(recentPreviewSavedId)) }\n            SavedTab.ALL_ARTICLES -> buildArticleRows(lists, normalizedQuery, articleFilter)\n        }\n    }\n\n    /**\n     * Every saved article across [lists] as [ReadingListRow.PageRow]s, de-duplicated by lang + API\n     * title so an article on multiple lists appears once, annotated with the lists that contain it.\n     * When [titleFilter] is non-null, only articles whose title contains it (accent-insensitive) are kept.\n     */\n    private fun buildArticleRows(\n        lists: List<ReadingList>,\n        titleFilter: String? = null,\n        articleFilter: SavedArticleFilter = SavedArticleFilter.ALL_ARTICLES,\n        sortMode: Int? = null\n    ): List<ReadingListRow.PageRow> {\n        val selectedArticles = linkedMapOf<Pair<String, String>, ArticleRowData>()\n        lists.forEach { list ->\n            list.pages.forEach { page ->\n                val matches = titleFilter == null ||\n                    page.accentInvariantTitle.contains(titleFilter, ignoreCase = true)\n                if (matches) {\n                    selectedArticles.getOrPut(page.lang to page.apiTitle) { ArticleRowData(page) }\n                }\n            }\n        }\n\n        if (selectedArticles.isEmpty()) {\n            return emptyList()\n        }\n\n        lists.forEach { list ->\n            val containingList = ContainingList(list.id, list.title, list.isDefault)\n            list.pages.forEach { page ->\n                selectedArticles[page.lang to page.apiTitle]?.containingLists?.add(containingList)\n            }\n        }\n\n        val filteredArticles = selectedArticles.values.filter { article ->\n            articleFilter == SavedArticleFilter.ALL_ARTICLES ||\n                article.containingLists.all { it.isDefault }\n        }\n        val orderedPages = filteredArticles.mapTo(mutableListOf()) { it.page }\n        sortMode?.let { sortArticles(orderedPages, it) }\n\n        return orderedPages.map { page ->\n            val article = selectedArticles.getValue(page.lang to page.apiTitle)\n            ReadingListRow.PageRow(\n                page.toUiModel(),\n                article.containingLists\n            )\n        }\n    }\n\n    private fun sortArticles(pages: MutableList<ReadingListPage>, sortMode: Int) {\n        when (sortMode) {\n            ReadingList.SORT_BY_NAME_ASC -> pages.sortWith { lhs: ReadingListPage, rhs: ReadingListPage -> lhs.accentInvariantTitle.compareTo(rhs.accentInvariantTitle, true) }\n            ReadingList.SORT_BY_NAME_DESC -> pages.sortWith { lhs: ReadingListPage, rhs: ReadingListPage -> rhs.accentInvariantTitle.compareTo(lhs.accentInvariantTitle, true) }\n            ReadingList.SORT_BY_RECENT_ASC -> pages.sortWith { lhs: ReadingListPage, rhs: ReadingListPage -> rhs.mtime.compareTo(lhs.mtime) }\n            ReadingList.SORT_BY_RECENT_DESC -> pages.sortWith { lhs: ReadingListPage, rhs: ReadingListPage -> lhs.mtime.compareTo(rhs.mtime) }\n        }\n    }\n\n    private fun MutableList<ReadingList>.removeEmptyDefaultList() {\n        if (size == 1 && this[0].isDefault && this[0].pages.isEmpty()) {\n            removeAt(0)\n        }\n    }\n\n    private fun ReadingList.toUiModel(recentPreviewSavedId: Long?): ReadingListUiModel {\n        return ReadingListUiModel(\n            id = id,\n            title = title,\n            description = description,\n            isDefault = isDefault,\n            totalPages = pages.size,\n            sizeBytesFromPages = sizeBytesFromPages,\n            thumbUrls = pages.mapNotNull { it.thumbUrl }.filterNot { it.isEmpty() },\n            isNew = id == recentPreviewSavedId\n        )\n    }\n\n    private fun ReadingListPage.toUiModel(): ReadingListPageUiModel {\n        val saving = saving\n        return ReadingListPageUiModel(\n            id = id,\n            title = displayTitle,\n            description = description,\n            thumbUrl = thumbUrl,\n            lang = lang,\n            apiTitle = apiTitle,\n            offline = offline,\n            saving = saving,\n            isAvailable = WikipediaApp.instance.isOnline || (offline && !saving)\n        )\n    }\n\n    companion object {\n        private const val STOP_TIMEOUT_MILLIS = 5000L\n        private const val SEARCH_DEBOUNCE_MILLIS = 150L\n        private const val PROGRESS_SAMPLE_MILLIS = 150L\n    }\n}","file":"app/src/main/java/org/wikipedia/readinglist/ReadingListsViewModel.kt","kind":"class","line":41,"members":{"PROGRESS_SAMPLE_MILLIS":[558,558],"SEARCH_DEBOUNCE_MILLIS":[557,557],"STOP_TIMEOUT_MILLIS":[556,556],"_isRefreshing":[62,62],"_selectionState":[65,65],"accountState":[59,59],"buildArticleRows":[463,510],"buildCollectionsRows":[434,442],"buildRows":[416,432],"buildSearchRows":[444,461],"clearListSelection":[257,259],"clearPageSelection":[269,271],"clearRecentPreviewSavedList":[294,297],"consumePreviewSavedSnackbar":[284,292],"containingLists":[299,305],"contentMode":[51,55],"contentStateWithDownloadProgress":[105,122],"createReadingList":[327,329],"debouncedSearchQuery":[44,46],"discoverCard":[132,150],"getPageById":[331,333],"getPagesByIds":[335,337],"getReadingListsWithoutContents":[323,325],"getSelectedArticleFilter":[197,199],"isRefreshing":[63,63],"isSelectedTab":[189,191],"loadReadingListWithPagesById":[314,316],"loadReadingListsWithPagesByIds":[318,321],"pageDownloadProgress":[60,60],"prepareSelectedPagesForDeletion":[339,374],"readAccountState":[408,414],"readingListsContentState":[68,103],"recentPreviewSavedState":[57,57],"recommendationPreferenceChanges":[124,130],"refreshAccountState":[209,211],"refreshRecentPreviewSavedList":[273,282],"removeEmptyDefaultList":[521,525],"resolveOnboardingState":[376,406],"searchActive":[47,47],"searchQuery":[43,43],"selectAllLists":[249,255],"selectAllPages":[261,267],"selectedArticleFilter":[49,49],"selectedTab":[48,48],"selectionState":[66,66],"setArticleFilter":[193,195],"setRefreshing":[205,207],"setSearchActive":[201,203],"setSearchQuery":[181,183],"setSelectedTab":[185,187],"setSelectionMode":[223,225],"setSortMode":[307,312],"sortArticles":[512,519],"toUiModel":[527,538],"toggleListSelection":[227,236],"togglePageSelection":[238,247],"uiState":[152,179],"updatePageDownloadProgress":[213,221]},"supers":["ViewModel()"]},"SavedPageSyncService":{"appearsIn":[["index","h-services","Services \u00b7 what the screens share"],["saved","h-classes","Logic \u00b7 class diagram"],["saved","h-sequence","Save an article and sync it \u00b7 sequence"]],"code":"class SavedPageSyncService(context: Context, params: WorkerParameters) : CoroutineWorker(context, params) {\n    private val savedPageSyncNotification = SavedPageSyncNotification.instance\n\n    override suspend fun doWork(): Result {\n        return withContext(Dispatchers.IO) {\n            if (ReadingListSyncAdapter.inProgress()) {\n                // Reading list sync was started in the meantime, so bail.\n                return@withContext Result.success()\n            }\n            val pagesToSave = AppDatabase.instance.readingListPageDao().getAllPagesToBeForcedSave().toMutableList()\n            if ((!Prefs.isDownloadOnlyOverWiFiEnabled || DeviceUtil.isOnWiFi) &&\n                Prefs.isDownloadingReadingListArticlesEnabled) {\n                pagesToSave.addAll(AppDatabase.instance.readingListPageDao().getAllPagesToBeSaved())\n            }\n            val pagesToUnSave = AppDatabase.instance.readingListPageDao().getAllPagesToBeUnsaved()\n            val pagesToDelete = AppDatabase.instance.readingListPageDao().getAllPagesToBeDeleted()\n            var shouldSendSyncEvent = false\n            try {\n                AppDatabase.instance.offlineObjectDao().deleteObjectsForPageId(pagesToDelete.map { it.id })\n                AppDatabase.instance.offlineObjectDao().deleteObjectsForPageId(pagesToUnSave.map { it.id })\n            } catch (e: Exception) {\n                L.e(\"Error while deleting page: \" + e.message)\n            } finally {\n                if (pagesToDelete.isNotEmpty()) {\n                    AppDatabase.instance.readingListPageDao().purgeDeletedPages()\n                    shouldSendSyncEvent = true\n                }\n                if (pagesToUnSave.isNotEmpty()) {\n                    AppDatabase.instance.readingListPageDao().updateStatus(\n                        oldStatus = ReadingListPage.STATUS_SAVED,\n                        newStatus = ReadingListPage.STATUS_QUEUE_FOR_SAVE,\n                        offline = false\n                    )\n                    shouldSendSyncEvent = true\n                }\n            }\n            val itemsTotal = pagesToSave.size\n            if (itemsTotal > 0) {\n                shouldSendSyncEvent = true\n            }\n            var itemsSaved = 0\n            try {\n                savePages(pagesToSave)\n            } finally {\n                if (savedPageSyncNotification.isSyncPaused()) {\n                    savedPageSyncNotification.setNotificationPaused(applicationContext, itemsTotal, itemsSaved)\n                } else {\n                    savedPageSyncNotification.cancelNotification(applicationContext)\n                    savedPageSyncNotification.setSyncCanceled(false)\n                    if (shouldSendSyncEvent) {\n                        sendSyncEvent()\n                    }\n                }\n            }.also { itemsSaved = it }\n            Result.success()\n        }\n    }\n\n    private suspend fun savePages(queue: MutableList<ReadingListPage>): Int {\n        return withContext(Dispatchers.IO) {\n            val itemsTotal = queue.size\n            var itemsSaved = 0\n            while (queue.isNotEmpty()) {\n\n                // Pick off the DB row that we'll be working on...\n                val page = queue.removeAt(0)\n                if (savedPageSyncNotification.isSyncPaused()) {\n                    // Remaining transactions will be picked up again when the service is resumed.\n                    break\n                } else if (savedPageSyncNotification.isSyncCanceled()) {\n                    // Mark remaining pages as online-only!\n                    queue.add(page)\n                    AppDatabase.instance.readingListPageDao().markPagesForOffline(queue, offline = false, forcedSave = false)\n                    break\n                }\n                savedPageSyncNotification.setNotificationProgress(applicationContext, itemsTotal, itemsSaved)\n                var success = false\n                var totalSize = 0L\n                try {\n                    // Lengthy operation during which the db state may change...\n                    totalSize = savePageFor(page)\n                    success = true\n                } catch (e: CancellationException) {\n                    throw e\n                } catch (_: InterruptedException) {\n                        // fall through\n                } catch (e: Exception) {\n                    // This can be an IOException from the storage media, or several types\n                    // of network exceptions from malformed URLs, timeouts, etc.\n                    L.e(e)\n\n                    // If we're offline, or if there's a transient network error, then don't do\n                    // anything.  Otherwise...\n                    if (!ThrowableUtil.isOffline(e) && !ThrowableUtil.isTimeout(e) && !ThrowableUtil.isNetworkError(e)) {\n                        // If it's not a transient network error (e.g. a 404 status response), it implies\n                        // that there's no way to fetch the page next time, or ever, therefore let's mark\n                        // it as \"successful\" so that it won't be retried again.\n                        success = true\n                        if (e !is HttpStatusException) {\n                            // And if it's something other than an HTTP status, let's log it and see what it is.\n                            L.logRemoteError(e)\n                        }\n                    }\n                }\n                if (ReadingListSyncAdapter.inProgress()) {\n                    // Reading list sync was started in the meantime, so bail.\n                    break\n                }\n                if (success) {\n                    page.status = ReadingListPage.STATUS_SAVED\n                    page.sizeBytes = totalSize\n                    AppDatabase.instance.readingListPageDao().updateReadingListPage(page)\n                    itemsSaved++\n                    sendSyncEvent()\n                }\n            }\n            itemsSaved\n        }\n    }\n\n    @Throws(Exception::class)\n    private suspend fun savePageFor(page: ReadingListPage): Long {\n        return withContext(Dispatchers.IO) {\n            val pageTitle = ReadingListPage.toPageTitle(page)\n\n            val summaryCall = async { ServiceFactory.getRest(pageTitle.wikiSite).getPageSummary(pageTitle.prefixedText,\n                cacheControl = OkHttpConnectionFactory.CACHE_CONTROL_FORCE_NETWORK.toString(),\n                saveHeader = OfflineCacheInterceptor.SAVE_HEADER_SAVE, langHeader = pageTitle.wikiSite.languageCode,\n                titleHeader = UriUtil.encodeURL(pageTitle.prefixedText)) }\n\n            val mediaListCall = async { ServiceFactory.getRest(pageTitle.wikiSite).getMediaList(pageTitle.prefixedText,\n                cacheControl = OkHttpConnectionFactory.CACHE_CONTROL_FORCE_NETWORK.toString(),\n                saveHeader = OfflineCacheInterceptor.SAVE_HEADER_SAVE, langHeader = pageTitle.wikiSite.languageCode,\n                titleHeader = UriUtil.encodeURL(pageTitle.prefixedText)) }\n\n            val mobileHTMLCall = async { reqMobileHTML(pageTitle) }\n\n            val summaryResponse = summaryCall.await()\n            val mediaListResponse = mediaListCall.await()\n            val mobileHTML = mobileHTMLCall.await()\n\n            page.downloadProgress = MEDIA_LIST_PROGRESS\n            FlowEventBus.post(PageDownloadEvent(page))\n\n            val fileUrls = mutableSetOf<String>()\n            // download css and javascript assets\n            fileUrls.addAll(PageComponentsUrlParser.parse(mobileHTML,\n                pageTitle.wikiSite).filter { url -> url.isNotEmpty() })\n            if (Prefs.isImageDownloadEnabled) {\n                // download thumbnail and lead image\n                if (!summaryResponse.thumbnailUrl.isNullOrEmpty()) {\n                    page.thumbUrl = UriUtil.resolveProtocolRelativeUrl(pageTitle.wikiSite, summaryResponse.thumbnailUrl.orEmpty())\n                    val existingPageImage = AppDatabase.instance.pageImagesDao()\n                        .findItemsBy(pageTitle.wikiSite.languageCode, pageTitle.namespace, pageTitle.prefixedText)\n                        .firstOrNull()\n\n                    AppDatabase.instance.pageImagesDao().insertPageImage(PageImage(\n                        pageTitle.wikiSite.languageCode,\n                        pageTitle.namespace,\n                        page.apiTitle,\n                        page.thumbUrl.orEmpty(),\n                        summaryResponse.description,\n                        existingPageImage?.timeSpentSec ?: 0,\n                        summaryResponse.coordinates?.latitude ?: 0.0,\n                        summaryResponse.coordinates?.longitude ?: 0.0\n                    ))\n                    fileUrls.add(UriUtil.resolveProtocolRelativeUrl(\n                        ImageUrlUtil.getUrlForPreferredSize(page.thumbUrl.orEmpty(), Constants.PREFERRED_CARD_THUMBNAIL_SIZE)))\n                }\n\n                // download article images\n                for (item in mediaListResponse.getItems(\"image\")) {\n                    item.srcSets.let {\n                        fileUrls.add(item.getImageUrl(DimenUtil.densityScalar))\n                    }\n                }\n            }\n            page.displayTitle = summaryResponse.displayTitle.orEmpty()\n            page.description = summaryResponse.description.orEmpty()\n\n            reqSaveFiles(page, pageTitle, fileUrls)\n\n            val totalSize = AppDatabase.instance.offlineObjectDao().getTotalBytesForPageId(page.id)\n\n            L.i(\"Saved page \" + pageTitle.prefixedText + \" (\" + totalSize + \")\")\n\n            totalSize\n        }\n    }\n\n    private suspend fun reqMobileHTML(pageTitle: PageTitle): String {\n        val request = makeUrlRequest(pageTitle.wikiSite,\n                ServiceFactory.getRestBasePath(pageTitle.wikiSite) +\n                        RestService.PAGE_HTML_ENDPOINT + UriUtil.encodeURL(pageTitle.prefixedText),\n                pageTitle).build()\n        return withContext(Dispatchers.IO) {\n            OkHttpConnectionFactory.client.newCall(request).execute().use { it.body.string() }\n        }\n    }\n\n    @Throws(IOException::class, InterruptedException::class)\n    private suspend fun reqSaveFiles(page: ReadingListPage, pageTitle: PageTitle, urls: Set<String>) {\n        val numOfImages = urls.size\n        var percentage = MEDIA_LIST_PROGRESS.toFloat()\n        val updateRate = (CircularProgressBar.MAX_PROGRESS - percentage) / numOfImages\n\n        withContext(Dispatchers.IO) {\n            for (url in urls) {\n                if (savedPageSyncNotification.isSyncPaused() || savedPageSyncNotification.isSyncCanceled()) {\n                    throw InterruptedException(\"Sync paused or cancelled.\")\n                }\n                try {\n                    reqSaveUrl(pageTitle, page.wiki, url)\n                    percentage += updateRate\n                    page.downloadProgress = percentage.toInt()\n                    FlowEventBus.post(PageDownloadEvent(page))\n                } catch (e: CancellationException) {\n                    throw e\n                } catch (e: Exception) {\n                    if (isRetryable(e)) {\n                        throw e\n                    }\n                }\n            }\n            page.downloadProgress = CircularProgressBar.MAX_PROGRESS\n            FlowEventBus.post(PageDownloadEvent(page))\n        }\n    }\n\n    @Throws(IOException::class)\n    private suspend fun reqSaveUrl(pageTitle: PageTitle, wiki: WikiSite, url: String) {\n        val request = makeUrlRequest(wiki, url, pageTitle).build()\n        withContext(Dispatchers.IO) {\n            OkHttpConnectionFactory.client.newCall(request).execute().use { response ->\n                // Read the entirety of the response, so that it's written to cache by the interceptor.\n                response.body.source().readAll(object : Sink {\n                    override fun write(source: Buffer, byteCount: Long) {}\n                    override fun flush() {}\n                    override fun timeout(): Timeout {\n                        return Timeout()\n                    }\n\n                    override fun close() {}\n                })\n            }\n        }\n    }\n\n    private fun makeUrlRequest(wiki: WikiSite, url: String, pageTitle: PageTitle): Request.Builder {\n        return Request.Builder().cacheControl(OkHttpConnectionFactory.CACHE_CONTROL_FORCE_NETWORK).url(UriUtil.resolveProtocolRelativeUrl(wiki, url))\n                .addHeader(\"Accept-Language\", WikipediaApp.instance.getAcceptLanguage(pageTitle.wikiSite))\n                .addHeader(OfflineCacheInterceptor.SAVE_HEADER, OfflineCacheInterceptor.SAVE_HEADER_SAVE)\n                .addHeader(OfflineCacheInterceptor.LANG_HEADER, pageTitle.wikiSite.languageCode)\n                .addHeader(OfflineCacheInterceptor.TITLE_HEADER, UriUtil.encodeURL(pageTitle.prefixedText))\n    }\n\n    private fun isRetryable(t: Throwable): Boolean {\n        // \"Retryable\" in this case refers to exceptions that will be rethrown up to the\n        // outer exception handler, so that the entire page can be retried on the next pass\n        // of the sync service.\n\n        // Errors that do *not* qualify for retrying include:\n        // - IllegalArgumentException (thrown for any kind of malformed URL)\n        // - HTTP 404 status (for nonexistent media)\n        return !(t is IllegalArgumentException || ThrowableUtil.is404(t))\n    }\n\n    companion object {\n        private const val WORK_NAME = \"savePageSyncService\"\n        private const val ENQUEUE_DELAY = 2L\n        const val MEDIA_LIST_PROGRESS = 30\n\n        fun enqueue() {\n            if (ReadingListSyncAdapter.inProgress()) {\n                return\n            }\n            val constraints = Constraints.Builder()\n                .setRequiredNetworkType(NetworkType.CONNECTED)\n                .build()\n            val workRequest = OneTimeWorkRequestBuilder<SavedPageSyncService>()\n                .setInitialDelay(ENQUEUE_DELAY, TimeUnit.SECONDS)\n                .setConstraints(constraints)\n                .build()\n            WorkManager.getInstance(WikipediaApp.instance)\n                .enqueueUniqueWork(WORK_NAME, ExistingWorkPolicy.REPLACE, workRequest)\n        }\n\n        fun sendSyncEvent(showMessage: Boolean = false) {\n            // Note: this method posts from a background thread but subscribers expect events to be\n            // received on the main thread.\n            FlowEventBus.post(ReadingListSyncEvent(showMessage))\n        }\n    }\n}","file":"app/src/main/java/org/wikipedia/savedpages/SavedPageSyncService.kt","kind":"class","line":46,"members":{"ENQUEUE_DELAY":[315,315],"MEDIA_LIST_PROGRESS":[316,316],"WORK_NAME":[314,314],"context":[46,46],"doWork":[49,102],"enqueue":[318,331],"isRetryable":[302,311],"makeUrlRequest":[294,300],"params":[46,46],"reqMobileHTML":[236,244],"reqSaveFiles":[246,273],"reqSaveUrl":[275,292],"savePageFor":[166,234],"savePages":[104,164],"savedPageSyncNotification":[47,47],"sendSyncEvent":[333,337]},"supers":["CoroutineWorker(context, params)"]},"SavedTab":{"appearsIn":[["saved","h-classes","Logic \u00b7 class diagram"]],"code":"enum class SavedTab {\n    ALL_ARTICLES,\n    COLLECTIONS\n}","file":"app/src/main/java/org/wikipedia/readinglist/ReadingListsViewModel.kt","kind":"enum","line":31,"members":{"ALL_ARTICLES":[32,32],"COLLECTIONS":[33,33]},"supers":[]},"SavedTabBar":{"appearsIn":[["saved","h-widgets","Screen \u00b7 composition"]],"code":"@Composable\nprivate fun SavedTabBar(\n    selectedTab: SavedTab,\n    modifier: Modifier = Modifier,\n    showCollectionsBadge: Boolean = false,\n    onSelectTab: (SavedTab) -> Unit = {}\n) {\n    Column(modifier = modifier.fillMaxWidth()) {\n        Row(modifier = Modifier.fillMaxWidth()) {\n            SavedTab.entries.forEach { tab ->\n                val isSelected = tab == selectedTab\n                val label = when (tab) {\n                    SavedTab.ALL_ARTICLES -> stringResource(R.string.reading_lists_tab_all_articles)\n                    SavedTab.COLLECTIONS -> stringResource(R.string.reading_lists_tab_collections)\n                }\n                Box(\n                    modifier = Modifier\n                        .weight(1f)\n                        .clickable { onSelectTab(tab) }\n                        .padding(top = 12.dp),\n                    contentAlignment = Alignment.TopCenter\n                ) {\n                    // Width wraps the label so the underline matches the text width, not the whole tab.\n                    Column(\n                        horizontalAlignment = Alignment.CenterHorizontally,\n                        modifier = Modifier.width(IntrinsicSize.Max)\n                    ) {\n                        Row(verticalAlignment = Alignment.CenterVertically) {\n                            Text(\n                                text = label,\n                                color = if (isSelected) {\n                                    WikipediaTheme.colors.progressiveColor\n                                } else {\n                                    WikipediaTheme.colors.primaryColor\n                                },\n                                style = MaterialTheme.typography.titleSmall\n                            )\n                            if (tab == SavedTab.COLLECTIONS && showCollectionsBadge) {\n                                Spacer(modifier = Modifier.width(6.dp))\n                                Box(\n                                    modifier = Modifier\n                                        .size(6.dp)\n                                        .clip(CircleShape)\n                                        .background(WikipediaTheme.colors.destructiveColor)\n                                )\n                            }\n                        }\n                        Spacer(modifier = Modifier.height(10.dp))\n                        Box(\n                            modifier = Modifier\n                                .fillMaxWidth()\n                                .height(3.dp)\n                                .clip(RoundedCornerShape(topStart = 3.dp, topEnd = 3.dp))\n                                .background(\n                                    if (isSelected) WikipediaTheme.colors.progressiveColor else Color.Transparent\n                                )\n                        )\n                    }\n                }\n            }\n        }\n        HorizontalDivider(\n            color = WikipediaTheme.colors.borderColor,\n            thickness = 0.5.dp\n        )\n    }\n}","file":"app/src/main/java/org/wikipedia/readinglist/compose/ReadingListsScreen.kt","kind":"composable function","line":160,"members":{},"supers":[]}},"sourceUrl":"https://github.com/wikimedia/apps-android-wikipedia/blob/a94b2dd658c6a6bdc7f131c5bf5fa97ba9ae6bfd/"};
